  const tokens = []; let present = false;
  try {
    const j = JSON.parse(fs.readFileSync(CRED_FILE, "utf8"));
    present = true;
    const o = j.claudeAiOauth || j;
    for (const k of ["accessToken", "refreshToken"]) if (typeof o[k] === "string" && o[k].length >= 16) tokens.push(o[k]);
  } catch { /* no login file: the env token (if any) is the credential */ }
