  const ns = rec.assets ? rec.assets.namespace : null;
  const t = texturesOn || keptTex ? TX.checkWorkspaceTextures(ws, { namespace: ns || "nx_00000000", javaFiles: ns && texturesOn ? java : [] }) : { results: [], soft: [] };
  const textures = t.results.filter((r) => r.ok || (!texturesOn && r.spec)).map((r) => ({ name: r.name, path: r.rel, sha256: r.sha256, spec: r.spec, quality: r.quality }));
  // kept sound specs are re-checked with the library allowed (they were valid when made; keeping is never gated)
  const sd = soundsOn || keptSnd ? SND.checkWorkspaceSounds(ws, { namespace: ns || "nx_00000000", javaFiles: ns && soundsOn ? java : [], library: soundsOn ? libOn(rec) : true }) : { results: [], soft: [] };
  const sounds = sd.results.filter((r) => r.ok || (!soundsOn && r.spec)).map((r) => ({
    key: r.name, path: r.rel, sha256: r.sha256, spec: r.spec,
    quality: { version: "ss-1", stage: "spec", estimatedSeconds: r.seconds, note: "rendered, measured and loudness-checked by Nxeon's render host after the build" },
    events: r.spec.events.map((e) => ({ event: e.event, key: `${ns}:${r.name}.${e.event}`, role: e.role, category: e.category, subtitle: e.subtitle, variants: e.variants.length })),
  }));
  const downgraded = rec.assetDowngrades || [];
  const warnings = [
    ...downgraded.map((d) => (d.kind === "sound"
      ? `Custom sound set "${d.name}" was left out: ${String(d.reason).replace(/^assets\/sounds\/[a-z0-9_]+\.json:?\s*/, "")}. Its events play no custom sound.`
      : `Custom texture "${d.name}" was left out: ${String(d.reason).replace(/^assets\/textures\/[a-z0-9_]+\.json:?\s*/, "")}. Items that use it show without a custom look.`)),
    ...(texturesOn ? t.soft.map((x) => `Texture check: ${x}`) : []),
    ...(soundsOn ? sd.soft.map((x) => `Sound check: ${x}`) : []),
  ].slice(0, 30);
  return {
    namespace: ns, promptVersion: texturesOn || soundsOn ? ASSET_PROMPT_VERSION : null, qualityVersion: TX.QUALITY_VERSION,
    kept: !texturesOn && !soundsOn, keptKinds: [...(keptTex && !texturesOn ? ["texture"] : []), ...(keptSnd && !soundsOn ? ["sound"] : [])],
    textures, sounds, downgraded, warnings,
  };
}

function validate(ws, rec) {
  const problems = [];
  const fixes = []; // mechanical fixes made here (reported to the model only if a repair follows)
  const res = path.join(ws, "src/main/resources");
  const ymlPath = path.join(res, "plugin.yml");
  if (fs.existsSync(path.join(res, "paper-plugin.yml"))) problems.push("Use plugin.yml, not paper-plugin.yml: delete src/main/resources/paper-plugin.yml.");
  if (!fs.existsSync(ymlPath)) return { problems: ["src/main/resources/plugin.yml is missing."], yml: null };
  let yml;
  try { yml = YAML.parse(fs.readFileSync(ymlPath, "utf8")); } catch (e) { return { problems: [`plugin.yml is not valid YAML: ${e.message}`], yml: null }; }
  if (!yml || typeof yml !== "object") return { problems: ["plugin.yml is empty."], yml: null };
  if (!/^[A-Za-z0-9_]{1,40}$/.test(String(yml.name || ""))) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
  if (!yml.version) problems.push("plugin.yml needs a version.");
  const main = String(yml.main || "");
  if (!/^[a-zA-Z_][\w]*(\.[a-zA-Z_][\w]*)+$/.test(main)) problems.push("plugin.yml main must be a fully-qualified class name.");
  else if (!fs.existsSync(path.join(ws, "src/main/java", main.replace(/\./g, "/") + ".java"))) problems.push(`plugin.yml main is ${main} but src/main/java/${main.replace(/\./g, "/")}.java does not exist.`);
  if (/^(org\.bukkit|io\.papermc|net\.minecraft|com\.destroystokyo|net\.kyori)\./.test(main)) problems.push("The main class must be in your own package.");
  // Pin api-version to the exact Paper version the jar was compiled against.
  // With '1.21' a 1.21.11 build also "loads" on a 1.21.1 server and then crashes
  // on API that version does not have (the Growth incident: Attribute.SCALE ->
  // InvalidPluginException initializing the main class). With '1.21.11' Paper
  // 1.21.1 refuses it cleanly ("Unsupported API version 1.21.11") while 1.21.11+
  // load it. Verified on real Paper 1.21.1 / 1.21.8 / 1.21.11 servers 2026-10-07.
  const apiVersion = rec.mcVersion;
  if (String(yml["api-version"] || "") !== apiVersion) {
    // Mechanical fix, not worth a model round-trip.
    yml["api-version"] = apiVersion;
    fs.writeFileSync(ymlPath, YAML.stringify(yml));
  }
  // getCommand("x") without a plugin.yml entry returns null at runtime -> NPE on enable.
  const declared = new Set(Object.keys((yml.commands && typeof yml.commands === "object") ? yml.commands : {}).map((s) => s.toLowerCase()));
  const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
  if (!java.length) problems.push("No Java source files were written.");
  for (const f of java) {
    const text = fs.readFileSync(f.abs, "utf8");
    for (const m of text.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) {
      if (!declared.has(m[1].toLowerCase())) problems.push(`${f.rel} calls getCommand("${m[1]}") but plugin.yml has no command "${m[1]}" (it would crash on enable).`);
    }
    if (/^\s*public\s+final\s+class\s+\w+\s+extends\s+JavaPlugin/m.test(text)) {
      // Mechanical (0.5): drop the modifier instead of spending a model repair on it.
      const fixed = AUTOFIX ? AF.fixMainFinal(text) : null;
      if (fixed) {
        fs.writeFileSync(f.abs, fixed);
        fixes.push({ file: f.rel, line: 0, kind: "main-final", from: "public final class", to: "public class" });
      } else problems.push(`${f.rel}: the main class must not be final.`);
    }
  }
  const total = listFiles(ws, "src").reduce((a, f) => a + f.size, 0);
  if (total > 1.5 * 1024 * 1024) problems.push("The source is too large (over 1.5 MB).");
  return { problems: [...new Set(problems)], yml, fixes };
}


async function compile(ws, rec, ctl) {
  const out = path.join(ws, "build/classes");
  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
  const cp = fs.readFileSync(path.join(CP_DIR, `${rec.mcVersion}.txt`), "utf8").trim();
  const sources = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")).map((f) => f.abs);
  const tc = javacFor(rec.mcVersion);
  const r = await run(tc.javac, ["-J-Xmx768m", "--release", tc.release, "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", out, ...sources],
    { cwd: ws, env: childEnv(false), timeout: 180000, track: ctl });
  ctl.child = null;
  const output = (r.err + r.out).split(ws + "/").join("");
  if (r.code !== 0) return { ok: false, errors: output.slice(0, 12000) };
  // Resources (plugin.yml, config.yml, ...)
  copyDir(path.join(ws, "src/main/resources"), out);
  const jar = path.join(ws, "build/plugin.jar");
  // Reproducible jar: sorted entries + a fixed entry timestamp (JDK 19+ `--date`), so the same source gives the same bytes.
  // If this JDK rejects --date, fall back to the old unsorted form rather than failing the build.
  const rel = (f) => f.rel.slice("build/classes/".length);
  const entries = jarEntries(listFiles(ws, "build/classes").map(rel));
  let j = await run("jar", jarArgs(jar, out, entries), { cwd: ws, env: childEnv(false), timeout: 60000 });
  if (j.code !== 0 && /--date|illegal option|unrecognized option|usage/i.test(j.err + j.out)) {
    j = await run("jar", ["--create", "--file", jar, "-C", out, "."], { cwd: ws, env: childEnv(false), timeout: 60000 });
  }
  if (j.code !== 0) return { ok: false, errors: j.err.slice(0, 4000) };
  const warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 10);
  return { ok: true, jar, classes: out, warnings };
}

// ------------------------------------------------------------ pipeline ----
async function runBuild(rec) {
  const ctl = { child: null, cancelled: false };
  running.set(rec.id, ctl);
  const started = Date.now();
  rec.startedAt = now();
  const ws = path.join(WORK, rec.id);
  const finalWs = path.join(dirOf(rec.id), "ws");
  const killer = setTimeout(() => { ctl.cancelled = true; ctl.timeout = true; if (ctl.child) ctl.child.kill("SIGKILL"); }, BUILD_TIMEOUT_MS);
  try {
    rmrf(ws);
    // Fresh builds have nothing to search: Read (reference images) + Write + Edit only.
    rec.toolset = !rec.baseBuildId && LEAN_TOOLS ? FRESH_TOOLS : FULL_TOOLS;
    if (rec.reuseOf) {
      if (await tryReuse(rec, ctl, ws)) return;
      // Anything unexpected: forget the match and build normally.
      event(rec, rec.status, "Building it fresh instead");
      rec.reusedFrom = null; rec.reuseFailed = rec.reuseOf; rec.reuseOf = null;
      rec.attempts = 0; rec.safety = null; rec.route = null;
      rmrf(ws);
    }
    if (rec.baseBuildId) {
      const baseWs = path.join(dirOf(rec.baseBuildId), "ws");
      if (!fs.existsSync(baseWs)) throw fail("bad_request", "The earlier build this change is based on is no longer available.");
      copyDir(baseWs, ws, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === baseWs));
      setStage(rec, "planning", "Reading your existing plugin and planning the change");
    } else {
      copyDir(TEMPLATE, ws);
      setStage(rec, "planning", "Planning the plugin from your description");
    }
    // Change build whose plan cannot edit textures / sounds: the base's specs are kept exactly as they are.
    {
      const snap = new Map();
      if (!texOn(rec)) { const t = TX.snapshotSpecs(ws); for (const [k, v] of t) snap.set(k, v); if (t.size) event(rec, rec.status, `Keeping ${t.size} existing custom texture${t.size > 1 ? "s" : ""} unchanged`); }
      if (!sndOn(rec)) { const t = SND.snapshotSoundSpecs(ws); for (const [k, v] of t) snap.set(k, v); if (t.size) event(rec, rec.status, `Keeping ${t.size} existing custom sound set${t.size > 1 ? "s" : ""} unchanged`); }
      if (snap.size) keptSpecs.set(rec.id, snap);
    }

    await guardRequest(rec, ctl);
    rec.route = await chooseRoute(rec, ctl);
    rec.model = rec.route.models.generate;
    save(rec); // route + models live in rec.route / rec.aiCalls, never in customer-visible events
    const refs = (rec.references || []).map((r) => ({ path: path.join(ws, "reference", refFile(r)), name: r.name }));
    let prompt = rec.baseBuildId ? P.changePrompt(rec, ws, refs) : P.initialPrompt(rec, ws, refs);
    let resume = null;
    let repairs = 0;
    let safetyRepairs = 0;
    let lastErr = "";
    let nextModel = rec.model;
    let nextKind = rec.baseBuildId ? "change" : "generate";
    const assetState = { assetRepairs: 0, softAsked: false };
    const precheckSeen = new Map(); // rule|file|code -> times reported (line numbers move between attempts)
    const preKey = (h) => `${h.rule}|${h.where.split(":")[0]}|${h.evidence}`;
    for (;;) {
      rec.attempts += 1;
      placeRefs(rec, ws);
      if (libOn(rec)) SND.placeCatalog(ws);

      if (libOn(rec)) SND.placeCatalog(ws);
      try { await callClaude(rec, ctl, ws, prompt, { resume, model: nextModel, kind: nextKind }); }
      finally { dropRefs(ws); SND.dropCatalog(ws); ctl.draft = null; }
      const usedModel = nextModel;
      resume = rec.sessionId;

      const summary = readSummary(ws);
      if (summary && summary.refused) {
        throw fail("refused", `We can't build this one. ${String(summary.reason || "It goes against our plugin safety rules.").slice(0, 300)}`);
      }
      sanitizeWorkspace(ws, rec);

      const secretHits = scanSecrets(listFiles(ws), [...SECRETS, ...credentialSecrets()]);
      if (secretHits.length) {
        rmrf(ws);
        log("error", "secret material found in generated source", { id: rec.id, files: secretHits });
        throw fail("safety", "The generated code was blocked by our safety checks.", "secret-scan");
      }

      setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", rec.attempts > 1 ? `Checking the fix (attempt ${rec.attempts})` : "Checking the plugin files");
      let t0 = Date.now();
      const v = validate(ws, rec);
      U.addTime(rec, "validate", Date.now() - t0);
      const roundFixes = [...(v.fixes || [])];
      let fixesRecorded = false;
      // A round whose auto-fixes ended in a clean compile is a model repair that was not needed.
      const recordFixes = (compiledOk) => {
        if (fixesRecorded || !roundFixes.length) return;
        fixesRecorded = true;
        rec.autofixes = [...(rec.autofixes || []), ...roundFixes.map((f) => ({ ...f, attempt: rec.attempts }))].slice(-40);
        rec.usage.autofix = (rec.usage.autofix || 0) + roundFixes.length;
        if (compiledOk) rec.usage.savedRepairs = (rec.usage.savedRepairs || 0) + 1;
      };
      let problem = null;
      // Known-bad API patterns for this version (reviewed rules). A hit that is
      // still there after the model was told once is left to javac, so a false
      // positive can cost at most one repair.
      if (AUTOFIX && !v.problems.length) {
        t0 = Date.now();
        try {
          const fx = AF.fixImports(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")), rec.mcVersion, { classIndex }).fixes;
          if (fx.length) { roundFixes.push(...fx); event(rec, rec.status, `Fixed ${fx.length} import${fx.length > 1 ? "s" : ""} automatically`); }
        }
        catch (e) { log("warn", "autofix failed", { id: rec.id, err: String(e) }); }
        U.addTime(rec, "autofix", Date.now() - t0);
      }
      t0 = Date.now();
      const assetProblem = v.problems.length ? null : assetRound(ws, rec, assetState, repairs);
      const pre = v.problems.length || assetProblem ? [] : precheck(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")), rec.mcVersion)
        .filter((h) => (precheckSeen.get(preKey(h)) || 0) < 1);
      U.addTime(rec, "precheck", Date.now() - t0);
      if (v.problems.length) {
        problem = { kind: "compile", count: v.problems.length, text: v.problems.map((p) => `- ${p}`).join("\n"), say: `${v.problems.length} setup problem${v.problems.length > 1 ? "s" : ""} found` };
      } else if (assetProblem) {
        problem = assetProblem;
        assetState.assetRepairs += 1;
      } else if (pre.length) {
        for (const h of pre) precheckSeen.set(preKey(h), (precheckSeen.get(preKey(h)) || 0) + 1);
        rec.precheck = [...(rec.precheck || []), ...pre.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
        problem = { kind: "compile", count: pre.length, text: pre.map((h) => `- ${h.where}: ${h.message}\n    ${h.evidence}`).join("\n"), say: `Pre-check found ${pre.length} known API mistake${pre.length > 1 ? "s" : ""}` };
      } else {
        setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", `Compiling against Paper ${rec.mcVersion}${rec.attempts > 1 ? ` (attempt ${rec.attempts})` : ""}`);
        let c = await timedCompile(ws, rec, ctl);
        // Mechanical compile errors (wrong import package, missing API import, renamed constant
        // with exactly one right name in this version's jar) are fixed here, then recompiled,
        // before any model repair is spent. At most 2 rounds.
        for (let k = 0; !c.ok && AUTOFIX && k < 2 && !ctl.cancelled; k++) {
          t0 = Date.now();
          let fx = { fixes: [] };
          try { fx = AF.fixCompile(c.errors, ws, rec.mcVersion, { classIndex, members }); } catch (e) { log("warn", "autofix failed", { id: rec.id, err: String(e) }); }
          U.addTime(rec, "autofix", Date.now() - t0);
          if (!fx.fixes.length) break;
          roundFixes.push(...fx.fixes);
          event(rec, rec.status, `Fixed ${fx.fixes.length} known API mistake${fx.fixes.length > 1 ? "s" : ""} automatically`);
          c = await timedCompile(ws, rec, ctl);
        }
        recordFixes(c.ok);
        if (ctl.cancelled) throw fail(ctl.timeout ? "timeout" : "cancelled", ctl.timeout ? "This build ran out of time." : "Build cancelled.");
        if (!c.ok) {
          const count = (c.errors.match(/^\d+ errors?$/m) || ["compile errors"])[0];
          const hints = apiHints(c.errors, ws, rec.mcVersion);
          problem = { kind: "compile", count: parseInt(count, 10) || 99, hints, text: hints ? `${c.errors.slice(0, 8000 - Math.min(hints.length, 3000))}${hints.slice(0, 3000)}` : c.errors, say: `Compiler found ${count}` };
        } else if (warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h))).length) {
          const wh = warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h)));
          for (const h of wh) precheckSeen.set(preKey(h), 1);
          rec.precheck = [...(rec.precheck || []), ...wh.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
          problem = { kind: "compile", count: wh.length, text: wh.map((h) => `- ${h.message}\n    ${h.evidence}`).join("\n"), say: `Found ${wh.length} known runtime problem${wh.length > 1 ? "s" : ""}` };
        } else {
          event(rec, rec.status, "Compiled successfully");
          setStage(rec, "scanning", "Running the safety check");
          t0 = Date.now();
          const findings = [...scanBytecode(c.classes), ...scanSource(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")))];
          U.addTime(rec, "scan", Date.now() - t0);
          const blocks = findings.filter((f) => f.severity === "block");
          if (blocks.length) {
            if (safetyRepairs >= 1 || repairs >= MAX_REPAIRS) {
              rec.safety = { verdict: "block", findings };
              throw fail("safety", `The plugin was blocked by our safety check: it ${blocks[0].message}. Try rewording the request without that part.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n"));
            }
            safetyRepairs += 1;
            problem = { kind: "safety", text: blocks.map((b) => `- ${b.where}: ${b.message} (${b.evidence})`).join("\n"), say: `Safety check flagged ${blocks.length} thing${blocks.length > 1 ? "s" : ""}` };
          } else {
            const warns = findings.filter((f) => f.severity === "warn");
            rec.safety = { verdict: warns.length ? "warn" : "pass", findings };
            event(rec, "scanning", warns.length ? `Safety check passed with ${warns.length} note${warns.length > 1 ? "s" : ""}` : "Safety check passed: no network, no commands outside the game, own folder only");
            await finish(rec, ws, c, v.yml);
            return;
          }
        }
      }
      // ---- repair loop
      recordFixes(false);
      lastErr = problem.text;
      if (repairs >= MAX_REPAIRS) throw fail("compile", `We couldn't get this plugin to build after ${rec.attempts} tries. Try a simpler description, or split it into smaller plugins.`, lastErr);
      if (rec.costUsd >= BUILD_BUDGET_USD) throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request.", lastErr);
      repairs += 1;
      rec.repairs = repairs;
      // Repair ladder: a small compile problem first goes to the cheap model; a
      // repair that did not work escalates (cheap -> generation model -> one class up).
      const rm = rec.route.models;
      const small = problem.kind === "compile" && (problem.count || 99) <= R.CFG.repairSmallMax;
      if (rec.override) nextModel = repairs <= (rm.escalateAfter || 2) ? rm.generate : rm.escalate;
      else if (!R.CFG.routing) nextModel = REPAIR_MODEL;
      else if (repairs === 1) nextModel = small && rm.repairCheap ? rm.repairCheap : rm.generate;
      else if (usedModel === rm.repairCheap && rm.repairCheap !== rm.generate) nextModel = rm.generate;
      else nextModel = rm.escalate;
      nextKind = problem.kind === "safety" ? "repair-safety" : problem.kind === "asset" ? "repair-asset" : "repair";
      if (problem.kind === "safety") nextModel = R.CFG.routing || rec.override ? rm.generate : REPAIR_MODEL;
      setStage(rec, "repairing", `${problem.say}. Fixing it automatically (fix ${repairs} of ${MAX_REPAIRS})`);
      event(rec, "repairing", "Error details", problem.text.slice(0, 3000));
      if (problem.hints) event(rec, "repairing", "API lookup", problem.hints);
      rec.repairPlan = [...(rec.repairPlan || []), { repair: repairs, model: nextModel, small, kind: problem.kind }];
      prompt = P.repairPrompt(problem.kind, problem.text.slice(0, 8000), ws, AF.fixNote(roundFixes));
    }
  } catch (e) {
    rec.status = "failed";
    rec.errorCode = ctl.timeout ? "timeout" : (e.code || "internal");
    rec.error = ctl.timeout ? "This build ran out of time. Try a smaller request." : (e.code ? e.message : "Something went wrong on our side. Please try again.");
    rec.errorDetail = e.detail ? String(e.detail).slice(0, 8000) : (e.code ? undefined : String(e.stack || e).slice(0, 2000));
    if (!e.code) log("error", "build crashed", { id: rec.id, err: String(e.stack || e) });
    rec.events.push({ at: now(), stage: "failed", message: rec.error });
    rec.files = srcList(ws);
  } finally {
    clearTimeout(killer);
    keptSpecs.delete(rec.id);
    try {
      rmrf(finalWs);
      if (fs.existsSync(ws)) { copyDir(ws, finalWs, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === ws)); rmrf(ws); }
    } catch (e) { log("error", "workspace persist failed", { id: rec.id, err: String(e) }); }
    rec.durationMs = Date.now() - started;
    rec.finishedAt = rec.finishedAt || now();
    running.delete(rec.id);
    save(rec);
    if (rec.status === "succeeded" && rec.dedupeKey && !rec.reusedFrom) dedupeIndex.set(rec.dedupeKey, rec.id);
    log("info", "build finished", { id: rec.id, status: rec.status, attempts: rec.attempts, costUsd: rec.costUsd, durationMs: rec.durationMs, usage: usageLine(rec) });
    pump();
  }
}

async function timedCompile(ws, rec, ctl) {
  const t0 = Date.now();
  try { return await compile(ws, rec, ctl); } finally { U.addTime(rec, "compile", Date.now() - t0); }
}

// One structured line per build for `docker logs` (the full detail is in build.json).
function usageLine(rec) {
  const t = { uncached: 0, cacheWrite: 0, cacheRead: 0, output: 0, turns: 0 };
  for (const c of rec.aiCalls || []) {
    const k = c.tokens || {};
    t.uncached += k.uncached || 0; t.cacheWrite += k.cacheWrite || 0; t.cacheRead += k.cacheRead || 0; t.output += k.output || 0; t.turns += c.turns || 0;
  }
  const stages = {};
  for (const [k, v] of Object.entries((rec.usage && rec.usage.stages) || {})) stages[k] = { n: v.n, ms: v.ms, ...(v.costUsd != null ? { usd: v.costUsd } : {}) };
  return { calls: (rec.aiCalls || []).length, ...t, autofix: (rec.usage && rec.usage.autofix) || 0, savedRepairs: (rec.usage && rec.usage.savedRepairs) || 0, reusedFrom: rec.reusedFrom || null, stages };
}

/** Same request -> same key. Only fresh, image-free builds are eligible. */
function dedupeKeyOf({ prompt, mcVersion, pluginName, override }) {
  return U.dedupeKey({ promptVersion: P.PROMPT_VERSION, knowledge: P.knowledgeVersion(), mcVersion, pluginName, tier: override ? override.tier || "" : "auto", model: override ? override.model || "" : "", prompt, extra: [LEAN_TOOLS, EFFORT] });
}

// Reuse path: copy the earlier build's checked source, then run every non-AI check again
// (validation, pre-check, javac, safety scan) so the result meets today's rules. No AI call.
async function tryReuse(rec, ctl, ws) {
  const src = records.get(rec.reuseOf);
  const srcWs = src ? path.join(dirOf(src.id), "ws") : null;
  if (!src || src.status !== "succeeded" || !fs.existsSync(srcWs)) return false;
  const t0 = Date.now();
  try {
    copyDir(srcWs, ws, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === srcWs));
    setStage(rec, "compiling", "Found a ready-made build of this exact request, checking it again");
    rec.route = { class: "reuse", method: "dedupe", models: { generate: null, repairCheap: null, escalate: null } };
    sanitizeWorkspace(ws, rec);
    rec.attempts = 1;
    const v = validate(ws, rec);
    if (v.problems.length || (v.fixes && v.fixes.length)) return false;
    if (precheck(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")), rec.mcVersion).length) return false;
    const c = await compile(ws, rec, ctl);
    if (!c.ok || warningCheck(c.warnings, rec.mcVersion).length) return false;
    const findings = [...scanBytecode(c.classes), ...scanSource(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")))];
    if (findings.some((f) => f.severity === "block")) return false;
    rec.safety = { verdict: findings.some((f) => f.severity === "warn") ? "warn" : "pass", findings };
    rec.reusedFrom = src.id;
    event(rec, "scanning", "Safety check passed");
    await finish(rec, ws, c, v.yml);
    return true;
  } catch (e) {
    log("warn", "reuse failed", { id: rec.id, from: rec.reuseOf, err: String(e) });
    return false;
  } finally { U.addTime(rec, "reuse", Date.now() - t0); }
}

function srcList(ws) {
  return listFiles(ws).filter((f) => !f.rel.startsWith("build/")).map((f) => ({ path: f.rel, size: f.size }));
}

async function finish(rec, ws, c, yml) {
  const s = readSummary(ws) || {};
  const name = String(yml.name);
  const version = String(yml.version);
  const jarName = `${name}-${version}.jar`;
  const dest = path.join(dirOf(rec.id), "artifact.jar");
  fs.copyFileSync(c.jar, dest);
  const buf = fs.readFileSync(dest);
  rec.jar = { name: jarName, size: buf.length, sha256: crypto.createHash("sha256").update(buf).digest("hex") };
  rec.pluginName = name;
  rec.version = version;
  const arr = (x) => (Array.isArray(x) ? x : []);
  const ymlCommands = yml.commands && typeof yml.commands === "object" ? yml.commands : {};
  const ymlPerms = yml.permissions && typeof yml.permissions === "object" ? yml.permissions : {};
  rec.summary = {
    tagline: str(s.tagline, 200) || String(yml.description || "").slice(0, 200),
    text: str(s.summary, 1500),
    howToUse: arr(s.howToUse).map((x) => str(x, 300)).filter(Boolean).slice(0, 12),
    limitations: arr(s.limitations).map((x) => str(x, 300)).filter(Boolean).slice(0, 8),
    changes: str(s.changes, 600),
  };
  rec.commands = arr(s.commands).length
    ? arr(s.commands).slice(0, 40).map((x) => ({ usage: str(x.usage, 120), description: str(x.description, 300), permission: str(x.permission, 120), whoCanUse: str(x.whoCanUse, 60) }))
    : Object.entries(ymlCommands).map(([k, v]) => ({ usage: (v && v.usage) ? String(v.usage).replace("<command>", k) : `/${k}`, description: str(v && v.description, 300), permission: str(v && v.permission, 120), whoCanUse: "" }));
  rec.permissions = arr(s.permissions).length
    ? arr(s.permissions).slice(0, 60).map((x) => ({ node: str(x.node, 120), description: str(x.description, 300), default: str(x.default, 10) }))
    : Object.entries(ymlPerms).map(([k, v]) => ({ node: k, description: str(v && v.description, 300), default: String((v && v.default) ?? "op") }));
  rec.config = arr(s.config).slice(0, 60).map((x) => ({ key: str(x.key, 120), description: str(x.description, 300), default: str(typeof x.default === "object" ? JSON.stringify(x.default) : x.default, 200) }));
  rec.warnings = [
    ...c.warnings.map((w) => w.replace(/^warning: /, "Compiler: ")),
    ...(rec.safety ? rec.safety.findings.filter((f) => f.severity === "warn").map((f) => `This plugin ${f.message} (${f.where}).`) : []),
  ];
  // Cyrus R1: the texture specs that ship with this jar (the portal renders, hosts and installs the pack).
  const ar = assetResultOf(ws, rec);
  if (ar) {
    rec.assetResult = ar;
    rec.warnings.push(...ar.warnings);
    if (ar.downgraded.length) rec.summary.limitations = [...rec.summary.limitations, ...ar.downgraded.map((d) => (d.kind === "sound" ? `The custom sound set "${d.name}" did not pass Nxeon's sound checks, so it was left out.` : `The custom texture "${d.name}" did not pass Nxeon's texture checks, so it was left out.`))].slice(0, 12);
  }
  rec.files = srcList(ws);
  rec.status = "succeeded";
  rec.finishedAt = now();
  rec.events.push({ at: now(), stage: "succeeded", message: `Ready: ${jarName}` });
}
function str(x, n) { return x == null ? "" : String(x).slice(0, n); }

function pump() {
  while (running.size < CONCURRENCY && queue.length) {
    const id = queue.shift();
    const rec = records.get(id);
    if (!rec || rec.status !== "queued") continue;
    runBuild(rec);
  }
}

