// Cyrus server inventory: a bounded, read-only ZIP/JAR reader. Never extracts anything to disk and never runs code.
// Cyrus-owned (no import of Nxeon's lib/mods/archive.ts, so Cyrus can stand alone later), same refusals:
//  - central directory only for the index; an entry is inflated only on request, against a shared byte budget;
//  - zip64, encrypted entries and methods other than store/deflate are refused per entry;
//  - zip bombs: entry-count cap, per-entry and total inflate caps, a compression-ratio cap, and zlib's
//    maxOutputLength so a lying header cannot allocate more than it declared; CRC-32 is checked;
//  - unsafe names (`..`, absolute, backslash, drive letters, NUL) never reach a filesystem here, but they are
//    REPORTED: a plugin jar carrying traversal names is suspicious in itself;
//  - garbage / truncated input gives { ok: false, error } instead of throwing.
import { crc32, inflateRawSync } from "node:zlib";

export type ZipLimits = {
  maxEntries: number;
  /** Largest single entry we will inflate. */
  maxEntryBytes: number;
  /** Total bytes inflated from one archive (shared budget across every readEntry call). */
  maxTotalBytes: number;
  /** usize/csize above this (for entries > 64 KB) is treated as a bomb. */
  maxRatio: number;
  maxNameBytes: number;
};

export const DEFAULT_ZIP_LIMITS: ZipLimits = { maxEntries: 20_000, maxEntryBytes: 4 * 1024 * 1024, maxTotalBytes: 48 * 1024 * 1024, maxRatio: 200, maxNameBytes: 512 };

export type ZipEntry = { name: string; method: number; csize: number; usize: number; crc: number; lho: number; flags: number; dir: boolean };
export type ZipIndex = {
  entries: ZipEntry[];
  /** Name problems found in the central directory (reported, never fatal: nothing is extracted). */
  unsafeNames: string[];
  duplicateNames: string[];
  budget: { left: number };
  buf: Buffer;
  limits: ZipLimits;
};

export type ZipIndexResult = { ok: true; zip: ZipIndex } | { ok: false; error: string };
export type ZipReadResult = { ok: true; data: Buffer } | { ok: false; error: string; bomb?: boolean };

const SIG_LOCAL = 0x04034b50, SIG_CENTRAL = 0x02014b50, SIG_EOCD = 0x06054b50;

export function isUnsafeEntryName(name: string): boolean {
  return !name || name.includes("\0") || name.includes("\\") || name.startsWith("/") || /^[A-Za-z]:/.test(name) || name.split("/").includes("..");
}

export function indexZip(buf: Buffer, limits: ZipLimits = DEFAULT_ZIP_LIMITS): ZipIndexResult {
  if (!Buffer.isBuffer(buf) || buf.length < 22) return { ok: false, error: "not a zip archive (too short)" };
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 22 - 0xffff); i--) {
    if (buf.readUInt32LE(i) === SIG_EOCD) { eocd = i; break; }
  }
  if (eocd < 0) return { ok: false, error: "not a zip archive (no end-of-central-directory record)" };
  const total = buf.readUInt16LE(eocd + 10);
  const cdSize = buf.readUInt32LE(eocd + 12);
  const cdOff = buf.readUInt32LE(eocd + 16);
  if (total === 0xffff || cdOff === 0xffffffff || cdSize === 0xffffffff) return { ok: false, error: "zip64 archives are not read" };
  if (total > limits.maxEntries) return { ok: false, error: `too many entries (${total} > ${limits.maxEntries})` };
  if (cdOff + cdSize > eocd) return { ok: false, error: "truncated or corrupt central directory" };
  const entries: ZipEntry[] = [];
  const unsafeNames: string[] = [];
  const duplicateNames: string[] = [];
  const seen = new Set<string>();
  let p = cdOff;
  for (let n = 0; n < total; n++) {
    if (p + 46 > eocd || buf.readUInt32LE(p) !== SIG_CENTRAL) return { ok: false, error: "corrupt central directory" };
    const flags = buf.readUInt16LE(p + 8);
    const method = buf.readUInt16LE(p + 10);
    const crc = buf.readUInt32LE(p + 16);
    const csize = buf.readUInt32LE(p + 20);
    const usize = buf.readUInt32LE(p + 24);
    const nlen = buf.readUInt16LE(p + 28), xlen = buf.readUInt16LE(p + 30), clen = buf.readUInt16LE(p + 32);
    const lho = buf.readUInt32LE(p + 42);
    if (p + 46 + nlen > eocd) return { ok: false, error: "corrupt central directory (name out of range)" };
    if (nlen > limits.maxNameBytes) return { ok: false, error: `entry name longer than ${limits.maxNameBytes} bytes` };
    const name = buf.subarray(p + 46, p + 46 + nlen).toString((flags & 0x800) ? "utf8" : "latin1");
    p += 46 + nlen + xlen + clen;
    const dir = name.endsWith("/");
    if (isUnsafeEntryName(name)) unsafeNames.push(name.slice(0, 160));
    if (seen.has(name)) duplicateNames.push(name.slice(0, 160)); else seen.add(name);
    entries.push({ name, method, csize, usize, crc, lho, flags, dir });
  }
  return { ok: true, zip: { entries, unsafeNames, duplicateNames, budget: { left: limits.maxTotalBytes }, buf, limits } };
}

/** Inflate one entry within the archive's shared budget. Never throws. */
export function readEntry(z: ZipIndex, e: ZipEntry, maxBytes = z.limits.maxEntryBytes): ZipReadResult {
  const { buf, limits } = z;
  if (e.dir) return { ok: false, error: "is a directory" };
  if (e.flags & 0x1) return { ok: false, error: "encrypted entry" };
  if (e.csize === 0xffffffff || e.usize === 0xffffffff || e.lho === 0xffffffff) return { ok: false, error: "zip64 entry" };
  if (e.usize > 64 * 1024 && e.csize > 0 && e.usize / e.csize > limits.maxRatio) return { ok: false, error: `suspicious compression ratio (${Math.round(e.usize / e.csize)}:1)`, bomb: true };
  const cap = Math.min(maxBytes, limits.maxEntryBytes);
  if (e.usize > cap) return { ok: false, error: `entry too large (${e.usize} > ${cap} bytes)`, bomb: e.usize > limits.maxTotalBytes };
  if (e.usize > z.budget.left) return { ok: false, error: "archive inflate budget exhausted", bomb: true };
  if (e.lho + 30 > buf.length || buf.readUInt32LE(e.lho) !== SIG_LOCAL) return { ok: false, error: "corrupt local header" };
  const start = e.lho + 30 + buf.readUInt16LE(e.lho + 26) + buf.readUInt16LE(e.lho + 28);
  if (start + e.csize > buf.length) return { ok: false, error: "truncated entry" };
  const comp = buf.subarray(start, start + e.csize);
  let data: Buffer;
  if (e.method === 0) {
    if (e.csize !== e.usize) return { ok: false, error: "bad stored entry size" };
    data = Buffer.from(comp);
  } else if (e.method === 8) {
    try {
      data = e.usize === 0 ? Buffer.alloc(0) : inflateRawSync(comp, { maxOutputLength: e.usize });
    } catch {
      return { ok: false, error: "could not inflate (corrupt, or larger than its header says)", bomb: true };
    }
  } else return { ok: false, error: `unsupported compression method ${e.method}` };
  if (data.length !== e.usize) return { ok: false, error: "size mismatch" };
  if ((crc32(data) >>> 0) !== (e.crc >>> 0)) return { ok: false, error: "CRC mismatch" };
  z.budget.left -= data.length;
  return { ok: true, data };
}

export function findEntry(z: ZipIndex, name: string): ZipEntry | null {
  return z.entries.find((e) => e.name === name) ?? null;
}
// One plugin jar -> descriptor + bytecode summary + safety flags. Pure (bytes in, data out). Never extracts or runs.
import { createHash } from "node:crypto";
import { parseClass } from "./classfile";
import { addClass, emptySummary, finishSummary } from "./bytecode";
import { readDescriptor } from "./descriptor";
import { DEFAULT_ZIP_LIMITS, findEntry, indexZip, readEntry, type ZipLimits } from "./zipread";
import type { PluginJar } from "./types";

export const JAR_LIMITS = { maxClasses: 4000, maxClassBytes: 1024 * 1024, maxDescriptorBytes: 256 * 1024 };

/** Signs that a jar is a Minecraft/Paper SERVER (bundler/paperclip/CraftBukkit main), never a plugin. */
const SERVER_MARKERS = ["net/minecraft/server/Main.class", "net/minecraft/bundler/Main.class", "io/papermc/paperclip/Main.class", "io/papermc/paperclip/Paperclip.class", "org/bukkit/craftbukkit/Main.class", "META-INF/versions.list"];

export function inspectJar(file: string, path: string, buf: Buffer, opts: { zipLimits?: ZipLimits; bytecode?: boolean } = {}): PluginJar {
  const jar: PluginJar = {
    file, path, size: buf.length,
    sha256: createHash("sha256").update(buf).digest("hex"),
    sha1: createHash("sha1").update(buf).digest("hex"),
    descriptor: null, bytecode: null,
    flags: { unsafeNames: [], duplicateNames: [], bombEntries: [], unreadable: null, serverJar: false, serverJarEvidence: null },
  };
  const idx = indexZip(buf, opts.zipLimits ?? DEFAULT_ZIP_LIMITS);
  if (!idx.ok) { jar.flags.unreadable = idx.error; return jar; }
  const z = idx.zip;
  jar.flags.unsafeNames = z.unsafeNames.slice(0, 20);
  jar.flags.duplicateNames = z.duplicateNames.slice(0, 20);
  const marker = SERVER_MARKERS.find((m) => findEntry(z, m));
  if (marker) { jar.flags.serverJar = true; jar.flags.serverJarEvidence = `contains ${marker}`; }

  // Paper uses paper-plugin.yml when a jar has both.
  const both = !!findEntry(z, "plugin.yml") && !!findEntry(z, "paper-plugin.yml");
  for (const f of ["paper-plugin.yml", "plugin.yml"] as const) {
    const e = findEntry(z, f);
    if (!e) continue;
    const r = readEntry(z, e, JAR_LIMITS.maxDescriptorBytes);
    if (!r.ok) { if (r.bomb) jar.flags.bombEntries.push(f); jar.descriptor = { ...readDescriptor("", f), issues: [`${f} unreadable: ${r.error}`] }; break; }
    jar.descriptor = readDescriptor(r.data.toString("utf8"), f);
    if (both) jar.descriptor.issues.push("jar has both plugin.yml and paper-plugin.yml: Paper uses paper-plugin.yml");
    break;
  }
  if (opts.bytecode === false) return jar;

  const sum = emptySummary();
  const notes = new Map<string, number>();
  const ns = jar.descriptor?.name ? jar.descriptor.name.toLowerCase().replace(/[^a-z0-9._-]/g, "") : null;
  let n = 0;
  for (const e of z.entries) {
    if (e.dir || !e.name.endsWith(".class")) continue;
    if (n >= JAR_LIMITS.maxClasses) { sum.classesSkipped++; continue; }
    n++;
    const r = readEntry(z, e, JAR_LIMITS.maxClassBytes);
    if (!r.ok) { if (r.bomb) jar.flags.bombEntries.push(e.name.slice(0, 120)); sum.classesSkipped++; continue; }
    const c = parseClass(r.data);
    if (!c.ok) { sum.classesFailed++; continue; }
    addClass(sum, c.cls, ns, notes);
  }
  jar.flags.bombEntries = jar.flags.bombEntries.slice(0, 20);
  jar.bytecode = finishSummary(sum, notes);
  return jar;
}
// plugin.yml / paper-plugin.yml -> a typed descriptor. Pure. Unknown or malformed fields are reported, never thrown.
// Bukkit rules mirrored here: permission defaults (true/false/op/not op and their aliases, falling back to the
// top-level `default-permission`, else op); command aliases may be a string or a list; depend/softdepend/loadbefore
// may be a string or a list. paper-plugin.yml declares dependencies as `dependencies.server.<Name>: { load, required }`
// (load BEFORE = this plugin loads before that one = Bukkit `loadbefore`) and has no `commands:` (Brigadier only).
import { asBool, asMap, asStr, asStrList, parseYaml, type YamlValue } from "./yaml";

export type PermissionDefault = "true" | "false" | "op" | "not op";
export type DeclaredCommand = { name: string; aliases: string[]; permission: string | null; description: string | null };
export type DeclaredPermission = { name: string; default: PermissionDefault; explicitDefault: boolean; children: string[] };
export type PluginDescriptor = {
  file: "plugin.yml" | "paper-plugin.yml";
  name: string | null;
  version: string | null;
  main: string | null;
  apiVersion: string | null;
  foliaSupported: boolean;
  depend: string[];
  softdepend: string[];
  loadbefore: string[];
  provides: string[];
  libraries: string[];
  commands: DeclaredCommand[];
  permissions: DeclaredPermission[];
  issues: string[];
};

const PERM_DEFAULTS: Record<string, PermissionDefault> = {
  true: "true", t: "true", yes: "true", y: "true",
  false: "false", f: "false", no: "false", n: "false",
  op: "op", isop: "op", operator: "op", isoperator: "op", admin: "op", isadmin: "op",
  "!op": "not op", notop: "not op", "not op": "not op", "!operator": "not op", notoperator: "not op", "!admin": "not op", notadmin: "not op",
};
export const normalizePermDefault = (v: YamlValue | undefined): PermissionDefault | null => {
  const s = asStr(v);
  return s == null ? null : PERM_DEFAULTS[s.toLowerCase().replace(/_/g, " ").trim()] ?? PERM_DEFAULTS[s.toLowerCase().replace(/[\s_]/g, "")] ?? null;
};

const NAME_RE = /^[A-Za-z0-9 _.-]{1,64}$/;

export function readDescriptor(text: string, file: "plugin.yml" | "paper-plugin.yml"): PluginDescriptor {
  const { value, issues } = parseYaml(text);
  const d: PluginDescriptor = { file, name: null, version: null, main: null, apiVersion: null, foliaSupported: false, depend: [], softdepend: [], loadbefore: [], provides: [], libraries: [], commands: [], permissions: [], issues: [...issues] };
  const root = asMap(value);
  if (!root) { d.issues.push(`${file} is not a mapping`); return d; }
  d.name = asStr(root.name);
  if (d.name && !NAME_RE.test(d.name)) d.issues.push(`plugin name '${d.name.slice(0, 80)}' has characters Paper refuses`);
  d.version = asStr(root.version);
  d.main = asStr(root.main);
  d.apiVersion = asStr(root["api-version"]);
  d.foliaSupported = asBool(root["folia-supported"]) === true;
  d.provides = asStrList(root.provides);
  d.libraries = asStrList(root.libraries);
  if (file === "plugin.yml") {
    d.depend = asStrList(root.depend);
    d.softdepend = asStrList(root.softdepend);
    d.loadbefore = asStrList(root.loadbefore);
  } else {
    const deps = asMap(asMap(root.dependencies)?.server);
    for (const [dep, cfgRaw] of Object.entries(deps ?? {})) {
      const cfg = asMap(cfgRaw);
      const load = (asStr(cfg?.load) ?? "OMIT").toUpperCase();
      const required = asBool(cfg?.required) ?? true;
      if (load === "BEFORE") d.loadbefore.push(dep);
      else if (required) d.depend.push(dep);
      else d.softdepend.push(dep);
    }
    for (const k of ["depend", "softdepend", "loadbefore"] as const) if (root[k] !== undefined) d.issues.push(`paper-plugin.yml ignores '${k}' (use dependencies.server)`);
    if (root.commands !== undefined) d.issues.push("paper-plugin.yml cannot declare commands (Paper ignores them; Brigadier only)");
  }
  if (!d.name) d.issues.push(`${file} has no name`);
  if (!d.main) d.issues.push(`${file} has no main class`);

  const fallback = normalizePermDefault(root["default-permission"]) ?? "op";
  const commands = file === "plugin.yml" ? asMap(root.commands) : null;
  if (root.commands !== undefined && file === "plugin.yml" && !commands && root.commands !== null) d.issues.push("commands is not a mapping");
  for (const [name, raw] of Object.entries(commands ?? {})) {
    const c = asMap(raw);
    if (/[\s:]/.test(name) || !name) { d.issues.push(`command '${name.slice(0, 40)}' has an invalid label`); continue; }
    d.commands.push({ name: name.toLowerCase(), aliases: asStrList(c?.aliases).map((a) => a.toLowerCase()).filter((a) => !/[\s:]/.test(a)), permission: asStr(c?.permission), description: asStr(c?.description) });
  }
  const perms = asMap(root.permissions);
  const seen = new Set<string>();
  const addPerm = (name: string, raw: YamlValue, inheritedDefault: PermissionDefault, depth: number) => {
    if (depth > 8 || d.permissions.length >= 2000) return;
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    const p = asMap(raw);
    const def = normalizePermDefault(p?.default);
    const childMap = asMap(p?.children);
    const children = childMap ? Object.keys(childMap) : asStrList(p?.children);
    d.permissions.push({ name: key, default: def ?? inheritedDefault, explicitDefault: def != null, children: children.map((c) => c.toLowerCase()) });
    // Bukkit registers map-form children that carry their own definition as permissions too.
    for (const [cn, cv] of Object.entries(childMap ?? {})) if (asMap(cv)) addPerm(cn, cv, def ?? inheritedDefault, depth + 1);
  };
  for (const [name, raw] of Object.entries(perms ?? {})) addPerm(name, raw, fallback, 0);
  return d;
}
// Cyrus server inventory (R2): report types + the read-only file-access seam.
// HOST SEAM: the inventory reaches a server only through `ReadOnlyServerFs`, a read-only subset that Nxeon's Mods
// engine GuestFs (lib/mods/guest-fs.ts: SSH in production, LocalGuestFs in tests/SANDBOX) already satisfies
// structurally, so no Nxeon module is imported here. A standalone Cyrus would implement it over the host API.
import type { PluginDescriptor } from "./descriptor";

export interface ReadOnlyServerFs {
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  list(dir: string): Promise<string[]>;
}

export type EventUse = { event: string; priority: string; ignoreCancelled: boolean; mutates: boolean; cancels: boolean; where: string };
export type ServiceUse = { service: "economy" | "permission" | "chat"; via: "ServicesManager.register" | "implements"; where: string };
export type SingleOwnerResource = "economy_provider" | "permission_provider" | "chat_provider" | "chat_renderer" | "tab_list" | "sidebar" | "world_rules" | "join_quit_messages";
export type SingleOwnerUse = { resource: SingleOwnerResource; where: string; evidence: string };
export type KeyUse = { key: string; where: string };

export type BytecodeSummary = {
  classesParsed: number;
  classesFailed: number;
  classesSkipped: number;
  /** Highest class-file major version seen (65 = Java 21, 69 = Java 25). */
  maxClassMajor: number | null;
  javaRelease: number | null;
  events: EventUse[];
  /** Root literals registered through Paper's Brigadier API (`Commands.register`), approximate. */
  brigadierRoots: string[];
  services: ServiceUse[];
  singleOwner: SingleOwnerUse[];
  /** Full `namespace:key` strings; plugin-scoped keys use the plugin's name lowercased (Bukkit's rule). */
  namespacedKeys: KeyUse[];
  pdcUsed: boolean;
  customModelData: number[];
  itemModels: KeyUse[];
  recipes: KeyUse[];
  soundKeys: KeyUse[];
  repeatingTaskSites: number;
  displayEntitySpawnSites: number;
  bukkitSchedulerSites: number;
  foliaSchedulerSites: number;
  usesItemModelApi: boolean;
  /** What this summary could NOT determine (computed keys, dynamic registration, skipped classes...). */
  undetermined: string[];
};

export type JarFlags = { unsafeNames: string[]; duplicateNames: string[]; bombEntries: string[]; unreadable: string | null; serverJar: boolean; serverJarEvidence: string | null };

