  const fresh = await db.modBuild.findUnique({ where: { id } });
  return { ok: true, status: 201, build: toView(fresh!), reserved: gate.reserved, ...(assets.meta?.notices.length ? { assetNotices: assets.meta.notices } : {}) };
}
