// Cyrus import: the curated, checksum-pinned COMPILE-ONLY dependency allowlist (deps.json) and the pure resolver that
// maps what an uploaded project declares (build-file coordinates, plugin.yml depend/softdepend, Java imports) onto it.
// Anything not on the list is `unsupported dependency: X` with how to request it. Nothing here downloads anything: the
// build service holds the jars (MB_DEPS_DIR) and re-verifies each sha256 before every compile. Pure + client-safe.
import DEPS from "./deps.json";

export type AllowedDep = {
  id: string; name: string; coordinates: string; aliases: string[]; packages: string[]; pluginNames: string[];
  repository: string; url: string; file: string; size: number; sha1: string; sha256: string;
  licence: string; licenceSource: string; scope: "compile-only"; shaded: false; verified: string;
};
export type RefusedDep = { match: string[]; what: string; reason: string };
export type DepsManifest = {
  version: string; note: string; dependencies: AllowedDep[];
  providedByPaper: { note: string; coordinates: string[]; packages: string[] };
  refused: RefusedDep[]; howToRequest: string;
};

export const DEPS_MANIFEST = DEPS as unknown as DepsManifest;
export const DEPS_VERSION = DEPS_MANIFEST.version;
export const depById = (id: string): AllowedDep | null => DEPS_MANIFEST.dependencies.find((d) => d.id === id) ?? null;

/** Java packages that come with the JDK (java.*, javax.* the JDK ships, jdk.*). The scanner judges which are allowed. */
const JDK_PREFIXES = ["java.", "javax.crypto", "javax.net", "javax.security", "javax.xml", "javax.naming", "javax.script", "javax.tools", "javax.management", "javax.sql", "javax.imageio", "javax.swing", "javax.sound", "javax.print", "javax.lang.model", "javax.annotation.processing", "jdk.", "sun.", "com.sun.", "org.w3c.dom", "org.xml.sax", "org.ietf.jgss"];

export type DepSource = "build-file" | "plugin.yml" | "import";
export type DepOutcome =
  | { status: "allowed"; dep: AllowedDep }
  | { status: "provided" }
  | { status: "jdk" }
  | { status: "refused"; what: string; reason: string }
  | { status: "unknown" };

const startsWithSeg = (s: string, prefix: string) => s === prefix || s.startsWith(prefix + ".") || s.startsWith(prefix + ":");

/** A Java package (or fully-qualified import) -> what it is. Longest match wins across allowed/refused/provided. */
export function classifyPackage(pkg: string): DepOutcome {
  const p = pkg.trim();
  if (!p) return { status: "unknown" };
  if (JDK_PREFIXES.some((j) => (j.endsWith(".") ? p.startsWith(j) : startsWithSeg(p, j)))) return { status: "jdk" };
  let best: { len: number; out: DepOutcome } | null = null;
  const consider = (prefix: string, out: DepOutcome) => {
    if (prefix.includes(":")) return;
    if (startsWithSeg(p, prefix) && (!best || prefix.length > best.len)) best = { len: prefix.length, out };
  };
  for (const d of DEPS_MANIFEST.dependencies) for (const k of d.packages) consider(k, { status: "allowed", dep: d });
  for (const r of DEPS_MANIFEST.refused) for (const k of r.match) consider(k, { status: "refused", what: r.what, reason: r.reason });
  for (const k of DEPS_MANIFEST.providedByPaper.packages) consider(k, { status: "provided" });
  return best ? (best as { out: DepOutcome }).out : { status: "unknown" };
}

/** `group:artifact[:version]` -> what it is. Version is ignored for matching (the allowlist pins its own). */
export function classifyCoordinate(coord: string): DepOutcome {
  const [g = "", a = ""] = coord.trim().split(":");
  if (!g) return { status: "unknown" };
  const ga = a ? `${g}:${a}` : g;
  for (const d of DEPS_MANIFEST.dependencies) {
    const own = d.coordinates.split(":").slice(0, 2).join(":");
    if (own === ga || d.aliases.includes(ga)) return { status: "allowed", dep: d };
  }
  for (const r of DEPS_MANIFEST.refused) for (const m of r.match) {
    if (m.includes(":") ? m === ga : startsWithSeg(g, m)) return { status: "refused", what: r.what, reason: r.reason };
  }
  for (const c of DEPS_MANIFEST.providedByPaper.coordinates) {
    const [cg, ca] = c.split(":");
    if (cg === g && (ca === "*" || ca === a)) return { status: "provided" };
  }
  return { status: "unknown" };
}

export type Unsupported = { what: string; reason: string; source: DepSource; evidence: string };
export type DepResolution = {
  /** Allowlisted dependency ids, sorted (the compile classpath, in this order). */
  allowed: string[];
  provided: string[];
  unsupported: Unsupported[];
  /** plugin.yml depend/softdepend entries that need no compile dependency (another plugin the server runs). */
  runtimeOnly: string[];
};

/**
 * Everything the project declares or imports -> the allowlisted classpath plus a clear refusal for the rest.
 * `ownPackages` are the packages declared by the uploaded sources (imports of those are the project's own code).
 */
export function resolveDependencies(input: { coordinates: string[]; imports: string[]; pluginDepends: string[]; ownPackages: string[] }): DepResolution {
  const allowed = new Set<string>();
  const provided = new Set<string>();
  const unsupported = new Map<string, Unsupported>();
  const add = (u: Unsupported) => { if (!unsupported.has(u.what)) unsupported.set(u.what, u); };
  for (const c of input.coordinates) {
    const o = classifyCoordinate(c);
    if (o.status === "allowed") allowed.add(o.dep.id);
    else if (o.status === "provided") provided.add(c.split(":").slice(0, 2).join(":"));
    else if (o.status === "refused") add({ what: o.what, reason: o.reason, source: "build-file", evidence: c.slice(0, 120) });
    else add({ what: c.split(":").slice(0, 2).join(":").slice(0, 120), reason: `it is not on Cyrus's dependency allowlist. ${DEPS_MANIFEST.howToRequest}`, source: "build-file", evidence: c.slice(0, 120) });
  }
  const own = input.ownPackages.filter(Boolean);
  for (const imp of input.imports) {
    const name = imp.replace(/^static\s+/, "").replace(/\.\*$/, "").trim();
    if (own.some((p) => startsWithSeg(name, p))) continue;
    // an import of a class in the same top-level group as an own package (com.example.x imports com.example.y) is own code
    // only if that exact package is declared; otherwise it must resolve below
    const o = classifyPackage(name);
    if (o.status === "allowed") allowed.add(o.dep.id);
    else if (o.status === "refused") add({ what: o.what, reason: o.reason, source: "import", evidence: name.slice(0, 160) });
    else if (o.status === "unknown") {
      const lib = name.split(".").slice(0, 3).join(".");
      add({ what: lib, reason: `the code imports ${name.slice(0, 120)}, which is not in the JDK, the Paper API, your own source or Cyrus's dependency allowlist. ${DEPS_MANIFEST.howToRequest}`, source: "import", evidence: name.slice(0, 160) });
    }
  }
  const runtimeOnly: string[] = [];
  for (const dep of input.pluginDepends) {
    const d = DEPS_MANIFEST.dependencies.find((x) => x.pluginNames.some((n) => n.toLowerCase() === dep.toLowerCase()));
    if (!d) runtimeOnly.push(dep);
  }
  return { allowed: [...allowed].sort(), provided: [...provided].sort(), unsupported: [...unsupported.values()], runtimeOnly };
}

/** Pure check of the data file itself (also run by the tests): ids unique, hashes well-formed, compile-only, never shaded. */
export function validateDepsManifest(m: DepsManifest = DEPS_MANIFEST): string[] {
  const errs: string[] = [];
  const ids = new Set<string>();
  for (const d of m.dependencies) {
    if (!/^[a-z0-9-]{2,40}$/.test(d.id)) errs.push(`${d.id}: bad id`);
    if (ids.has(d.id)) errs.push(`${d.id}: duplicate id`);
    ids.add(d.id);
    if (!/^[0-9a-f]{64}$/.test(d.sha256)) errs.push(`${d.id}: sha256 must be 64 hex`);
    if (!/^[0-9a-f]{40}$/.test(d.sha1)) errs.push(`${d.id}: sha1 must be 40 hex`);
    if (d.scope !== "compile-only" || d.shaded !== false) errs.push(`${d.id}: must be compile-only and never shaded`);
    if (!/^[A-Za-z0-9-]+\.jar$/.test(d.file.replace(/\./g, (c, i) => (i === d.file.lastIndexOf(".") ? c : "-")))) errs.push(`${d.id}: bad file name`);
    if (!/^https:\/\//.test(d.url) || !d.url.endsWith("/" + d.url.split("/").pop())) errs.push(`${d.id}: url must be https`);
    if (!d.licence) errs.push(`${d.id}: licence missing`);
    if (!d.packages.length) errs.push(`${d.id}: packages missing`);
    if (d.coordinates.split(":").length !== 3) errs.push(`${d.id}: coordinates must be group:artifact:version`);
  }
  return errs;
}

