// Cyrus import: licence detection (SPDX ids) from the files an uploader sent. Pure + client-safe; reads text only.
// Sources: `SPDX-License-Identifier:` headers in any text file, LICENSE / COPYING / NOTICE / UNLICENSE files by their
// standard wording, and a Maven POM's <licenses><name> (the POM is DATA here: read as text, never run). "unknown" is a
// valid, honest answer and is what most uploads will get.

export type DetectedLicence = { spdx: string; source: string; how: "spdx-header" | "licence-text" | "pom" };

/** SPDX ids (plus our LicenseRef for "All rights reserved") this detector can name. */
export const KNOWN_LICENCES = [
  "MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC", "Unlicense", "CC0-1.0", "MPL-2.0", "EPL-2.0",
  "LGPL-2.1", "LGPL-3.0", "GPL-2.0", "GPL-3.0", "AGPL-3.0", "LicenseRef-All-Rights-Reserved",
] as const;
export type KnownLicence = (typeof KNOWN_LICENCES)[number];

/** Licences that let anyone redistribute the work. Copyleft ones also need the source to go with it. */
export const REDISTRIBUTION: Record<KnownLicence, { redistribute: boolean; copyleft: boolean }> = {
  MIT: { redistribute: true, copyleft: false }, "Apache-2.0": { redistribute: true, copyleft: false },
  "BSD-2-Clause": { redistribute: true, copyleft: false }, "BSD-3-Clause": { redistribute: true, copyleft: false },
  ISC: { redistribute: true, copyleft: false }, Unlicense: { redistribute: true, copyleft: false }, "CC0-1.0": { redistribute: true, copyleft: false },
  "MPL-2.0": { redistribute: true, copyleft: true }, "EPL-2.0": { redistribute: true, copyleft: true },
  "LGPL-2.1": { redistribute: true, copyleft: true }, "LGPL-3.0": { redistribute: true, copyleft: true },
  "GPL-2.0": { redistribute: true, copyleft: true }, "GPL-3.0": { redistribute: true, copyleft: true }, "AGPL-3.0": { redistribute: true, copyleft: true },
  "LicenseRef-All-Rights-Reserved": { redistribute: false, copyleft: false },
};

/** Normalise a free-form or SPDX string ("MIT License", "GPL-3.0-or-later", "apache 2") to a known id, else null. */
export function normaliseLicence(raw: string | null | undefined): KnownLicence | null {
  if (!raw) return null;
  const s = String(raw).trim().replace(/\s+/g, " ").slice(0, 200);
  if (!s) return null;
  const low = s.toLowerCase();
  const exact = KNOWN_LICENCES.find((k) => k.toLowerCase() === low);
  if (exact) return exact;
  const t = low.replace(/[-_ ]?(only|or[-_ ]later|\+)$/, "").replace(/^the /, "");
  const table: [RegExp, KnownLicence][] = [
    [/^(mit|mit license|expat)$/, "MIT"],
    [/^apache([- ]?license)?[ ,-]*(version )?2(\.0)?$/, "Apache-2.0"],
    [/^bsd[- ]?2([- ]?clause)?/, "BSD-2-Clause"], [/^bsd[- ]?3([- ]?clause)?|^(new|revised|modified) bsd/, "BSD-3-Clause"],
    [/^isc( license)?$/, "ISC"], [/^(the )?unlicense$/, "Unlicense"], [/^cc0([- ]1\.0)?/, "CC0-1.0"],
    [/^mpl[- ]?2(\.0)?$|^mozilla public license,? (version )?2\.0$/, "MPL-2.0"], [/^epl[- ]?2(\.0)?$|^eclipse public license.*2\.0/, "EPL-2.0"],
    [/^(lgpl|gnu lesser general public license)[- ,v]*(version )?2\.1/, "LGPL-2.1"], [/^(lgpl|gnu lesser general public license)[- ,v]*(version )?3/, "LGPL-3.0"],
    [/^(agpl|gnu affero general public license)[- ,v]*(version )?3/, "AGPL-3.0"],
    [/^(gpl|gnu general public license)[- ,v]*(version )?2(\.0)?$/, "GPL-2.0"], [/^(gpl|gnu general public license)[- ,v]*(version )?3(\.0)?$/, "GPL-3.0"],
    [/^all rights reserved$|^proprietary$/, "LicenseRef-All-Rights-Reserved"],
  ];
  for (const [re, id] of table) if (re.test(t)) return id;
  return null;
}

/** One licence text file -> its id by the standard wording (first match; order matters: LGPL/AGPL before GPL). */
export function licenceFromText(text: string): KnownLicence | null {
  const t = text.slice(0, 64 * 1024).replace(/\s+/g, " ");
  const has = (s: string) => t.toLowerCase().includes(s.toLowerCase());
  if (has("GNU AFFERO GENERAL PUBLIC LICENSE")) return "AGPL-3.0";
  if (has("GNU LESSER GENERAL PUBLIC LICENSE")) return has("Version 2.1") ? "LGPL-2.1" : has("Version 3") ? "LGPL-3.0" : null;
  if (has("GNU GENERAL PUBLIC LICENSE")) return has("Version 3") ? "GPL-3.0" : has("Version 2") ? "GPL-2.0" : null;
  if (has("Mozilla Public License Version 2.0") || has("Mozilla Public License, version 2.0")) return "MPL-2.0";
  if (has("Eclipse Public License - v 2.0") || has("Eclipse Public License v. 2.0")) return "EPL-2.0";
  if (has("Apache License") && (has("Version 2.0") || has("version 2.0"))) return "Apache-2.0";
  if (has("This is free and unencumbered software released into the public domain")) return "Unlicense";
  if (has("CC0 1.0 Universal")) return "CC0-1.0";
  if (has("Permission is hereby granted, free of charge, to any person obtaining a copy")) return "MIT";
  if (has("Permission to use, copy, modify, and/or distribute this software for any purpose with or without fee")) return "ISC";
  if (has("Redistribution and use in source and binary forms")) return has("Neither the name") ? "BSD-3-Clause" : "BSD-2-Clause";
  if (/\ball rights reserved\b/i.test(t) && t.length < 4000) return "LicenseRef-All-Rights-Reserved";
  return null;
}

const LICENCE_FILE_RE = /(^|\/)(LICEN[CS]E|COPYING|UNLICENSE|NOTICE)(\.(md|txt|rst))?$/i;
export const isLicenceFile = (path: string) => LICENCE_FILE_RE.test(path);

/** Every licence the files name, de-duplicated by (id, source). Empty = unknown. */
export function detectLicences(files: { path: string; text: string }[]): DetectedLicence[] {
  const out: DetectedLicence[] = [];
  const seen = new Set<string>();
  const push = (spdx: string, source: string, how: DetectedLicence["how"]) => {
    const k = `${spdx}|${source}`;
    if (seen.has(k) || out.length >= 40) return;
    seen.add(k);
    out.push({ spdx, source: source.slice(0, 200), how });
  };
  for (const f of files) {
    const head = f.text.slice(0, 16 * 1024);
    for (const m of head.matchAll(/SPDX-License-Identifier:\s*([A-Za-z0-9.+\- ()]+?)\s*(?:\*\/|-->|$)/gm)) {
      for (const part of m[1].split(/\s+(?:AND|OR|WITH)\s+|[()]/)) {
        const id = normaliseLicence(part);
        if (id) push(id, f.path, "spdx-header");
      }
    }
    if (isLicenceFile(f.path)) {
      const id = licenceFromText(f.text);
      if (id) push(id, f.path, "licence-text");
    }
    if (/(^|\/)pom\.xml$/.test(f.path)) {
      for (const m of f.text.slice(0, 256 * 1024).matchAll(/<license>\s*<name>([^<]{1,200})<\/name>/g)) {
        const id = normaliseLicence(m[1]);
        if (id) push(id, f.path, "pom");
      }
    }
  }
  return out;
}

/** The distinct ids detected, or ["unknown"]. */
export const licenceSummary = (d: DetectedLicence[]): string[] => (d.length ? [...new Set(d.map((x) => x.spdx))].sort() : ["unknown"]);

