// Cyrus import: SAFE INGESTION of an uploaded mod (MASTER-PLAN 4.9, GAPS B11 + D "Import: safe ingestion"). Pure:
// bytes in, a verdict and the cleaned file set out. NOTHING here writes to disk or runs anything: not the uploader's
// build (build.gradle*, pom.xml, gradlew, settings.* are read as TEXT for detection, then dropped), not their code.
//
// Accepted: a source ZIP (one Gradle/Maven/plain module), a plugin JAR, a datapack ZIP, a resource-pack ZIP.
// Refused before anything is inflated: oversized uploads, too many entries, traversal / absolute / backslash / NUL /
// control-character names, over-long or over-deep paths, duplicate paths (exact or case-folded), symbolic links,
// zip64 / encrypted entries, archive-level and per-entry compression-ratio bombs, a declared inflated total over the
// budget. While reading: a shared inflate budget, CRC checks (lib/cyrus/inventory/zipread.ts), nested archives at most
// IMPORT_LIMITS.maxNesting deep with the same budget. Unsupported inputs get a clear `unsupported: X` with the reason.
import { createHash } from "node:crypto";
import { indexZip, isSymlinkEntry, readEntry, type ZipEntry, type ZipIndex, type ZipLimits } from "../inventory/zipread";
import { readDescriptor, type PluginDescriptor } from "../inventory/descriptor";
import { inspectJar } from "../inventory/jar";
import { classifyDataPath, readPackMcmeta } from "../inventory/datapack";
import type { FileRole } from "../engine-core/revisions";
import { resolveDependencies, type DepResolution } from "./deps";
import { isLicenceFile } from "./licence";
import type { ImportKind } from "./attestation";

export const IMPORT_LIMITS = {
  maxUploadBytes: 25 * 1024 * 1024,
  maxEntries: 5000,
  maxEntryBytes: 8 * 1024 * 1024,
  maxTotalInflated: 96 * 1024 * 1024,
  /** Per entry (for entries over 64 KB), as in the inventory reader. */
  maxRatio: 100,
  /** Whole archive: declared inflated bytes / upload bytes, once the archive inflates to more than 8 MB. */
  maxArchiveRatio: 40,
  maxNameBytes: 400,
  maxPathDepth: 40,
  /** Archives inside the upload (jar-in-zip = 1, jar-in-jar-in-zip = 2). Deeper is refused. */
  maxNesting: 2,
  maxSourceFiles: 3000,
  maxSourceBytes: 16 * 1024 * 1024,
  maxResourceFiles: 2000,
  maxDocs: 20,
  maxDocBytes: 256 * 1024,
  maxBuildFileBytes: 256 * 1024,
  maxJarClasses: 4000,
  maxClassBytes: 1024 * 1024,
} as const;

const ZIP_LIMITS: ZipLimits = { maxEntries: IMPORT_LIMITS.maxEntries, maxEntryBytes: IMPORT_LIMITS.maxEntryBytes, maxTotalBytes: IMPORT_LIMITS.maxTotalInflated, maxRatio: IMPORT_LIMITS.maxRatio, maxNameBytes: IMPORT_LIMITS.maxNameBytes };

/** Class-file major per Java release: Paper 1.21.x runs on Java 21 (65), 26.x on Java 25 (69). */
export const javaMajorLimit = (mcVersion: string): number => (/^2[6-9]\./.test(mcVersion) ? 69 : 65);

export type Problem = { code: string; message: string };
export type UnsupportedItem = { what: string; reason: string };
export type IngestedFile = { path: string; role: FileRole; size: number; sha256: string; data: Buffer };
export type ImportDoc = { path: string; text: string };

export type Detection = {
  kind: ImportKind;
  buildSystem: "gradle" | "gradle-kotlin-dsl" | "maven" | "none" | null;
  descriptorFile: "plugin.yml" | "paper-plugin.yml" | null;
  name: string | null;
  version: string | null;
  main: string | null;
  apiVersion: string | null;
  description: string | null;
  depend: string[];
  softdepend: string[];
  commands: string[];
  permissions: string[];
  language: "java" | "kotlin" | "scala" | "groovy" | "bytecode" | null;
  sourcesComplete: boolean | null;
  missingClasses: string[];
  javaFiles: number;
  resourceFiles: number;
  ownPackages: string[];
  maxClassMajor: number | null;
  multiRelease: boolean;
  strippedSignatures: string[];
  nestedArchives: string[];
  packFormat: number | null;
  rootPrefix: string | null;
};

export type IngestOk = {
  ok: true;
  kind: ImportKind;
  uploadSha256: string;
  size: number;
  /** Kept files (paths relative to the module / pack root: src/main/java/**, src/main/resources/**, data/**, ...). */
  files: IngestedFile[];
  /** README / LICENSE / CHANGELOG ... : text DATA only (licence detection; quoted to the model, never instructions). */
  docs: ImportDoc[];
  /** The uploader's build files as text (detection and licence only; NEVER run, never sent to the build service). */
  buildTexts: ImportDoc[];
  /** Build files and other inputs dropped on purpose (paths, capped). */
  ignored: string[];
  notes: string[];
  detection: Detection;
  deps: DepResolution;
};
export type IngestFail = { ok: false; kind: ImportKind | null; uploadSha256: string; size: number; problems: Problem[]; unsupported: UnsupportedItem[]; notes: string[] };
export type IngestResult = IngestOk | IngestFail;

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const BUILD_FILE_RE = /(^|\/)(build\.gradle(\.kts)?|settings\.gradle(\.kts)?|gradle\.properties|gradlew(\.bat)?|pom\.xml|mvnw(\.cmd)?|build\.xml|ivy\.xml|Makefile|justfile|build\.sh|libs\.versions\.toml)$/;
const BUILD_DIR_RE = /(^|\/)(gradle|\.mvn|buildSrc|\.gradle|\.github|\.idea|\.vscode|build|target|out|bin|run|\.git)(\/|$)/;
const DOC_RE = /(^|\/)(README|LICEN[CS]E|COPYING|NOTICE|UNLICENSE|CHANGELOG|CHANGES|CONTRIBUTING|AUTHORS|SECURITY)(\.(md|txt|rst|markdown))?$/i;
const RESOURCE_EXT = new Set(["yml", "yaml", "json", "properties", "txt", "md", "lang", "mcmeta", "png", "jpg", "jpeg", "gif", "webp", "ogg", "wav", "nbt", "schem", "schematic", "csv", "toml", "conf", "cfg", "html", "css", "xml", "ttf", "otf", "mcfunction", "sql"]);
/** Executable code or archives: never shipped unless Cyrus compiled it. */
const CODE_EXT = new Set(["class", "jar", "zip", "war", "ear", "so", "dll", "dylib", "jnilib", "exe", "bin", "sh", "bash", "bat", "cmd", "ps1", "py", "rb", "pl", "js", "mjs", "cjs", "groovy", "kts", "kt", "scala", "lua", "dex", "apk", "7z", "rar", "gz", "tgz", "xz", "bz2", "tar"]);
const DATAPACK_EXT = new Set(["json", "mcfunction", "nbt", "mcmeta", "txt", "png"]);
const RESOURCEPACK_EXT = new Set(["json", "png", "ogg", "mcmeta", "txt", "lang", "fsh", "vsh", "glsl", "properties", "ttf", "otf", "bin"]);
const ext = (p: string) => { const b = p.split("/").pop() || ""; const i = b.lastIndexOf("."); return i > 0 ? b.slice(i + 1).toLowerCase() : ""; };
const SIG_RE = /^META-INF\/([^/]+\.(SF|RSA|DSA|EC)|SIG-[^/]+)$/i;
const ARCHIVE_RE = /\.(jar|zip)$/i;

function fail(kind: ImportKind | null, buf: Buffer, problems: Problem[], unsupported: UnsupportedItem[] = [], notes: string[] = []): IngestFail {
  return { ok: false, kind, uploadSha256: sha256(buf), size: buf.length, problems, unsupported, notes };
}

/** Name checks the inventory reader does not do (it only reports traversal): control chars, depth, length. */
function badName(name: string): string | null {
  if (/[\u0000-\u001f\u007f]/.test(name)) return "control characters in a file name";
  if (name.split("/").length > IMPORT_LIMITS.maxPathDepth) return "a path nested too deep";
  if (name.split("/").some((s) => s.length > 255)) return "a file name over 255 characters";
  if (name.split("/").includes(".")) return "a '.' path segment";
  return null;
}

/**
 * Structural checks over the central directory only (nothing inflated). Shared by the upload and every nested archive.
 * Returns the index or the problems.
 */
export function vetArchive(buf: Buffer, label: string): { ok: true; zip: ZipIndex } | { ok: false; problems: Problem[] } {
  const idx = indexZip(buf, ZIP_LIMITS);
  if (!idx.ok) {
    const bomb = /too many entries/.test(idx.error);
    return { ok: false, problems: [{ code: bomb ? "too_many_entries" : "unreadable", message: `${label}: ${idx.error}` }] };
  }
  const z = idx.zip;
  const problems: Problem[] = [];
  if (z.unsafeNames.length) problems.push({ code: "unsafe_path", message: `${label}: unsafe file names (absolute, '..' or backslash), e.g. ${z.unsafeNames[0]}` });
  const other = z.entries.map((e) => [e.name, badName(e.name)] as const).find(([, b]) => b);
  if (other) problems.push({ code: "unsafe_path", message: `${label}: ${other[1]} (${other[0].slice(0, 120)})` });
  if (z.duplicateNames.length) problems.push({ code: "duplicate_path", message: `${label}: the same path twice (${z.duplicateNames[0]})` });
  else {
    const folded = new Map<string, string>();
    for (const e of z.entries) {
      const k = e.name.toLowerCase().replace(/\/+$/, "");
      const prev = folded.get(k);
      if (prev && prev !== e.name) { problems.push({ code: "duplicate_path", message: `${label}: two paths differ only by case (${prev.slice(0, 80)} / ${e.name.slice(0, 80)})` }); break; }
      folded.set(k, e.name);
    }
  }
  const link = z.entries.find(isSymlinkEntry);
  if (link) problems.push({ code: "symlink", message: `${label}: symbolic links are not accepted (${link.name.slice(0, 120)})` });
  const enc = z.entries.find((e) => e.flags & 0x1);
  if (enc) problems.push({ code: "encrypted", message: `${label}: encrypted entries are not accepted` });
  const declared = z.entries.reduce((a, e) => a + (e.dir ? 0 : e.usize), 0);
  if (declared > IMPORT_LIMITS.maxTotalInflated) problems.push({ code: "too_large_inflated", message: `${label}: unpacks to ${Math.round(declared / 1048576)} MB (limit ${IMPORT_LIMITS.maxTotalInflated / 1048576} MB)` });
  else if (declared > 8 * 1024 * 1024 && declared / Math.max(1, buf.length) > IMPORT_LIMITS.maxArchiveRatio) problems.push({ code: "zip_bomb", message: `${label}: compression ratio ${Math.round(declared / buf.length)}:1 is too high` });
  const bomb = z.entries.find((e) => !e.dir && e.usize > 64 * 1024 && e.csize > 0 && e.usize / e.csize > IMPORT_LIMITS.maxRatio);
  if (bomb) problems.push({ code: "zip_bomb", message: `${label}: ${bomb.name.slice(0, 120)} has a suspicious compression ratio (${Math.round(bomb.usize / bomb.csize)}:1)` });
  const big = z.entries.find((e) => !e.dir && e.usize > IMPORT_LIMITS.maxEntryBytes && !ARCHIVE_RE.test(e.name));
  if (big) problems.push({ code: "file_too_large", message: `${label}: ${big.name.slice(0, 120)} is over ${IMPORT_LIMITS.maxEntryBytes / 1048576} MB` });
  const z64 = z.entries.find((e) => e.csize === 0xffffffff || e.usize === 0xffffffff || e.lho === 0xffffffff);
  if (z64) problems.push({ code: "unreadable", message: `${label}: zip64 entries are not accepted` });
  return problems.length ? { ok: false, problems } : { ok: true, zip: z };
}

function read(z: ZipIndex, e: ZipEntry, max: number): { ok: true; data: Buffer } | { ok: false; problem: Problem } {
  const r = readEntry(z, e, max);
  if (r.ok) return r;
  return { ok: false, problem: { code: r.bomb ? "zip_bomb" : "unreadable", message: `${e.name.slice(0, 120)}: ${r.error}` } };
}

/** Nested archives: index each one (within the shared budget) to the depth limit; a bomb or a too-deep chain anywhere is fatal. */
function vetNested(z: ZipIndex, depth: number, label: string, found: string[]): Problem[] {
  for (const e of z.entries) {
    if (e.dir || !ARCHIVE_RE.test(e.name)) continue;
    found.push(`${label}${e.name}`.slice(0, 200));
    if (found.length > 64) return [{ code: "too_many_archives", message: "more than 64 archives inside the upload" }];
    if (depth + 1 > IMPORT_LIMITS.maxNesting) return [{ code: "nested_too_deep", message: `archives nested more than ${IMPORT_LIMITS.maxNesting} deep (${label}${e.name.slice(0, 120)})` }];
    const r = read(z, e, IMPORT_LIMITS.maxEntryBytes);
    if (!r.ok) return [r.problem];
    const inner = vetArchive(r.data, `${label}${e.name}`.slice(0, 160));
    if (!inner.ok) return inner.problems;
    inner.zip.budget = z.budget; // one inflate budget for the whole upload
    const deeper = vetNested(inner.zip, depth + 1, `${label}${e.name}!/`, found);
    if (deeper.length) return deeper;
  }
  return [];
}

function commonRoot(names: string[]): string | null {
  const firsts = new Set(names.map((n) => (n.includes("/") ? n.slice(0, n.indexOf("/") + 1) : "")));
  if (firsts.size !== 1) return null;
  const [p] = [...firsts];
  if (!p || ["src/", "META-INF/", "data/", "assets/"].includes(p)) return null;
  return p;
}

export type IngestOptions = { filename: string; mcVersion: string };

/** The one entry point: vet, classify, extract (in memory) and detect. Never throws on hostile input. */
export function ingestUpload(buf: Buffer, opts: IngestOptions): IngestResult {
  try {
    return ingestInner(buf, opts);
  } catch (e) {
    return fail(null, Buffer.isBuffer(buf) ? buf : Buffer.alloc(0), [{ code: "unreadable", message: `could not read the upload (${String((e as Error).message || e).slice(0, 120)})` }]);
  }
}

function ingestInner(buf: Buffer, opts: IngestOptions): IngestResult {
  if (!Buffer.isBuffer(buf) || buf.length === 0) return fail(null, Buffer.alloc(0), [{ code: "empty", message: "the upload is empty" }]);
  if (buf.length > IMPORT_LIMITS.maxUploadBytes) return fail(null, buf, [{ code: "upload_too_large", message: `the upload is over ${IMPORT_LIMITS.maxUploadBytes / 1048576} MB` }]);
  const v = vetArchive(buf, "upload");
  if (!v.ok) return fail(null, buf, v.problems);
  let z = v.zip;
  const notes: string[] = [];
  // A zip whose only file is one plugin jar (a common way to send one): unwrap it once, inside the same budget.
  const files0 = z.entries.filter((e) => !e.dir);
  if (files0.length === 1 && /\.jar$/i.test(files0[0].name)) {
    const r = read(z, files0[0], IMPORT_LIMITS.maxEntryBytes);
    if (!r.ok) return fail(null, buf, [r.problem]);
    const inner = vetArchive(r.data, files0[0].name.slice(0, 120));
    if (!inner.ok) return fail(null, buf, inner.problems);
    notes.push(`Opened ${files0[0].name.slice(0, 120)} from the zip.`);
    inner.zip.budget = z.budget;
    z = inner.zip;
  }
  const names = z.entries.filter((e) => !e.dir).map((e) => e.name);
  const has = (re: RegExp) => names.some((n) => re.test(n));
  const isJar = /\.jar$/i.test(opts.filename) || ((has(/^(plugin|paper-plugin)\.yml$/) || has(/^META-INF\/MANIFEST\.MF$/)) && has(/\.class$/) && !has(/(^|\/)src\/main\//));
  if (isJar) return ingestJar(buf, z, opts, notes);
  const root = commonRoot(names);
  const rel = (n: string) => (root && n.startsWith(root) ? n.slice(root.length) : n);
  const relNames = names.map(rel);
  if (relNames.includes("pack.mcmeta") && relNames.some((n) => n.startsWith("data/"))) return ingestPack(buf, z, "datapack", root, notes);
  if (relNames.includes("pack.mcmeta") && relNames.some((n) => n.startsWith("assets/"))) return ingestPack(buf, z, "resourcepack", root, notes);
  if (relNames.some((n) => /(^|\/)src\/main\//.test(n) || BUILD_FILE_RE.test(n))) return ingestSource(buf, z, opts, root, notes);
  return fail(null, buf, [{ code: "unknown_kind", message: "this is not a plugin source zip (src/main/...), a plugin jar, a datapack or a resource pack" }], [], notes);
}

// ---------------------------------------------------------------------------------------------------------------------
// Source ZIP
// ---------------------------------------------------------------------------------------------------------------------

const IMPORT_RE = /^\s*import\s+(static\s+)?([A-Za-z_][\w]*(?:\.[A-Za-z_$][\w$]*)*(?:\.\*)?)\s*;/gm;
const PACKAGE_RE = /^\s*package\s+([A-Za-z_][\w]*(?:\.[A-Za-z_][\w]*)*)\s*;/m;

export function parseBuildCoordinates(path: string, text: string): string[] {
  const out = new Set<string>();
  if (/\.gradle(\.kts)?$/.test(path)) {
    const re = /\b(?:compileOnly|compileOnlyApi|implementation|api|compile|provided|shadow|runtimeOnly|paperLibrary|library)\s*\(?\s*(?:group\s*[:=]\s*)?["']([A-Za-z0-9_.\-]+:[A-Za-z0-9_.\-]+(?::[A-Za-z0-9_.\-+\[\]]+)?)(?::[A-Za-z0-9_.\-]+)?["']/g;
    for (const m of text.matchAll(re)) out.add(m[1]);
  } else if (/pom\.xml$/.test(path)) {
    for (const m of text.matchAll(/<dependency>([\s\S]{0,2000}?)<\/dependency>/g)) {
      const g = /<groupId>\s*([^<\s]+)\s*<\/groupId>/.exec(m[1])?.[1];
      const a = /<artifactId>\s*([^<\s]+)\s*<\/artifactId>/.exec(m[1])?.[1];
      const scope = /<scope>\s*([^<\s]+)\s*<\/scope>/.exec(m[1])?.[1];
      if (g && a && scope !== "test") out.add(`${g}:${a}`);
    }
  }
  return [...out].slice(0, 200);
}

/** What the build files say about the compile that we cannot honour (processors, Lombok, Kotlin, toolchains). */
export function buildFileUnsupported(texts: ImportDoc[]): UnsupportedItem[] {
  const out: UnsupportedItem[] = [];
  const all = texts.map((t) => t.text).join("\n");
  if (/\blombok\b|io\.freefair\.lombok/i.test(all)) out.push({ what: "Lombok", reason: "Lombok rewrites code with an annotation processor, and Cyrus compiles with annotation processing off (-proc:none). Delombok the source first." });
  if (/\bkapt\b|\bksp\s*\(|\bannotationProcessor\s*[("']|<annotationProcessorPaths>|<annotationProcessors>/.test(all)) out.push({ what: "annotation processors", reason: "the build runs annotation processors, and Cyrus compiles with annotation processing off (-proc:none), so the generated code would be missing." });
  if (/kotlin\s*\(\s*["']jvm["']|org\.jetbrains\.kotlin|kotlin-stdlib/.test(all)) out.push({ what: "Kotlin", reason: "the project uses Kotlin; Cyrus compiles Java only." });
  if (/\bscala\b|org\.scala-lang/.test(all)) out.push({ what: "Scala", reason: "the project uses Scala; Cyrus compiles Java only." });
  return out;
}

function ingestSource(buf: Buffer, z: ZipIndex, opts: IngestOptions, root: string | null, notes: string[]): IngestResult {
  const kind: ImportKind = "source";
  const all = z.entries.filter((e) => !e.dir);
  const relOf = (n: string) => (root && n.startsWith(root) ? n.slice(root.length) : n);
  // Modules: every directory that holds src/main/. One module only (the one with the plugin descriptor if several).
  const modules = new Set<string>();
  for (const e of all) { const m = /^(.*?)src\/main\//.exec(relOf(e.name)); if (m) modules.add(m[1]); }
  const descr = [...modules].filter((m) => all.some((e) => relOf(e.name) === `${m}src/main/resources/plugin.yml` || relOf(e.name) === `${m}src/main/resources/paper-plugin.yml`));
  let mod: string;
  if (modules.size === 1) mod = [...modules][0];
  else if (descr.length === 1) { mod = descr[0]; notes.push(`Multi-module project: imported the module with the plugin descriptor (${mod || "root"}); other modules were ignored.`); }
  else if (!modules.size) return fail(kind, buf, [{ code: "no_sources", message: "no src/main/java folder found" }], [], notes);
  else return fail(kind, buf, [], [{ what: "multi-module project", reason: `${descr.length ? "several" : "no"} modules have a plugin.yml (${[...modules].slice(0, 5).map((m) => m || "root").join(", ")}). Upload one module.` }], notes);

  const unsupported: UnsupportedItem[] = [];
  const problems: Problem[] = [];
  const ignored: string[] = [];
  const kept: IngestedFile[] = [];
  const docs: ImportDoc[] = [];
  const buildTexts: ImportDoc[] = [];
  const nestedFound: string[] = [];
  let srcBytes = 0, javaFiles = 0, resourceFiles = 0, otherIgnored = 0;
  let buildSystem: Detection["buildSystem"] = "none";
  const langHits = { kotlin: 0, scala: 0, groovy: 0 };

  for (const e of all) {
    const r0 = relOf(e.name);
    const inMod = r0.startsWith(mod);
    const r = inMod ? r0.slice(mod.length) : r0;
    if (BUILD_FILE_RE.test(r0)) {
      ignored.push(r0);
      if (/build\.gradle\.kts$|settings\.gradle\.kts$/.test(r0)) buildSystem = buildSystem === "maven" ? "maven" : "gradle-kotlin-dsl";
      else if (/build\.gradle$|settings\.gradle$/.test(r0) && buildSystem !== "gradle-kotlin-dsl") buildSystem = buildSystem === "maven" ? "maven" : "gradle";
      else if (/pom\.xml$/.test(r0) && buildSystem === "none") buildSystem = "maven";
      if (/\.(gradle|kts|xml|toml|properties)$/.test(r0) && e.usize <= IMPORT_LIMITS.maxBuildFileBytes) {
        const t = read(z, e, IMPORT_LIMITS.maxBuildFileBytes);
        if (t.ok) buildTexts.push({ path: r0, text: t.data.toString("utf8") });
      }
      continue;
    }
    if (/(^|\/)src\/main\/kotlin\//.test(r0) || /\.kt$/.test(r0)) langHits.kotlin++;
    if (/(^|\/)src\/main\/scala\//.test(r0) || /\.scala$/.test(r0)) langHits.scala++;
    if (/(^|\/)src\/main\/groovy\//.test(r0) || /\.groovy$/.test(r0)) langHits.groovy++;
    if (inMod && r.startsWith("src/main/java/")) {
      if (!r.endsWith(".java")) {
        if (CODE_EXT.has(ext(r))) unsupported.push({ what: `non-Java code in src/main/java (${r.slice(0, 120)})`, reason: "Cyrus compiles Java sources only and never ships code it did not compile." });
        else { ignored.push(r0); }
        continue;
      }
      if (/(^|\/)module-info\.java$/.test(r) || /(^|\/)package-info\.java$/.test(r) && false) { unsupported.push({ what: "Java modules (module-info.java)", reason: "Paper plugins are not JPMS modules; remove module-info.java." }); continue; }
      if (++javaFiles > IMPORT_LIMITS.maxSourceFiles) { problems.push({ code: "too_many_files", message: `more than ${IMPORT_LIMITS.maxSourceFiles} Java files` }); break; }
      const d = read(z, e, IMPORT_LIMITS.maxEntryBytes);
      if (!d.ok) { problems.push(d.problem); break; }
      if (d.data.includes(0)) { problems.push({ code: "binary_source", message: `${r.slice(0, 120)} is not a text file` }); break; }
      srcBytes += d.data.length;
      kept.push({ path: r, role: "source", size: d.data.length, sha256: sha256(d.data), data: d.data });
      continue;
    }
    if (inMod && r.startsWith("src/main/resources/")) {
      const x = ext(r);
      if (ARCHIVE_RE.test(r) || CODE_EXT.has(x)) { unsupported.push({ what: `binary code in resources (${r.slice(0, 120)})`, reason: "resources may not contain jars, classes, archives, native libraries or scripts: Cyrus never ships code it did not compile." }); continue; }
      if (/^src\/main\/resources\/META-INF\/services\/javax\.annotation\.processing\.Processor$/.test(r)) { unsupported.push({ what: "annotation processors", reason: "the project registers an annotation processor; Cyrus compiles with -proc:none." }); continue; }
      if (/^src\/main\/resources\/META-INF\//.test(r)) { ignored.push(r0); continue; }
      if (!RESOURCE_EXT.has(x)) { ignored.push(r0); notes.push(`Left out ${r.slice(0, 120)} (file type .${x || "none"} is not kept in plugin resources).`); continue; }
      if (++resourceFiles > IMPORT_LIMITS.maxResourceFiles) { problems.push({ code: "too_many_files", message: `more than ${IMPORT_LIMITS.maxResourceFiles} resource files` }); break; }
      const d = read(z, e, IMPORT_LIMITS.maxEntryBytes);
      if (!d.ok) { problems.push(d.problem); break; }
      srcBytes += d.data.length;
      const role: FileRole = /^src\/main\/resources\/(plugin|paper-plugin|config)\.yml$/.test(r) ? "config" : "resource";
      kept.push({ path: r, role, size: d.data.length, sha256: sha256(d.data), data: d.data });
      continue;
    }
    if (DOC_RE.test(r0) && r0.split("/").length <= 2 + (mod ? mod.split("/").length - 1 : 0) && docs.length < IMPORT_LIMITS.maxDocs && e.usize <= IMPORT_LIMITS.maxDocBytes) {
      const d = read(z, e, IMPORT_LIMITS.maxDocBytes);
      if (d.ok && !d.data.includes(0)) docs.push({ path: r0, text: d.data.toString("utf8") });
      continue;
    }
    if (ARCHIVE_RE.test(r0)) { nestedFound.push(r0.slice(0, 200)); ignored.push(r0); continue; }
    if (BUILD_DIR_RE.test(r0)) { ignored.push(r0); continue; }
    otherIgnored++;
  }
  if (srcBytes > IMPORT_LIMITS.maxSourceBytes) problems.push({ code: "too_large", message: `the kept sources are over ${IMPORT_LIMITS.maxSourceBytes / 1048576} MB` });
  if (problems.length) return fail(kind, buf, problems, unsupported, notes);
  if (otherIgnored) notes.push(`${otherIgnored} other file${otherIgnored > 1 ? "s" : ""} outside src/main (tests, docs folders, IDE files) were not imported.`);
  if (nestedFound.length) notes.push(`Bundled archives were ignored (${nestedFound.slice(0, 3).join(", ")}${nestedFound.length > 3 ? ", ..." : ""}): dependencies come only from Cyrus's allowlist.`);
  if (langHits.kotlin) unsupported.push({ what: "Kotlin", reason: "the project contains Kotlin sources; Cyrus compiles Java only." });
  if (langHits.scala) unsupported.push({ what: "Scala", reason: "the project contains Scala sources; Cyrus compiles Java only." });
  if (langHits.groovy) unsupported.push({ what: "Groovy", reason: "the project contains Groovy sources; Cyrus compiles Java only." });
  unsupported.push(...buildFileUnsupported(buildTexts));

  // Java: packages, imports, Lombok / processor-driven annotations, completeness.
  const java = kept.filter((f) => f.role === "source");
  const ownPackages = new Set<string>();
  const ownClasses = new Set<string>();
  const imports: string[] = [];
  for (const f of java) {
    const t = f.data.toString("utf8");
    const pkg = PACKAGE_RE.exec(t)?.[1] ?? "";
    if (pkg) ownPackages.add(pkg);
    ownClasses.add((pkg ? pkg + "." : "") + f.path.split("/").pop()!.replace(/\.java$/, ""));
    for (const m of t.matchAll(IMPORT_RE)) imports.push((m[1] ? "static " : "") + m[2]);
    if (/^\s*import\s+lombok\./m.test(t) && !unsupported.some((u) => u.what === "Lombok")) unsupported.push({ what: "Lombok", reason: "the code uses Lombok, which needs an annotation processor; Cyrus compiles with -proc:none. Delombok the source first." });
  }
  const descriptorEntry = kept.find((f) => f.path === "src/main/resources/paper-plugin.yml") ?? kept.find((f) => f.path === "src/main/resources/plugin.yml");
  let d: PluginDescriptor | null = null;
  if (!descriptorEntry) problems.push({ code: "no_descriptor", message: "src/main/resources/plugin.yml is missing" });
  else d = readDescriptor(descriptorEntry.data.toString("utf8"), descriptorEntry.path.endsWith("paper-plugin.yml") ? "paper-plugin.yml" : "plugin.yml");
  if (kept.some((f) => f.path === "src/main/resources/paper-plugin.yml")) unsupported.push({ what: "paper-plugin.yml", reason: "Paper's own plugin format is experimental and its loader/bootstrapper classes can fetch libraries at runtime. Cyrus builds plugin.yml plugins: add a plugin.yml (and remove paper-plugin.yml)." });
  if (d) {
    if (d.libraries.length) unsupported.push({ what: "plugin.yml libraries", reason: `Paper downloads these from Maven when the server starts (${d.libraries.slice(0, 3).join(", ")}); Cyrus does not allow runtime downloads.` });
    if (d.name && !/^[A-Za-z0-9_.-]{1,64}$/.test(d.name)) unsupported.push({ what: "plugin name", reason: `"${d.name.slice(0, 64)}" has spaces or other characters Cyrus does not build; use letters, digits, '_', '-' or '.'.` });
    if (!d.name) problems.push({ code: "bad_descriptor", message: "plugin.yml has no name" });
    if (!d.version) problems.push({ code: "bad_descriptor", message: "plugin.yml has no version" });
  }
  const main = d?.main ?? null;
  const missing: string[] = [];
  if (main && !ownClasses.has(main)) missing.push(main);
  // Imports of the project's own group (the main class's first two package segments) must resolve to an uploaded file.
  const group = main ? main.split(".").slice(0, Math.max(1, Math.min(2, main.split(".").length - 2))).join(".") : null;
  const isOwnish = (n: string) => !!group && (n === group || n.startsWith(group + "."));
  for (const raw of imports) {
    const n = raw.replace(/^static\s+/, "");
    if (!isOwnish(n)) continue;
    if (n.endsWith(".*")) { const p = n.slice(0, -2); if (!ownPackages.has(p) && ![...ownClasses].some((c) => c === p)) missing.push(n); continue; }
    const segs = n.split(".");
    let ok = false;
    for (let i = segs.length; i >= 2 && !ok; i--) if (ownClasses.has(segs.slice(0, i).join("."))) ok = true;
    if (!ok && !ownPackages.has(segs.slice(0, -1).join("."))) missing.push(n);
    else if (!ok) missing.push(n);
  }
  const missingU = [...new Set(missing)].slice(0, 20);
  if (missingU.length) unsupported.push({ what: "incomplete sources", reason: `these classes are referenced but not in the upload: ${missingU.slice(0, 6).join(", ")}${missingU.length > 6 ? ", ..." : ""}` });
  const deps = resolveDependencies({
    coordinates: buildTexts.flatMap((t) => parseBuildCoordinates(t.path, t.text)).filter((c) => !/:(junit|mockito|assertj)/.test(c)),
    imports: imports.filter((n) => !isOwnish(n.replace(/^static\s+/, ""))),
    pluginDepends: [...(d?.depend ?? []), ...(d?.softdepend ?? [])],
    ownPackages: [...ownPackages],
  });
  // Build-file coordinates are hints, not requirements: only imports the CODE really makes are fatal.
  const fromImports = deps.unsupported.filter((u) => u.source === "import");
  for (const u of deps.unsupported.filter((x) => x.source === "build-file")) notes.push(`The build file declares ${u.what}, which Cyrus does not provide (${u.reason.split(".")[0]}). Your code does not import it, so it was ignored.`);
  for (const u of fromImports) unsupported.push({ what: `unsupported dependency: ${u.what}`, reason: u.reason });
  if (!java.length) problems.push({ code: "no_sources", message: "no Java files in src/main/java" });
  const uniqueUnsupported = dedupeUnsupported(unsupported);
  const detection: Detection = {
    kind, buildSystem, descriptorFile: d?.file ?? null, name: d?.name ?? null, version: d?.version ?? null, main, apiVersion: d?.apiVersion ?? null,
    description: descriptionOf(descriptorEntry?.data), depend: d?.depend ?? [], softdepend: d?.softdepend ?? [],
    commands: (d?.commands ?? []).map((c) => c.name).slice(0, 100), permissions: (d?.permissions ?? []).map((p) => p.name).slice(0, 200),
    language: langHits.kotlin ? "kotlin" : langHits.scala ? "scala" : langHits.groovy ? "groovy" : "java",
    sourcesComplete: !!main && missingU.length === 0, missingClasses: missingU, javaFiles: java.length, resourceFiles: kept.length - java.length,
    ownPackages: [...ownPackages].sort().slice(0, 100), maxClassMajor: null, multiRelease: false, strippedSignatures: [], nestedArchives: nestedFound.slice(0, 20), packFormat: null,
    rootPrefix: root,
  };
  if (problems.length || uniqueUnsupported.length) return { ...fail(kind, buf, problems, uniqueUnsupported, notes) };
  if (buildSystem !== "none") notes.push(`Your ${buildSystem === "maven" ? "Maven" : "Gradle"} build files were not used and never run: Cyrus compiles src/main/java with its own pinned toolchain.`);
  return { ok: true, kind, uploadSha256: sha256(buf), size: buf.length, files: kept, docs, buildTexts, ignored: ignored.slice(0, 50), notes, detection, deps };
}

function descriptionOf(b: Buffer | undefined): string | null {
  if (!b) return null;
  const m = /^description:\s*['"]?(.+?)['"]?\s*$/m.exec(b.toString("utf8"));
  return m ? m[1].slice(0, 300) : null;
}

function dedupeUnsupported(list: UnsupportedItem[]): UnsupportedItem[] {
  const seen = new Set<string>();
  return list.filter((u) => (seen.has(u.what) ? false : (seen.add(u.what), true))).slice(0, 30);
}

// ---------------------------------------------------------------------------------------------------------------------
// Plugin JAR (analysis + diagnosis only: never rebuilt, never "safely modified")
// ---------------------------------------------------------------------------------------------------------------------

function ingestJar(buf: Buffer, z: ZipIndex, opts: IngestOptions, notes: string[]): IngestResult {
  const kind: ImportKind = "jar";
  const nested: string[] = [];
  const nestedProblems = vetNested(z, 0, "", nested);
  if (nestedProblems.length) return fail(kind, buf, nestedProblems, [], notes);
  // The descriptor + bytecode summary come from the inventory reader (bounded, never extracts).
  const jarBytes = z.buf;
  const info = inspectJar(opts.filename.slice(0, 120), opts.filename.slice(0, 120), jarBytes, { zipLimits: ZIP_LIMITS });
  if (info.flags.unreadable) return fail(kind, buf, [{ code: "unreadable", message: info.flags.unreadable }], [], notes);
  if (info.flags.bombEntries.length) return fail(kind, buf, [{ code: "zip_bomb", message: `entries that inflate suspiciously: ${info.flags.bombEntries[0]}` }], [], notes);
  if (info.flags.serverJar) return fail(kind, buf, [], [{ what: "a server jar", reason: `this is a Minecraft/Paper server jar (${info.flags.serverJarEvidence}), not a plugin.` }], notes);
  const unsupported: UnsupportedItem[] = [];
  const d = info.descriptor;
  if (!d) return fail(kind, buf, [{ code: "no_descriptor", message: "the jar has no plugin.yml or paper-plugin.yml (is it a library or a client mod?)" }], [], notes);
  const limit = javaMajorLimit(opts.mcVersion);
  const major = info.bytecode?.maxClassMajor ?? null;
  if (major && major > limit) unsupported.push({ what: `Java ${major - 44} classes`, reason: `the jar is compiled for Java ${major - 44}, but Paper ${opts.mcVersion} runs on Java ${limit - 44}.` });
  const strippedSignatures: string[] = [];
  const classes: IngestedFile[] = [];
  let multiRelease = false;
  const problems: Problem[] = [];
  const manifest = z.entries.find((e) => e.name === "META-INF/MANIFEST.MF");
  if (manifest) { const m = read(z, manifest, 256 * 1024); if (m.ok && /^Multi-Release:\s*true\s*$/im.test(m.data.toString("latin1"))) multiRelease = true; }
  for (const e of z.entries) {
    if (e.dir) continue;
    if (SIG_RE.test(e.name)) { strippedSignatures.push(e.name.slice(0, 120)); continue; }
    if (e.name.startsWith("META-INF/versions/")) multiRelease = true;
    if (!e.name.endsWith(".class")) continue;
    if (classes.length >= IMPORT_LIMITS.maxJarClasses) { notes.push(`Only the first ${IMPORT_LIMITS.maxJarClasses} classes were analysed.`); break; }
    const r = read(z, e, IMPORT_LIMITS.maxClassBytes);
    if (!r.ok) { problems.push(r.problem); break; }
    if (r.data.length < 10 || r.data.readUInt32BE(0) !== 0xcafebabe) { problems.push({ code: "bad_class", message: `${e.name.slice(0, 120)} is not a class file` }); break; }
    const m = r.data.readUInt16BE(6);
    if (m > limit && !e.name.startsWith("META-INF/versions/")) { /* counted by the summary above */ }
    classes.push({ path: e.name, role: "artifact", size: r.data.length, sha256: sha256(r.data), data: r.data });
  }
  if (problems.length) return fail(kind, buf, problems, unsupported, notes);
  if (strippedSignatures.length) notes.push(`The jar's signature files were removed from the analysis (${strippedSignatures.length}); signatures are never kept on files Cyrus handles.`);
  if (multiRelease) notes.push("Multi-release jar: the versioned classes under META-INF/versions were analysed too (they can run on newer Java).");
  if (nested.length) notes.push(`The jar contains ${nested.length} nested archive${nested.length > 1 ? "s" : ""}: Paper does not load them; any code that would load them is blocked by the check.`);
  if (d.libraries.length) notes.push(`plugin.yml asks Paper to download libraries at startup (${d.libraries.slice(0, 3).join(", ")}).`);
  notes.push("Jar-only import: Cyrus analyses and diagnoses it but cannot change it. Upload the source to work on it.");
  const desc = z.entries.find((e) => e.name === (d.file === "paper-plugin.yml" ? "paper-plugin.yml" : "plugin.yml"));
  const descBuf = desc ? read(z, desc, 256 * 1024) : null;
  const files: IngestedFile[] = [...classes];
  if (descBuf && descBuf.ok) files.push({ path: d.file, role: "config", size: descBuf.data.length, sha256: sha256(descBuf.data), data: descBuf.data });
  const detection: Detection = {
    kind, buildSystem: null, descriptorFile: d.file, name: d.name, version: d.version, main: d.main, apiVersion: d.apiVersion,
    description: descriptionOf(descBuf && descBuf.ok ? descBuf.data : undefined), depend: d.depend, softdepend: d.softdepend,
    commands: d.commands.map((c) => c.name).slice(0, 100), permissions: d.permissions.map((p) => p.name).slice(0, 200), language: "bytecode",
    sourcesComplete: null, missingClasses: [], javaFiles: 0, resourceFiles: 0, ownPackages: [], maxClassMajor: major, multiRelease, strippedSignatures: strippedSignatures.slice(0, 20),
    nestedArchives: nested.slice(0, 20), packFormat: null, rootPrefix: null,
  };
  if (unsupported.length) return fail(kind, buf, [], unsupported, notes);
  const deps: DepResolution = { allowed: [], provided: [], unsupported: [], runtimeOnly: [...d.depend, ...d.softdepend] };
  return { ok: true, kind, uploadSha256: sha256(buf), size: buf.length, files, docs: [], buildTexts: [], ignored: [], notes, detection, deps };
}

// ---------------------------------------------------------------------------------------------------------------------
// Datapack / resource pack ZIP (structure check; no code)
// ---------------------------------------------------------------------------------------------------------------------

function ingestPack(buf: Buffer, z: ZipIndex, kind: "datapack" | "resourcepack", root: string | null, notes: string[]): IngestResult {
  const allow = kind === "datapack" ? DATAPACK_EXT : RESOURCEPACK_EXT;
  const files: IngestedFile[] = [];
  const unsupported: UnsupportedItem[] = [];
  const ignored: string[] = [];
  const docs: ImportDoc[] = [];
  let total = 0;
  for (const e of z.entries) {
    if (e.dir) continue;
    const r = root && e.name.startsWith(root) ? e.name.slice(root.length) : e.name;
    const x = ext(r);
    if (ARCHIVE_RE.test(r) || (CODE_EXT.has(x) && !(kind === "resourcepack" && x === "bin"))) { unsupported.push({ what: `code or archives in a ${kind} (${r.slice(0, 120)})`, reason: "packs may only contain data files." }); continue; }
    if (DOC_RE.test(r) && !r.includes("/")) { const d = read(z, e, IMPORT_LIMITS.maxDocBytes); if (d.ok) docs.push({ path: r, text: d.data.toString("utf8") }); continue; }
    const inTree = r === "pack.mcmeta" || r === "pack.png" || (kind === "datapack" ? r.startsWith("data/") : r.startsWith("assets/"));
    if (!inTree || !allow.has(x)) { ignored.push(r); continue; }
    if (files.length >= IMPORT_LIMITS.maxEntries) break;
    const d = read(z, e, IMPORT_LIMITS.maxEntryBytes);
    if (!d.ok) return fail(kind, buf, [d.problem], unsupported, notes);
    total += d.data.length;
    files.push({ path: r, role: kind === "datapack" ? "dataPack" : "resourcePack", size: d.data.length, sha256: sha256(d.data), data: d.data });
  }
  const mcmeta = files.find((f) => f.path === "pack.mcmeta");
  const fmt = readPackMcmeta(mcmeta?.data ?? null);
  if (!fmt || fmt.packFormat == null) return fail(kind, buf, [{ code: "bad_pack", message: "pack.mcmeta is missing or has no pack.pack_format" }], unsupported, notes);
  if (kind === "datapack") {
    const typed = files.filter((f) => classifyDataPath(f.path)).length;
    if (!typed) notes.push("No recognised datapack files (data/<namespace>/<type>/...) were found.");
  } else if (files.some((f) => /\.(fsh|vsh|glsl)$/.test(f.path))) notes.push("The pack overrides shaders: shader files cannot be merged with other packs.");
  if (ignored.length) notes.push(`${ignored.length} file${ignored.length > 1 ? "s" : ""} outside the pack tree or of other types were left out.`);
  if (unsupported.length) return fail(kind, buf, [], dedupeUnsupported(unsupported), notes);
  const detection: Detection = {
    kind, buildSystem: null, descriptorFile: null, name: fmt.description ? fmt.description.slice(0, 64) : null, version: null, main: null, apiVersion: null, description: fmt.description,
    depend: [], softdepend: [], commands: [], permissions: [], language: null, sourcesComplete: null, missingClasses: [], javaFiles: 0, resourceFiles: files.length,
    ownPackages: [], maxClassMajor: null, multiRelease: false, strippedSignatures: [], nestedArchives: [], packFormat: fmt.packFormat, rootPrefix: root,
  };
  void total;
  return { ok: true, kind, uploadSha256: sha256(buf), size: buf.length, files, docs, buildTexts: [], ignored: ignored.slice(0, 50), notes, detection, deps: { allowed: [], provided: [], unsupported: [], runtimeOnly: [] } };
}

/** Licence inputs: docs, build texts (pom licences) and the first lines of source files (SPDX headers). */
export function licenceInputs(r: IngestOk): { path: string; text: string }[] {
  const heads = r.files.filter((f) => f.role === "source").slice(0, 400).map((f) => ({ path: f.path, text: f.data.subarray(0, 2048).toString("utf8") }));
  return [...r.docs.filter((d) => isLicenceFile(d.path) || /readme/i.test(d.path)), ...r.buildTexts, ...heads];
}

toolu_01KPy7BtFdqwK6RLN51Q6yH9.content:
// Cyrus import: SAFE INGESTION of an uploaded mod (MASTER-PLAN 4.9, GAPS B11 + D "Import: safe ingestion"). Pure:
// bytes in, a verdict and the cleaned file set out. NOTHING here writes to disk or runs anything: not the uploader's
// build (build.gradle*, pom.xml, gradlew, settings.* are read as TEXT for detection, then dropped), not their code.
//
// Accepted: a source ZIP (one Gradle/Maven/plain module), a plugin JAR, a datapack ZIP, a resource-pack ZIP.
// Refused before anything is inflated: oversized uploads, too many entries, traversal / absolute / backslash / NUL /
// control-character names, over-long or over-deep paths, duplicate paths (exact or case-folded), symbolic links,
// zip64 / encrypted entries, archive-level and per-entry compression-ratio bombs, a declared inflated total over the
// budget. While reading: a shared inflate budget, CRC checks (lib/cyrus/inventory/zipread.ts), nested archives at most
// IMPORT_LIMITS.maxNesting deep with the same budget. Unsupported inputs get a clear `unsupported: X` with the reason.
import { createHash } from "node:crypto";
import { indexZip, isSymlinkEntry, readEntry, type ZipEntry, type ZipIndex, type ZipLimits } from "../inventory/zipread";
import { readDescriptor, type PluginDescriptor } from "../inventory/descriptor";
import { inspectJar } from "../inventory/jar";
import { classifyDataPath, readPackMcmeta } from "../inventory/datapack";
import type { FileRole } from "../engine-core/revisions";
import { resolveDependencies, type DepResolution } from "./deps";
import { isLicenceFile } from "./licence";
import type { ImportKind } from "./attestation";

export const IMPORT_LIMITS = {
  maxUploadBytes: 25 * 1024 * 1024,
  maxEntries: 5000,
  maxEntryBytes: 8 * 1024 * 1024,
  maxTotalInflated: 96 * 1024 * 1024,
  /** Per entry (for entries over 64 KB), as in the inventory reader. */
  maxRatio: 100,
  /** Whole archive: declared inflated bytes / upload bytes, once the archive inflates to more than 8 MB. */
  maxArchiveRatio: 40,
  maxNameBytes: 400,
  maxPathDepth: 40,
  /** Archives inside the upload (jar-in-zip = 1, jar-in-jar-in-zip = 2). Deeper is refused. */
  maxNesting: 2,
  maxSourceFiles: 3000,
  maxSourceBytes: 16 * 1024 * 1024,
  maxResourceFiles: 2000,
  maxDocs: 20,
  maxDocBytes: 256 * 1024,
  maxBuildFileBytes: 256 * 1024,
  maxJarClasses: 4000,
  maxClassBytes: 1024 * 1024,
} as const;

const ZIP_LIMITS: ZipLimits = { maxEntries: IMPORT_LIMITS.maxEntries, maxEntryBytes: IMPORT_LIMITS.maxEntryBytes, maxTotalBytes: IMPORT_LIMITS.maxTotalInflated, maxRatio: IMPORT_LIMITS.maxRatio, maxNameBytes: IMPORT_LIMITS.maxNameBytes };

/** Class-file major per Java release: Paper 1.21.x runs on Java 21 (65), 26.x on Java 25 (69). */
export const javaMajorLimit = (mcVersion: string): number => (/^2[6-9]\./.test(mcVersion) ? 69 : 65);

export type Problem = { code: string; message: string };
export type UnsupportedItem = { what: string; reason: string };
export type IngestedFile = { path: string; role: FileRole; size: number; sha256: string; data: Buffer };
export type ImportDoc = { path: string; text: string };

export type Detection = {
  kind: ImportKind;
  buildSystem: "gradle" | "gradle-kotlin-dsl" | "maven" | "none" | null;
  descriptorFile: "plugin.yml" | "paper-plugin.yml" | null;
  name: string | null;
  version: string | null;
  main: string | null;
  apiVersion: string | null;
  description: string | null;
  depend: string[];
  softdepend: string[];
  commands: string[];
  permissions: string[];
  language: "java" | "kotlin" | "scala" | "groovy" | "bytecode" | null;
  sourcesComplete: boolean | null;
  missingClasses: string[];
  javaFiles: number;
  resourceFiles: number;
  ownPackages: string[];
  maxClassMajor: number | null;
  multiRelease: boolean;
  strippedSignatures: string[];
  nestedArchives: string[];
  packFormat: number | null;
  rootPrefix: string | null;
};

export type IngestOk = {
  ok: true;
  kind: ImportKind;
  uploadSha256: string;
  size: number;
  /** Kept files (paths relative to the module / pack root: src/main/java/**, src/main/resources/**, data/**, ...). */
  files: IngestedFile[];
  /** README / LICENSE / CHANGELOG ... : text DATA only (licence detection; quoted to the model, never instructions). */
  docs: ImportDoc[];
  /** The uploader's build files as text (detection and licence only; NEVER run, never sent to the build service). */
  buildTexts: ImportDoc[];
  /** Build files and other inputs dropped on purpose (paths, capped). */
  ignored: string[];
  notes: string[];
  detection: Detection;
  deps: DepResolution;
};
export type IngestFail = { ok: false; kind: ImportKind | null; uploadSha256: string; size: number; problems: Problem[]; unsupported: UnsupportedItem[]; notes: string[] };
export type IngestResult = IngestOk | IngestFail;

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const BUILD_FILE_RE = /(^|\/)(build\.gradle(\.kts)?|settings\.gradle(\.kts)?|gradle\.properties|gradlew(\.bat)?|pom\.xml|mvnw(\.cmd)?|build\.xml|ivy\.xml|Makefile|justfile|build\.sh|libs\.versions\.toml)$/;
const BUILD_DIR_RE = /(^|\/)(gradle|\.mvn|buildSrc|\.gradle|\.github|\.idea|\.vscode|build|target|out|bin|run|\.git)(\/|$)/;
const DOC_RE = /(^|\/)(README|LICEN[CS]E|COPYING|NOTICE|UNLICENSE|CHANGELOG|CHANGES|CONTRIBUTING|AUTHORS|SECURITY)(\.(md|txt|rst|markdown))?$/i;
const RESOURCE_EXT = new Set(["yml", "yaml", "json", "properties", "txt", "md", "lang", "mcmeta", "png", "jpg", "jpeg", "gif", "webp", "ogg", "wav", "nbt", "schem", "schematic", "csv", "toml", "conf", "cfg", "html", "css", "xml", "ttf", "otf", "mcfunction", "sql"]);
/** Executable code or archives: never shipped unless Cyrus compiled it. */
const CODE_EXT = new Set(["class", "jar", "zip", "war", "ear", "so", "dll", "dylib", "jnilib", "exe", "bin", "sh", "bash", "bat", "cmd", "ps1", "py", "rb", "pl", "js", "mjs", "cjs", "groovy", "kts", "kt", "scala", "lua", "dex", "apk", "7z", "rar", "gz", "tgz", "xz", "bz2", "tar"]);
const DATAPACK_EXT = new Set(["json", "mcfunction", "nbt", "mcmeta", "txt", "png"]);
const RESOURCEPACK_EXT = new Set(["json", "png", "ogg", "mcmeta", "txt", "lang", "fsh", "vsh", "glsl", "properties", "ttf", "otf", "bin"]);
const ext = (p: string) => { const b = p.split("/").pop() || ""; const i = b.lastIndexOf("."); return i > 0 ? b.slice(i + 1).toLowerCase() : ""; };
const SIG_RE = /^META-INF\/([^/]+\.(SF|RSA|DSA|EC)|SIG-[^/]+)$/i;
const ARCHIVE_RE = /\.(jar|zip)$/i;

function fail(kind: ImportKind | null, buf: Buffer, problems: Problem[], unsupported: UnsupportedItem[] = [], notes: string[] = []): IngestFail {
  return { ok: false, kind, uploadSha256: sha256(buf), size: buf.length, problems, unsupported, notes };
}

/** Name checks the inventory reader does not do (it only reports traversal): control chars, depth, length. */
function badName(name: string): string | null {
  if (/[\u0000-\u001f\u007f]/.test(name)) return "control characters in a file name";
  if (name.split("/").length > IMPORT_LIMITS.maxPathDepth) return "a path nested too deep";
  if (name.split("/").some((s) => s.length > 255)) return "a file name over 255 characters";
  if (name.split("/").includes(".")) return "a '.' path segment";
  return null;
}

/**
 * Structural checks over the central directory only (nothing inflated). Shared by the upload and every nested archive.
 * Returns the index or the problems.
 */
export function vetArchive(buf: Buffer, label: string): { ok: true; zip: ZipIndex } | { ok: false; problems: Problem[] } {
  const idx = indexZip(buf, ZIP_LIMITS);
  if (!idx.ok) {
    const bomb = /too many entries/.test(idx.error);
    return { ok: false, problems: [{ code: bomb ? "too_many_entries" : "unreadable", message: `${label}: ${idx.error}` }] };
  }
  const z = idx.zip;
  const problems: Problem[] = [];
  if (z.unsafeNames.length) problems.push({ code: "unsafe_path", message: `${label}: unsafe file names (absolute, '..' or backslash), e.g. ${z.unsafeNames[0]}` });
  const other = z.entries.map((e) => [e.name, badName(e.name)] as const).find(([, b]) => b);
  if (other) problems.push({ code: "unsafe_path", message: `${label}: ${other[1]} (${other[0].slice(0, 120)})` });
  if (z.duplicateNames.length) problems.push({ code: "duplicate_path", message: `${label}: the same path twice (${z.duplicateNames[0]})` });
  else {
    const folded = new Map<string, string>();
    for (const e of z.entries) {
      const k = e.name.toLowerCase().replace(/\/+$/, "");
      const prev = folded.get(k);
      if (prev && prev !== e.name) { problems.push({ code: "duplicate_path", message: `${label}: two paths differ only by case (${prev.slice(0, 80)} / ${e.name.slice(0, 80)})` }); break; }
      folded.set(k, e.name);
    }
  }
  const link = z.entries.find(isSymlinkEntry);
  if (link) problems.push({ code: "symlink", message: `${label}: symbolic links are not accepted (${link.name.slice(0, 120)})` });
  const enc = z.entries.find((e) => e.flags & 0x1);
  if (enc) problems.push({ code: "encrypted", message: `${label}: encrypted entries are not accepted` });
  const declared = z.entries.reduce((a, e) => a + (e.dir ? 0 : e.usize), 0);
  if (declared > IMPORT_LIMITS.maxTotalInflated) problems.push({ code: "too_large_inflated", message: `${label}: unpacks to ${Math.round(declared / 1048576)} MB (limit ${IMPORT_LIMITS.maxTotalInflated / 1048576} MB)` });
  else if (declared > 8 * 1024 * 1024 && declared / Math.max(1, buf.length) > IMPORT_LIMITS.maxArchiveRatio) problems.push({ code: "zip_bomb", message: `${label}: compression ratio ${Math.round(declared / buf.length)}:1 is too high` });
  const bomb = z.entries.find((e) => !e.dir && e.usize > 64 * 1024 && e.csize > 0 && e.usize / e.csize > IMPORT_LIMITS.maxRatio);
  if (bomb) problems.push({ code: "zip_bomb", message: `${label}: ${bomb.name.slice(0, 120)} has a suspicious compression ratio (${Math.round(bomb.usize / bomb.csize)}:1)` });
  const big = z.entries.find((e) => !e.dir && e.usize > IMPORT_LIMITS.maxEntryBytes && !ARCHIVE_RE.test(e.name));
  if (big) problems.push({ code: "file_too_large", message: `${label}: ${big.name.slice(0, 120)} is over ${IMPORT_LIMITS.maxEntryBytes / 1048576} MB` });
  const z64 = z.entries.find((e) => e.csize === 0xffffffff || e.usize === 0xffffffff || e.lho === 0xffffffff);
  if (z64) problems.push({ code: "unreadable", message: `${label}: zip64 entries are not accepted` });
  return problems.length ? { ok: false, problems } : { ok: true, zip: z };
}

function read(z: ZipIndex, e: ZipEntry, max: number): { ok: true; data: Buffer } | { ok: false; problem: Problem } {
  const r = readEntry(z, e, max);
  if (r.ok) return r;
  return { ok: false, problem: { code: r.bomb ? "zip_bomb" : "unreadable", message: `${e.name.slice(0, 120)}: ${r.error}` } };
}

/** Nested archives: index each one (within the shared budget) to the depth limit; a bomb or a too-deep chain anywhere is fatal. */
function vetNested(z: ZipIndex, depth: number, label: string, found: string[]): Problem[] {
  for (const e of z.entries) {
    if (e.dir || !ARCHIVE_RE.test(e.name)) continue;
    found.push(`${label}${e.name}`.slice(0, 200));
    if (found.length > 64) return [{ code: "too_many_archives", message: "more than 64 archives inside the upload" }];
    if (depth + 1 > IMPORT_LIMITS.maxNesting) return [{ code: "nested_too_deep", message: `archives nested more than ${IMPORT_LIMITS.maxNesting} deep (${label}${e.name.slice(0, 120)})` }];
    const r = read(z, e, IMPORT_LIMITS.maxEntryBytes);
    if (!r.ok) return [r.problem];
    const inner = vetArchive(r.data, `${label}${e.name}`.slice(0, 160));
    if (!inner.ok) return inner.problems;
    inner.zip.budget = z.budget; // one inflate budget for the whole upload
    const deeper = vetNested(inner.zip, depth + 1, `${label}${e.name}!/`, found);
    if (deeper.length) return deeper;
  }
  return [];
}

function commonRoot(names: string[]): string | null {
  const firsts = new Set(names.map((n) => (n.includes("/") ? n.slice(0, n.indexOf("/") + 1) : "")));
  if (firsts.size !== 1) return null;
  const [p] = [...firsts];
  if (!p || ["src/", "META-INF/", "data/", "assets/"].includes(p)) return null;
  return p;
}

export type IngestOptions = { filename: string; mcVersion: string };

/** The one entry point: vet, classify, extract (in memory) and detect. Never throws on hostile input. */
export function ingestUpload(buf: Buffer, opts: IngestOptions): IngestResult {
  try {
    return ingestInner(buf, opts);
  } catch (e) {
    return fail(null, Buffer.isBuffer(buf) ? buf : Buffer.alloc(0), [{ code: "unreadable", message: `could not read the upload (${String((e as Error).message || e).slice(0, 120)})` }]);
  }
}

function ingestInner(buf: Buffer, opts: IngestOptions): IngestResult {
  if (!Buffer.isBuffer(buf) || buf.length === 0) return fail(null, Buffer.alloc(0), [{ code: "empty", message: "the upload is empty" }]);
  if (buf.length > IMPORT_LIMITS.maxUploadBytes) return fail(null, buf, [{ code: "upload_too_large", message: `the upload is over ${IMPORT_LIMITS.maxUploadBytes / 1048576} MB` }]);
  const v = vetArchive(buf, "upload");
  if (!v.ok) return fail(null, buf, v.problems);
  let z = v.zip;
  const notes: string[] = [];
  // A zip whose only file is one plugin jar (a common way to send one): unwrap it once, inside the same budget.
  const files0 = z.entries.filter((e) => !e.dir);
  if (files0.length === 1 && /\.jar$/i.test(files0[0].name)) {
    const r = read(z, files0[0], IMPORT_LIMITS.maxEntryBytes);
    if (!r.ok) return fail(null, buf, [r.problem]);
    const inner = vetArchive(r.data, files0[0].name.slice(0, 120));
    if (!inner.ok) return fail(null, buf, inner.problems);
    notes.push(`Opened ${files0[0].name.slice(0, 120)} from the zip.`);
    inner.zip.budget = z.budget;
    z = inner.zip;
  }
  const names = z.entries.filter((e) => !e.dir).map((e) => e.name);
  const has = (re: RegExp) => names.some((n) => re.test(n));
  const isJar = /\.jar$/i.test(opts.filename) || ((has(/^(plugin|paper-plugin)\.yml$/) || has(/^META-INF\/MANIFEST\.MF$/)) && has(/\.class$/) && !has(/(^|\/)src\/main\//));
  if (isJar) return ingestJar(buf, z, opts, notes);
  const root = commonRoot(names);
  const rel = (n: string) => (root && n.startsWith(root) ? n.slice(root.length) : n);
  const relNames = names.map(rel);
  if (relNames.includes("pack.mcmeta") && relNames.some((n) => n.startsWith("data/"))) return ingestPack(buf, z, "datapack", root, notes);
  if (relNames.includes("pack.mcmeta") && relNames.some((n) => n.startsWith("assets/"))) return ingestPack(buf, z, "resourcepack", root, notes);
  if (relNames.some((n) => /(^|\/)src\/main\//.test(n) || BUILD_FILE_RE.test(n))) return ingestSource(buf, z, opts, root, notes);
  return fail(null, buf, [{ code: "unknown_kind", message: "this is not a plugin source zip (src/main/...), a plugin jar, a datapack or a resource pack" }], [], notes);
}

// ---------------------------------------------------------------------------------------------------------------------
// Source ZIP
// ---------------------------------------------------------------------------------------------------------------------

const IMPORT_RE = /^\s*import\s+(static\s+)?([A-Za-z_][\w]*(?:\.[A-Za-z_$][\w$]*)*(?:\.\*)?)\s*;/gm;
const PACKAGE_RE = /^\s*package\s+([A-Za-z_][\w]*(?:\.[A-Za-z_][\w]*)*)\s*;/m;

export function parseBuildCoordinates(path: string, text: string): string[] {
  const out = new Set<string>();
  if (/\.gradle(\.kts)?$/.test(path)) {
    const re = /\b(?:compileOnly|compileOnlyApi|implementation|api|compile|provided|shadow|runtimeOnly|paperLibrary|library)\s*\(?\s*(?:group\s*[:=]\s*)?["']([A-Za-z0-9_.\-]+:[A-Za-z0-9_.\-]+(?::[A-Za-z0-9_.\-+\[\]]+)?)(?::[A-Za-z0-9_.\-]+)?["']/g;
    for (const m of text.matchAll(re)) out.add(m[1]);
  } else if (/pom\.xml$/.test(path)) {
    for (const m of text.matchAll(/<dependency>([\s\S]{0,2000}?)<\/dependency>/g)) {
      const g = /<groupId>\s*([^<\s]+)\s*<\/groupId>/.exec(m[1])?.[1];
      const a = /<artifactId>\s*([^<\s]+)\s*<\/artifactId>/.exec(m[1])?.[1];
      const scope = /<scope>\s*([^<\s]+)\s*<\/scope>/.exec(m[1])?.[1];
      if (g && a && scope !== "test") out.add(`${g}:${a}`);
    }
  }
  return [...out].slice(0, 200);
}

/** What the build files say about the compile that we cannot honour (processors, Lombok, Kotlin, toolchains). */
export function buildFileUnsupported(texts: ImportDoc[]): UnsupportedItem[] {
  const out: UnsupportedItem[] = [];
  const all = texts.map((t) => t.text).join("\n");
  if (/\blombok\b|io\.freefair\.lombok/i.test(all)) out.push({ what: "Lombok", reason: "Lombok rewrites code with an annotation processor, and Cyrus compiles with annotation processing off (-proc:none). Delombok the source first." });
  if (/\bkapt\b|\bksp\s*\(|\bannotationProcessor\s*[("']|<annotationProcessorPaths>|<annotationProcessors>/.test(all)) out.push({ what: "annotation processors", reason: "the build runs annotation processors, and Cyrus compiles with annotation processing off (-proc:none), so the generated code would be missing." });
  if (/kotlin\s*\(\s*["']jvm["']|org\.jetbrains\.kotlin|kotlin-stdlib/.test(all)) out.push({ what: "Kotlin", reason: "the project uses Kotlin; Cyrus compiles Java only." });
  if (/\bscala\b|org\.scala-lang/.test(all)) out.push({ what: "Scala", reason: "the project uses Scala; Cyrus compiles Java only." });
  return out;
}

function ingestSource(buf: Buffer, z: ZipIndex, opts: IngestOptions, root: string | null, notes: string[]): IngestResult {
  const kind: ImportKind = "source";
  const all = z.entries.filter((e) => !e.dir);
  const relOf = (n: string) => (root && n.startsWith(root) ? n.slice(root.length) : n);
  // Modules: every directory that holds src/main/. One module only (the one with the plugin descriptor if several).
  const modules = new Set<string>();
  for (const e of all) { const m = /^(.*?)src\/main\//.exec(relOf(e.name)); if (m) modules.add(m[1]); }
  const descr = [...modules].filter((m) => all.some((e) => relOf(e.name) === `${m}src/main/resources/plugin.yml` || relOf(e.name) === `${m}src/main/resources/paper-plugin.yml`));
  let mod: string;
  if (modules.size === 1) mod = [...modules][0];
  else if (descr.length === 1) { mod = descr[0]; notes.push(`Multi-module project: imported the module with the plugin descriptor (${mod || "root"}); other modules were ignored.`); }
  else if (!modules.size) return fail(kind, buf, [{ code: "no_sources", message: "no src/main/java folder found" }], [], notes);
  else return fail(kind, buf, [], [{ what: "multi-module project", reason: `${descr.length ? "several" : "no"} modules have a plugin.yml (${[...modules].slice(0, 5).map((m) => m || "root").join(", ")}). Upload one module.` }], notes);

  const unsupported: UnsupportedItem[] = [];
  const problems: Problem[] = [];
  const ignored: string[] = [];
  const kept: IngestedFile[] = [];
  const docs: ImportDoc[] = [];
  const buildTexts: ImportDoc[] = [];
  const nestedFound: string[] = [];
  let srcBytes = 0, javaFiles = 0, resourceFiles = 0, otherIgnored = 0;
  let buildSystem: Detection["buildSystem"] = "none";
  const langHits = { kotlin: 0, scala: 0, groovy: 0 };

  for (const e of all) {
    const r0 = relOf(e.name);
    const inMod = r0.startsWith(mod);
    const r = inMod ? r0.slice(mod.length) : r0;
    if (BUILD_FILE_RE.test(r0)) {
      ignored.push(r0);
      if (/build\.gradle\.kts$|settings\.gradle\.kts$/.test(r0)) buildSystem = buildSystem === "maven" ? "maven" : "gradle-kotlin-dsl";
      else if (/build\.gradle$|settings\.gradle$/.test(r0) && buildSystem !== "gradle-kotlin-dsl") buildSystem = buildSystem === "maven" ? "maven" : "gradle";
      else if (/pom\.xml$/.test(r0) && buildSystem === "none") buildSystem = "maven";
      if (/\.(gradle|kts|xml|toml|properties)$/.test(r0) && e.usize <= IMPORT_LIMITS.maxBuildFileBytes) {
        const t = read(z, e, IMPORT_LIMITS.maxBuildFileBytes);
        if (t.ok) buildTexts.push({ path: r0, text: t.data.toString("utf8") });
      }
      continue;
    }
    if (/(^|\/)src\/main\/kotlin\//.test(r0) || /\.kt$/.test(r0)) langHits.kotlin++;
    if (/(^|\/)src\/main\/scala\//.test(r0) || /\.scala$/.test(r0)) langHits.scala++;
    if (/(^|\/)src\/main\/groovy\//.test(r0) || /\.groovy$/.test(r0)) langHits.groovy++;
    if (inMod && r.startsWith("src/main/java/")) {
      if (!r.endsWith(".java")) {
        if (CODE_EXT.has(ext(r))) unsupported.push({ what: `non-Java code in src/main/java (${r.slice(0, 120)})`, reason: "Cyrus compiles Java sources only and never ships code it did not compile." });
        else { ignored.push(r0); }
        continue;
      }
      if (/(^|\/)module-info\.java$/.test(r) || /(^|\/)package-info\.java$/.test(r) && false) { unsupported.push({ what: "Java modules (module-info.java)", reason: "Paper plugins are not JPMS modules; remove module-info.java." }); continue; }
      if (++javaFiles > IMPORT_LIMITS.maxSourceFiles) { problems.push({ code: "too_many_files", message: `more than ${IMPORT_LIMITS.maxSourceFiles} Java files` }); break; }
      const d = read(z, e, IMPORT_LIMITS.maxEntryBytes);
      if (!d.ok) { problems.push(d.problem); break; }
      if (d.data.includes(0)) { problems.push({ code: "binary_source", message: `${r.slice(0, 120)} is not a text file` }); break; }
      srcBytes += d.data.length;
      kept.push({ path: r, role: "source", size: d.data.length, sha256: sha256(d.data), data: d.data });
      continue;
    }
    if (inMod && r.startsWith("src/main/resources/")) {
      const x = ext(r);
      if (ARCHIVE_RE.test(r) || CODE_EXT.has(x)) { unsupported.push({ what: `binary code in resources (${r.slice(0, 120)})`, reason: "resources may not contain jars, classes, archives, native libraries or scripts: Cyrus never ships code it did not compile." }); continue; }
      if (/^src\/main\/resources\/META-INF\/services\/javax\.annotation\.processing\.Processor$/.test(r)) { unsupported.push({ what: "annotation processors", reason: "the project registers an annotation processor; Cyrus compiles with -proc:none." }); continue; }
      if (/^src\/main\/resources\/META-INF\//.test(r)) { ignored.push(r0); continue; }
      if (!RESOURCE_EXT.has(x)) { ignored.push(r0); notes.push(`Left out ${r.slice(0, 120)} (file type .${x || "none"} is not kept in plugin resources).`); continue; }
      if (++resourceFiles > IMPORT_LIMITS.maxResourceFiles) { problems.push({ code: "too_many_files", message: `more than ${IMPORT_LIMITS.maxResourceFiles} resource files` }); break; }
      const d = read(z, e, IMPORT_LIMITS.maxEntryBytes);
      if (!d.ok) { problems.push(d.problem); break; }
      srcBytes += d.data.length;
      const role: FileRole = /^src\/main\/resources\/(plugin|paper-plugin|config)\.yml$/.test(r) ? "config" : "resource";
      kept.push({ path: r, role, size: d.data.length, sha256: sha256(d.data), data: d.data });
      continue;
    }
    if (DOC_RE.test(r0) && r0.split("/").length <= 2 + (mod ? mod.split("/").length - 1 : 0) && docs.length < IMPORT_LIMITS.maxDocs && e.usize <= IMPORT_LIMITS.maxDocBytes) {
      const d = read(z, e, IMPORT_LIMITS.maxDocBytes);
      if (d.ok && !d.data.includes(0)) docs.push({ path: r0, text: d.data.toString("utf8") });
      continue;
    }
    if (ARCHIVE_RE.test(r0)) { nestedFound.push(r0.slice(0, 200)); ignored.push(r0); continue; }
    if (BUILD_DIR_RE.test(r0)) { ignored.push(r0); continue; }
    otherIgnored++;
  }
  if (srcBytes > IMPORT_LIMITS.maxSourceBytes) problems.push({ code: "too_large", message: `the kept sources are over ${IMPORT_LIMITS.maxSourceBytes / 1048576} MB` });
  if (problems.length) return fail(kind, buf, problems, unsupported, notes);
  if (otherIgnored) notes.push(`${otherIgnored} other file${otherIgnored > 1 ? "s" : ""} outside src/main (tests, docs folders, IDE files) were not imported.`);
  if (nestedFound.length) notes.push(`Bundled archives were ignored (${nestedFound.slice(0, 3).join(", ")}${nestedFound.length > 3 ? ", ..." : ""}): dependencies come only from Cyrus's allowlist.`);
  if (langHits.kotlin) unsupported.push({ what: "Kotlin", reason: "the project contains Kotlin sources; Cyrus compiles Java only." });
  if (langHits.scala) unsupported.push({ what: "Scala", reason: "the project contains Scala sources; Cyrus compiles Java only." });
  if (langHits.groovy) unsupported.push({ what: "Groovy", reason: "the project contains Groovy sources; Cyrus compiles Java only." });
  unsupported.push(...buildFileUnsupported(buildTexts));

  // Java: packages, imports, Lombok / processor-driven annotations, completeness.
  const java = kept.filter((f) => f.role === "source");
  const ownPackages = new Set<string>();
  const ownClasses = new Set<string>();
  const imports: string[] = [];
  for (const f of java) {
    const t = f.data.toString("utf8");
    const pkg = PACKAGE_RE.exec(t)?.[1] ?? "";
    if (pkg) ownPackages.add(pkg);
    ownClasses.add((pkg ? pkg + "." : "") + f.path.split("/").pop()!.replace(/\.java$/, ""));
    for (const m of t.matchAll(IMPORT_RE)) imports.push((m[1] ? "static " : "") + m[2]);
    if (/^\s*import\s+lombok\./m.test(t) && !unsupported.some((u) => u.what === "Lombok")) unsupported.push({ what: "Lombok", reason: "the code uses Lombok, which needs an annotation processor; Cyrus compiles with -proc:none. Delombok the source first." });
  }
  const descriptorEntry = kept.find((f) => f.path === "src/main/resources/paper-plugin.yml") ?? kept.find((f) => f.path === "src/main/resources/plugin.yml");
  let d: PluginDescriptor | null = null;
  if (!descriptorEntry) problems.push({ code: "no_descriptor", message: "src/main/resources/plugin.yml is missing" });
  else d = readDescriptor(descriptorEntry.data.toString("utf8"), descriptorEntry.path.endsWith("paper-plugin.yml") ? "paper-plugin.yml" : "plugin.yml");
  if (kept.some((f) => f.path === "src/main/resources/paper-plugin.yml")) unsupported.push({ what: "paper-plugin.yml", reason: "Paper's own plugin format is experimental and its loader/bootstrapper classes can fetch libraries at runtime. Cyrus builds plugin.yml plugins: add a plugin.yml (and remove paper-plugin.yml)." });
  if (d) {
    if (d.libraries.length) unsupported.push({ what: "plugin.yml libraries", reason: `Paper downloads these from Maven when the server starts (${d.libraries.slice(0, 3).join(", ")}); Cyrus does not allow runtime downloads.` });
    if (d.name && !/^[A-Za-z0-9_.-]{1,64}$/.test(d.name)) unsupported.push({ what: "plugin name", reason: `"${d.name.slice(0, 64)}" has spaces or other characters Cyrus does not build; use letters, digits, '_', '-' or '.'.` });
    if (!d.name) problems.push({ code: "bad_descriptor", message: "plugin.yml has no name" });
    if (!d.version) problems.push({ code: "bad_descriptor", message: "plugin.yml has no version" });
  }
  const main = d?.main ?? null;
  const missing: string[] = [];
  if (main && !ownClasses.has(main)) missing.push(main);
  // Imports of the project's own group (the main class's first two package segments) must resolve to an uploaded file.
  const group = main ? main.split(".").slice(0, Math.max(1, Math.min(2, main.split(".").length - 2))).join(".") : null;
  const isOwnish = (n: string) => !!group && (n === group || n.startsWith(group + "."));
  for (const raw of imports) {
    const n = raw.replace(/^static\s+/, "");
    if (!isOwnish(n)) continue;
    if (n.endsWith(".*")) { const p = n.slice(0, -2); if (!ownPackages.has(p) && ![...ownClasses].some((c) => c === p)) missing.push(n); continue; }
    const segs = n.split(".");
    let ok = false;
    for (let i = segs.length; i >= 2 && !ok; i--) if (ownClasses.has(segs.slice(0, i).join("."))) ok = true;
    if (!ok && !ownPackages.has(segs.slice(0, -1).join("."))) missing.push(n);
    else if (!ok) missing.push(n);
  }
  const missingU = [...new Set(missing)].slice(0, 20);
  if (missingU.length) unsupported.push({ what: "incomplete sources", reason: `these classes are referenced but not in the upload: ${missingU.slice(0, 6).join(", ")}${missingU.length > 6 ? ", ..." : ""}` });
  const deps = resolveDependencies({
    coordinates: buildTexts.flatMap((t) => parseBuildCoordinates(t.path, t.text)).filter((c) => !/:(junit|mockito|assertj)/.test(c)),
    imports: imports.filter((n) => !isOwnish(n.replace(/^static\s+/, ""))),
    pluginDepends: [...(d?.depend ?? []), ...(d?.softdepend ?? [])],
    ownPackages: [...ownPackages],
  });
  // Build-file coordinates are hints, not requirements: only imports the CODE really makes are fatal.
  const fromImports = deps.unsupported.filter((u) => u.source === "import");
  for (const u of deps.unsupported.filter((x) => x.source === "build-file")) notes.push(`The build file declares ${u.what}, which Cyrus does not provide (${u.reason.split(".")[0]}). Your code does not import it, so it was ignored.`);
  for (const u of fromImports) unsupported.push({ what: `unsupported dependency: ${u.what}`, reason: u.reason });
  if (!java.length) problems.push({ code: "no_sources", message: "no Java files in src/main/java" });
  const uniqueUnsupported = dedupeUnsupported(unsupported);
  const detection: Detection = {
    kind, buildSystem, descriptorFile: d?.file ?? null, name: d?.name ?? null, version: d?.version ?? null, main, apiVersion: d?.apiVersion ?? null,
    description: descriptionOf(descriptorEntry?.data), depend: d?.depend ?? [], softdepend: d?.softdepend ?? [],
    commands: (d?.commands ?? []).map((c) => c.name).slice(0, 100), permissions: (d?.permissions ?? []).map((p) => p.name).slice(0, 200),
    language: langHits.kotlin ? "kotlin" : langHits.scala ? "scala" : langHits.groovy ? "groovy" : "java",
    sourcesComplete: !!main && missingU.length === 0, missingClasses: missingU, javaFiles: java.length, resourceFiles: kept.length - java.length,
    ownPackages: [...ownPackages].sort().slice(0, 100), maxClassMajor: null, multiRelease: false, strippedSignatures: [], nestedArchives: nestedFound.slice(0, 20), packFormat: null,
    rootPrefix: root,
  };
  if (problems.length || uniqueUnsupported.length) return { ...fail(kind, buf, problems, uniqueUnsupported, notes) };
  if (buildSystem !== "none") notes.push(`Your ${buildSystem === "maven" ? "Maven" : "Gradle"} build files were not used and never run: Cyrus compiles src/main/java with its own pinned toolchain.`);
  return { ok: true, kind, uploadSha256: sha256(buf), size: buf.length, files: kept, docs, buildTexts, ignored: ignored.slice(0, 50), notes, detection, deps };
}

function descriptionOf(b: Buffer | undefined): string | null {
  if (!b) return null;
  const m = /^description:\s*['"]?(.+?)['"]?\s*$/m.exec(b.toString("utf8"));
  return m ? m[1].slice(0, 300) : null;
}

function dedupeUnsupported(list: UnsupportedItem[]): UnsupportedItem[] {
  const seen = new Set<string>();
  return list.filter((u) => (seen.has(u.what) ? false : (seen.add(u.what), true))).slice(0, 30);
}

// ---------------------------------------------------------------------------------------------------------------------
// Plugin JAR (analysis + diagnosis only: never rebuilt, never "safely modified")
// ---------------------------------------------------------------------------------------------------------------------

function ingestJar(buf: Buffer, z: ZipIndex, opts: IngestOptions, notes: string[]): IngestResult {
  const kind: ImportKind = "jar";
  const nested: string[] = [];
  const nestedProblems = vetNested(z, 0, "", nested);
  if (nestedProblems.length) return fail(kind, buf, nestedProblems, [], notes);
  // The descriptor + bytecode summary come from the inventory reader (bounded, never extracts).
  const jarBytes = z.buf;
  const info = inspectJar(opts.filename.slice(0, 120), opts.filename.slice(0, 120), jarBytes, { zipLimits: ZIP_LIMITS });
  if (info.flags.unreadable) return fail(kind, buf, [{ code: "unreadable", message: info.flags.unreadable }], [], notes);
  if (info.flags.bombEntries.length) return fail(kind, buf, [{ code: "zip_bomb", message: `entries that inflate suspiciously: ${info.flags.bombEntries[0]}` }], [], notes);
  if (info.flags.serverJar) return fail(kind, buf, [], [{ what: "a server jar", reason: `this is a Minecraft/Paper server jar (${info.flags.serverJarEvidence}), not a plugin.` }], notes);
  const unsupported: UnsupportedItem[] = [];
  const d = info.descriptor;
  if (!d) return fail(kind, buf, [{ code: "no_descriptor", message: "the jar has no plugin.yml or paper-plugin.yml (is it a library or a client mod?)" }], [], notes);
  const limit = javaMajorLimit(opts.mcVersion);
  const major = info.bytecode?.maxClassMajor ?? null;
  if (major && major > limit) unsupported.push({ what: `Java ${major - 44} classes`, reason: `the jar is compiled for Java ${major - 44}, but Paper ${opts.mcVersion} runs on Java ${limit - 44}.` });
  const strippedSignatures: string[] = [];
  const classes: IngestedFile[] = [];
  let multiRelease = false;
  const problems: Problem[] = [];
  const manifest = z.entries.find((e) => e.name === "META-INF/MANIFEST.MF");
  if (manifest) { const m = read(z, manifest, 256 * 1024); if (m.ok && /^Multi-Release:\s*true\s*$/im.test(m.data.toString("latin1"))) multiRelease = true; }
  for (const e of z.entries) {
    if (e.dir) continue;
    if (SIG_RE.test(e.name)) { strippedSignatures.push(e.name.slice(0, 120)); continue; }
    if (e.name.startsWith("META-INF/versions/")) multiRelease = true;
    if (!e.name.endsWith(".class")) continue;
    if (classes.length >= IMPORT_LIMITS.maxJarClasses) { notes.push(`Only the first ${IMPORT_LIMITS.maxJarClasses} classes were analysed.`); break; }
    const r = read(z, e, IMPORT_LIMITS.maxClassBytes);
    if (!r.ok) { problems.push(r.problem); break; }
    if (r.data.length < 10 || r.data.readUInt32BE(0) !== 0xcafebabe) { problems.push({ code: "bad_class", message: `${e.name.slice(0, 120)} is not a class file` }); break; }
    const m = r.data.readUInt16BE(6);
    if (m > limit && !e.name.startsWith("META-INF/versions/")) { /* counted by the summary above */ }
    classes.push({ path: e.name, role: "artifact", size: r.data.length, sha256: sha256(r.data), data: r.data });
  }
  if (problems.length) return fail(kind, buf, problems, unsupported, notes);
  if (strippedSignatures.length) notes.push(`The jar's signature files were removed from the analysis (${strippedSignatures.length}); signatures are never kept on files Cyrus handles.`);
  if (multiRelease) notes.push("Multi-release jar: the versioned classes under META-INF/versions were analysed too (they can run on newer Java).");
  if (nested.length) notes.push(`The jar contains ${nested.length} nested archive${nested.length > 1 ? "s" : ""}: Paper does not load them; any code that would load them is blocked by the check.`);
  if (d.libraries.length) notes.push(`plugin.yml asks Paper to download libraries at startup (${d.libraries.slice(0, 3).join(", ")}).`);
  notes.push("Jar-only import: Cyrus analyses and diagnoses it but cannot change it. Upload the source to work on it.");
  const desc = z.entries.find((e) => e.name === (d.file === "paper-plugin.yml" ? "paper-plugin.yml" : "plugin.yml"));
  const descBuf = desc ? read(z, desc, 256 * 1024) : null;
  const files: IngestedFile[] = [...classes];
  if (descBuf && descBuf.ok) files.push({ path: d.file, role: "config", size: descBuf.data.length, sha256: sha256(descBuf.data), data: descBuf.data });
  const detection: Detection = {
    kind, buildSystem: null, descriptorFile: d.file, name: d.name, version: d.version, main: d.main, apiVersion: d.apiVersion,
    description: descriptionOf(descBuf && descBuf.ok ? descBuf.data : undefined), depend: d.depend, softdepend: d.softdepend,
    commands: d.commands.map((c) => c.name).slice(0, 100), permissions: d.permissions.map((p) => p.name).slice(0, 200), language: "bytecode",
    sourcesComplete: null, missingClasses: [], javaFiles: 0, resourceFiles: 0, ownPackages: [], maxClassMajor: major, multiRelease, strippedSignatures: strippedSignatures.slice(0, 20),
    nestedArchives: nested.slice(0, 20), packFormat: null, rootPrefix: null,
  };
  if (unsupported.length) return fail(kind, buf, [], unsupported, notes);
  const deps: DepResolution = { allowed: [], provided: [], unsupported: [], runtimeOnly: [...d.depend, ...d.softdepend] };
  return { ok: true, kind, uploadSha256: sha256(buf), size: buf.length, files, docs: [], buildTexts: [], ignored: [], notes, detection, deps };
}

// ---------------------------------------------------------------------------------------------------------------------
// Datapack / resource pack ZIP (structure check; no code)
// ---------------------------------------------------------------------------------------------------------------------

function ingestPack(buf: Buffer, z: ZipIndex, kind: "datapack" | "resourcepack", root: string | null, notes: string[]): IngestResult {
  const allow = kind === "datapack" ? DATAPACK_EXT : RESOURCEPACK_EXT;
  const files: IngestedFile[] = [];
  const unsupported: UnsupportedItem[] = [];
  const ignored: string[] = [];
  const docs: ImportDoc[] = [];
  let total = 0;
  for (const e of z.entries) {
    if (e.dir) continue;
    const r = root && e.name.startsWith(root) ? e.name.slice(root.length) : e.name;
    const x = ext(r);
