#!/usr/bin/env node
"use strict";
// Download the Cyrus import dependency allowlist (lib/cyrus/import/deps.json) into a directory and VERIFY every jar's
// sha256 (and sha1) against the pinned values. A jar that does not match is deleted and the script exits 1.
//   node tools/fetch-import-deps.js <deps.json> <out-dir> [--verify-only]
// Owner/image use only (the build service never downloads at build time; it only re-verifies what is in MB_DEPS_DIR).
// Agents: <out-dir> must be under /tank/nxeon-build/tmp on node-2.
const fs = require("fs");
const path = require("path");
const https = require("https");
const crypto = require("crypto");

const [manifestPath, outDir] = process.argv.slice(2);
const verifyOnly = process.argv.includes("--verify-only");
if (!manifestPath || !outDir) { console.error("usage: fetch-import-deps.js <deps.json> <out-dir> [--verify-only]"); process.exit(2); }
const m = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
fs.mkdirSync(outDir, { recursive: true });

function get(url, redirects = 0) {
  return new Promise((resolve, reject) => {
    if (!/^https:\/\//.test(url)) return reject(new Error(`refusing non-https ${url}`));
    https.get(url, { headers: { "User-Agent": "nxeon-cyrus-import-deps/1.0" }, timeout: 60000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && redirects < 5) { res.resume(); return resolve(get(new URL(res.headers.location, url).toString(), redirects + 1)); }
      if (res.statusCode !== 200) { res.resume(); return reject(new Error(`${url}: HTTP ${res.statusCode}`)); }
      const chunks = []; let n = 0;
      res.on("data", (c) => { n += c.length; if (n > 32 * 1024 * 1024) { res.destroy(); reject(new Error("too large")); } else chunks.push(c); });
      res.on("end", () => resolve(Buffer.concat(chunks)));
    }).on("error", reject).on("timeout", function () { this.destroy(new Error("timeout")); });
  });
}

(async () => {
  let bad = 0;
  for (const d of m.dependencies) {
    if (!/^[A-Za-z0-9][A-Za-z0-9._-]*\.jar$/.test(d.file)) { console.error(`${d.id}: bad file name`); bad++; continue; }
    const f = path.join(outDir, d.file);
    let buf = fs.existsSync(f) ? fs.readFileSync(f) : null;
    if (!buf && !verifyOnly) { try { buf = await get(d.url); } catch (e) { console.error(`${d.id}: ${e.message}`); bad++; continue; } }
    if (!buf) { console.error(`${d.id}: missing`); bad++; continue; }
    const s256 = crypto.createHash("sha256").update(buf).digest("hex");
    const s1 = crypto.createHash("sha1").update(buf).digest("hex");
    if (s256 !== d.sha256 || s1 !== d.sha1 || buf.length !== d.size) { console.error(`${d.id}: CHECKSUM MISMATCH (sha256 ${s256}, sha1 ${s1}, ${buf.length} bytes)`); try { fs.unlinkSync(f); } catch { /* not written */ } bad++; continue; }
    fs.writeFileSync(f, buf, { mode: 0o644 });
    console.log(`ok ${d.id} ${d.file} ${buf.length} sha256 ${s256}`);
  }
  process.exit(bad ? 1 : 0);
})();
EOF
