/**
 * Cyrus import (service with features.imports): hand the VETTED files of an import to the build service. `source` makes
 * a base build (no AI; javac + allowlisted compile-only jars + attested scan); `jar` is analysis only. The service checks
 * everything again. Large: the body carries the files as base64 (portal caps the upload at 25 MB).
 */
export type SvcImportBody = {
  id: string; mcVersion: string; kind: "source" | "jar"; pluginName?: string; namespace: string;
  files: { path: string; data: string }[]; docs?: { path: string; text: string }[]; deps?: string[];
};
export async function svcImport(body: SvcImportBody): Promise<ServiceBuild> {
  const r = await call("/imports", { method: "POST", body: JSON.stringify(body), timeoutMs: 120_000 });
  const j = await r.json().catch(() => ({}));
  if (r.status !== 202) throw new Error((j as { error?: string }).error || `service returned ${r.status}`);
  return j as ServiceBuild;
}
EOF
