// Cyrus import: TODAY'S HOST WIRING (Nxeon). SERVER ONLY. The one place the import feature touches Nxeon: the DB rows
// Cyrus already owns (CyrusProject / CyrusRevision through the engine-core store, ModBuild through the same calls the
// builder uses), the build-service client, the settings flag, the rate limiter, the signed-in Cyrus user, and a
// read-only server view through the Mods engine's GuestFs (the same adapter lib/modbuilder/install.ts uses). A
// standalone Cyrus replaces this file; lib/cyrus/import/{ingest,attestation,licence,deps,importer,api}.ts stay as they are.
import { randomBytes } from "node:crypto";
import { readFile } from "node:fs/promises";
import { db } from "../../db";
import { getSettingBool } from "../../settings";
import { checkRateLimit } from "../../rate-limit";
import { modBuilderUser } from "../../modbuilder/access";
import { svcGet, svcImport } from "../../modbuilder/client";
import { syncBuild } from "../../modbuilder/store";
import { MB_VERSIONS } from "../../modbuilder/types";
import { SANDBOX } from "../../sandbox";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest } from "../../mods/guest-fs";
import { SshGuestFs } from "../../../worker/mods-guest-ssh";
import { addRevision, createProject, setRevisionStatus } from "../engine-core/store";
import { validateModSpec } from "../engine-core/spec";
import { getAdapter } from "../adapters";
import { FsQuarantine } from "./store";
import { CYRUS_IMPORT_FLAG, type ImportApiDeps } from "./api";
import type { ImportMeta } from "./attestation";
import type { ImporterDeps, ImportRow, SvcView } from "./importer";

type RevRow = { id: string; projectId: string; status: string; engine: unknown; manifest: unknown; createdAt: Date };
type ProjRow = { id: string; namespace: string; title: string | null };
const toRow = (p: ProjRow, r: RevRow): ImportRow => ({
  projectId: p.id, namespace: p.namespace, title: p.title, revisionId: r.id, revisionStatus: r.status,
  meta: (r.engine as { import: ImportMeta }).import, manifestCount: Array.isArray(r.manifest) ? r.manifest.length : 0, createdAt: r.createdAt,
});

async function firstImported(projectIds: string[], extra: Record<string, unknown> = {}): Promise<RevRow[]> {
  if (!projectIds.length) return [];
  return db.cyrusRevision.findMany({ where: { projectId: { in: projectIds }, kind: "imported", seq: 1, ...extra }, orderBy: { createdAt: "desc" } }) as unknown as RevRow[];
}

function svcViewOfRow(row: { id: string; status: string; error: string | null; result: unknown; jarName: string | null; jarSize: number | null; jarSha256: string | null }): SvcView {
  const res = (row.result ?? {}) as { warnings?: string[]; safety?: SvcView["safety"]; errorDetail?: string | null };
  return { id: row.id, status: row.status, error: row.error, errorDetail: res.errorDetail ?? null, warnings: res.warnings ?? [], safety: res.safety ?? null, jar: row.jarName ? { name: row.jarName, size: row.jarSize ?? 0, sha256: row.jarSha256 ?? "" } : null };
}

export const realImporterDeps: ImporterDeps = {
  now: () => new Date(),
  newId: (prefix) => prefix + randomBytes(10).toString("hex"),
  quarantine: new FsQuarantine(),
  async findByUploadHash(userId, sha256) {
    const projects = await db.cyrusProject.findMany({ where: { userId }, select: { id: true, namespace: true, title: true } });
    const revs = await firstImported(projects.map((p) => p.id), { engine: { path: ["import", "uploadSha256"], equals: sha256 } });
    const r = revs[0];
    return r ? toRow(projects.find((p) => p.id === r.projectId)!, r) : null;
  },
  async getImportRow(userId, projectId) {
    const p = await db.cyrusProject.findFirst({ where: { id: projectId, userId }, select: { id: true, namespace: true, title: true } });
    if (!p) return null;
    const [r] = await firstImported([p.id]);
    return r ? toRow(p, r) : null;
  },
  async listImportRows(userId) {
    const projects = await db.cyrusProject.findMany({ where: { userId }, select: { id: true, namespace: true, title: true }, orderBy: { createdAt: "desc" }, take: 500 });
    const revs = await firstImported(projects.map((p) => p.id));
    return revs.map((r) => toRow(projects.find((p) => p.id === r.projectId)!, r));
  },
  createProject: (i) => createProject(i),
  async addImportedRevision(projectId, i) {
    const r = await addRevision(projectId, { kind: "imported", manifest: i.manifest, spec: i.spec ?? undefined, modBuildId: i.modBuildId, engine: i.engine as never, status: i.status, message: i.message, expectedHeadId: null });
    return { id: r.id, seq: r.seq, status: r.status };
  },
  async setRevisionStatus(id, status) { await setRevisionStatus(id, status); },
  async createModBuildRow(row) {
    await db.modBuild.create({ data: { id: row.id, userId: row.userId, prompt: row.prompt, mcVersion: row.mcVersion, pluginName: row.pluginName, rootBuildId: row.id, ...(row.title ? { cyrus: { title: row.title } } : {}) } });
  },
  async failModBuildRow(id, message) {
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: message, finishedAt: new Date() } });
  },
  async syncModBuild(id) {
    const row = await db.modBuild.findUnique({ where: { id } });
    if (!row) return null;
    return svcViewOfRow(await syncBuild(row));
  },
  service: {
    importBuild: async (body) => svcImport(body as never) as unknown as SvcView,
    get: async (id) => (await svcGet(id)) as unknown as SvcView | null,
  },
  async openServerReadOnly(userId, serverId) {
    const server = await db.server.findFirst({ where: { id: serverId, userId, status: { notIn: ["DELETING"] } } });
    if (!server) return null;
    if (SANDBOX) {
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
      return { fs: local, base: "/opt/mc" };
    }
    const ssh = await SshGuestFs.open(server as never);
    return { fs: ssh, base: "/opt/mc", close: () => ssh.close() };
  },
  async fetchArtifact(modBuildId) {
    const row = await db.modBuild.findUnique({ where: { id: modBuildId }, select: { jarPath: true, status: true } });
    if (!row?.jarPath || row.status !== "succeeded") return null;
    return readFile(row.jarPath).catch(() => null);
  },
  validateSpec(spec) {
    const v = validateModSpec(spec, { adapterFor: getAdapter });
    return v.ok ? v.spec : null;
  },
};

export const realImportApiDeps: ImportApiDeps = {
  // Fails closed: any settings/DB error is "off".
  importEnabled: async () => { try { return await getSettingBool(CYRUS_IMPORT_FLAG, false); } catch { return false; } },
  currentUser: async () => { const u = await modBuilderUser().catch(() => null); return u ? { id: u.id, emailVerified: !!u.emailVerifiedAt } : null; },
  rateLimit: (key, max, windowMs) => checkRateLimit(key, { max, windowMs }),
  inflight: (userId) => db.modBuild.count({ where: { userId, status: { notIn: ["succeeded", "failed"] } } }),
  versions: MB_VERSIONS,
  importer: realImporterDeps,
};

