    await db.modBuild.create({ data: { id: row.id, userId: row.userId, prompt: row.prompt, mcVersion: row.mcVersion, pluginName: row.pluginName, rootBuildId: row.id, ...(row.title ? { cyrus: { title: row.title } } : {}) } });
  },
  async failModBuildRow(id, message) {
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: message, finishedAt: new Date() } });
  },
  async syncModBuild(id) {
    const row = await db.modBuild.findUnique({ where: { id } });
    if (!row) return null;
    return svcViewOfRow(await syncBuild(row));
  },
  service: {
    importBuild: async (body) => svcImport(body as never) as unknown as SvcView,
    get: async (id) => (await svcGet(id)) as unknown as SvcView | null,
  },
  async openServerReadOnly(userId, serverId) {
    const server = await db.server.findFirst({ where: { id: serverId, userId, status: { notIn: ["DELETING"] } } });
    if (!server) return null;
    if (SANDBOX) {
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
      return { fs: local, base: "/opt/mc" };
    }
    const ssh = await SshGuestFs.open(server as never);
    return { fs: ssh, base: "/opt/mc", close: () => ssh.close() };
  },
  async fetchArtifact(modBuildId) {
    const row = await db.modBuild.findUnique({ where: { id: modBuildId }, select: { jarPath: true, status: true } });
    if (!row?.jarPath || row.status !== "succeeded") return null;
    return readFile(row.jarPath).catch(() => null);
  },
  validateSpec(spec) {
    const v = validateModSpec(spec, { adapterFor: getAdapter });
    return v.ok ? v.spec : null;
  },
};

export const realImportApiDeps: ImportApiDeps = {
