  rateLimit: (key, max, windowMs) => checkRateLimit(key, { max, windowMs }),
  inflight: (userId) => db.modBuild.count({ where: { userId, status: { notIn: ["succeeded", "failed"] } } }),
  versions: MB_VERSIONS,
  importer: realImporterDeps,
};

