public final class ImportDemo extends JavaPlugin {
    private VaultHook vault;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        // Vault and PlaceholderAPI are optional: their classes are only touched when the plugins are present.
        if (getServer().getPluginManager().getPlugin("Vault") != null) {
            vault = VaultHook.create(this);
        }
        if (getServer().getPluginManager().getPlugin("PlaceholderAPI") != null) {
            PapiHook.register(this);
        }
        PluginCommand cmd = getCommand("importdemo");
        if (cmd != null) cmd.setExecutor(new DemoCommand(this));
        getServer().getPluginManager().registerEvents(new JoinListener(this), this);
        if (getConfig().getBoolean("metrics", true)) new Metrics(this, 23456);
        if (getConfig().getBoolean("check-updates", true)) new UpdateChecker(this, 123456).check();
        getLogger().info("ImportDemo enabled (vault=" + (vault != null) + ")");
    }

    public VaultHook vault() {
        return vault;
    }
}
