package me.demo.importdemo.metrics;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPOutputStream;
import javax.net.ssl.HttpsURLConnection;
import org.bukkit.Bukkit;
import org.bukkit.plugin.java.JavaPlugin;

/** A bStats-style metrics class (the pattern most public plugins copy in): an async HTTPS POST every 30 minutes. */
public final class Metrics {
    private static final String URL_BASE = "https://bStats.org/api/v2/data/bukkit";
    private final JavaPlugin plugin;
    private final int serviceId;

    public Metrics(JavaPlugin plugin, int serviceId) {
        this.plugin = plugin;
        this.serviceId = serviceId;
        // first submission after 5 minutes, then every 30 (never during a short test boot)
        Bukkit.getScheduler().runTaskTimerAsynchronously(plugin, this::submit, 20L * 60 * 5, 20L * 60 * 30);
    }

    private int playerCount() {
        try {
            // bStats does this because getOnlinePlayers changed its return type once
            Object players = Bukkit.class.getMethod("getOnlinePlayers").invoke(null);
            return players instanceof java.util.Collection<?> c ? c.size() : 0;
        } catch (ReflectiveOperationException e) {
            return 0;
        }
    }

    private void submit() {
        String json = "{\"service\":{\"id\":" + serviceId + "},\"playerAmount\":" + playerCount() + ",\"plugin\":\"" + plugin.getName() + "\"}";
        try {
            HttpsURLConnection c = (HttpsURLConnection) new URL(URL_BASE).openConnection();
            byte[] body = gzip(json);
            c.setRequestMethod("POST");
            c.setRequestProperty("Content-Encoding", "gzip");
            c.setRequestProperty("Content-Type", "application/json");
            c.setDoOutput(true);
            try (DataOutputStream out = new DataOutputStream(c.getOutputStream())) {
                out.write(body);
            }
            c.getInputStream().close();
        } catch (IOException e) {
            plugin.getLogger().fine("metrics submit failed: " + e.getMessage());
        }
    }

    private static byte[] gzip(String s) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (GZIPOutputStream g = new GZIPOutputStream(bos)) {
            g.write(s.getBytes(StandardCharsets.UTF_8));
        }
        return bos.toByteArray();
    }
}
