// Cyrus import (pure): ingestion limits + malicious fixtures (bombs, traversal, nesting, truncation, huge names,
// symlinks, duplicates, fuzzed archives), the detection matrix, the dependency allowlist, licence detection +
// attestation + the sharing rule, and the two scan profiles over REAL javac output (test/fixtures/cyrus-import/javap,
// compiled with JDK 21 --release 21 against the Paper 1.21.11 classpath on node-2; sources in scan-src/).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { zip, zipDir, type ZEntry } from "./_zipwriter";
import { ingestUpload, IMPORT_LIMITS, parseBuildCoordinates, type IngestResult, type IngestOk } from "../lib/cyrus/import/ingest";
import { classifyCoordinate, classifyPackage, DEPS_MANIFEST, resolveDependencies, validateDepsManifest } from "../lib/cyrus/import/deps";
import { detectLicences, licenceFromText, normaliseLicence } from "../lib/cyrus/import/licence";
import { ATTESTATION_TEXT_VERSION, SHARE_CONSENT_TEXT_VERSION, buildAttestation, effectiveLicence, mayShareImport, validateImportMeta } from "../lib/cyrus/import/attestation";
import { validateEngineRecord } from "../lib/cyrus/engine-core/revisions";
import { manifestOf, specFromImport } from "../lib/cyrus/import/importer";
import { validateModSpec } from "../lib/cyrus/engine-core/spec";
import { getAdapter } from "../lib/cyrus/adapters";

const require = createRequire(import.meta.url);
type Finding = { severity: string; rule: string; where: string; message: string; downgradedFrom?: string };
const scan = require("../services/modbuilder/scan.js") as {
  scanJavapText: (s: string, o?: { profile?: string }) => Finding[];
  applyBaseline: (f: Finding[], b: string[]) => Finding[];
  baselineOf: (f: Finding[]) => string[];
  attestedSummary: (f: Finding[]) => string;
  ATTESTED_DOWNGRADES: Record<string, unknown>;
};

const FX = path.join(__dirname, "fixtures/cyrus-import");
const OPTS = { filename: "ImportDemo-main.zip", mcVersion: "1.21.11" };
const ok = (r: IngestResult): IngestOk => { assert.ok(r.ok, JSON.stringify(!r.ok ? { p: r.problems, u: r.unsupported } : {})); return r as IngestOk; };
const codes = (r: IngestResult) => (r.ok ? [] : r.problems.map((p) => p.code));
const whats = (r: IngestResult) => (r.ok ? [] : r.unsupported.map((u) => u.what));
const PY = "name: P\nversion: 1.0.0\nmain: a.b.P\napi-version: '1.21'\n";
const MAIN = "package a.b;\nimport org.bukkit.plugin.java.JavaPlugin;\npublic class P extends JavaPlugin {}\n";
const src = (extra: ZEntry[] = [], yml = PY): Buffer => zip([{ name: "src/main/resources/plugin.yml", data: yml }, { name: "src/main/java/a/b/P.java", data: MAIN }, ...extra]);
const demo = () => zipDir(path.join(FX, "demo-src"), "ImportDemo-main/");

describe("import ingestion: the realistic source project", () => {
  const r = ok(ingestUpload(demo(), OPTS));
  it("is a Gradle source import of one module with plugin.yml", () => {
    assert.equal(r.kind, "source");
    assert.equal(r.detection.buildSystem, "gradle");
    assert.equal(r.detection.descriptorFile, "plugin.yml");
    assert.equal(r.detection.main, "me.demo.importdemo.ImportDemo");
    assert.equal(r.detection.apiVersion, "1.21");
    assert.equal(r.detection.language, "java");
    assert.equal(r.detection.sourcesComplete, true);
    assert.equal(r.detection.rootPrefix, "ImportDemo-main/");
    assert.deepEqual(r.detection.softdepend, ["Vault", "PlaceholderAPI"]);
  });
  it("keeps only src/main/java + src/main/resources; build files are dropped and listed, never kept", () => {
    assert.ok(r.files.every((f) => f.path.startsWith("src/main/java/") || f.path.startsWith("src/main/resources/")));
    assert.ok(r.files.every((f) => !/gradle|pom\.xml|gradlew/.test(f.path)));
    for (const b of ["ImportDemo-main/build.gradle", "ImportDemo-main/settings.gradle", "ImportDemo-main/gradlew"]) assert.ok(r.ignored.includes(b), b);
    assert.ok(r.ignored.some((p) => p.includes("gradle/wrapper")));
    assert.ok(!r.files.some((f) => f.data.toString().includes("attacker.invalid/x | sh")), "the malicious build task never reaches the kept files");
    assert.ok(r.notes.some((n) => /never run/.test(n)));
  });
  it("resolves Vault + PlaceholderAPI from the allowlist (imports + build file), Paper as provided", () => {
    assert.deepEqual(r.deps.allowed, ["placeholderapi", "vault-api"]);
    assert.ok(r.deps.provided.includes("io.papermc.paper:paper-api"));
    assert.equal(r.deps.unsupported.filter((u) => u.source === "import").length, 0);
  });
  it("keeps README and LICENSE as DATA docs and finds the MIT licence (file + SPDX header)", () => {
    assert.deepEqual(r.docs.map((d) => d.path).sort(), ["ImportDemo-main/LICENSE", "ImportDemo-main/README.md"]);
    const lic = detectLicences([...r.docs, ...r.files.filter((f) => f.role === "source").map((f) => ({ path: f.path, text: f.data.toString() }))]);
    assert.deepEqual([...new Set(lic.map((l) => l.spdx))], ["MIT"]);
    assert.ok(lic.some((l) => l.how === "spdx-header") && lic.some((l) => l.how === "licence-text"));
  });
  it("derives a valid ModSpec v1 and a manifest with hashes", () => {
    const spec = specFromImport(r, "nx_ab12cd34", "1.21.11");
    const v = validateModSpec(spec, { adapterFor: getAdapter });
    assert.ok(v.ok, JSON.stringify(!v.ok && v.errors));
    const m = manifestOf(r, "ImportDemo-main.zip");
    assert.ok(m.every((e) => /^[0-9a-f]{64}$/.test(e.sha256)));
    assert.ok(m.some((e) => e.role === "doc" && e.path.startsWith("imported-docs/")));
    assert.ok(m.some((e) => e.path === "src/main/resources/plugin.yml" && e.role === "config"));
  });
});

describe("import ingestion: detection matrix (unsupported says what and why)", () => {
  const cases: [string, Buffer, RegExp][] = [
    ["kotlin", src([{ name: "src/main/kotlin/a/b/K.kt", data: "class K" }]), /^Kotlin$/],
    ["scala", src([{ name: "src/main/scala/a/S.scala", data: "object S" }]), /^Scala$/],
    ["groovy", src([{ name: "src/main/groovy/a/G.groovy", data: "class G {}" }]), /^Groovy$/],
    ["lombok import", src([{ name: "src/main/java/a/b/L.java", data: "package a.b;\nimport lombok.Getter;\nclass L {}" }]), /^Lombok$/],
    ["lombok in build", src([{ name: "build.gradle", data: "dependencies { compileOnly 'org.projectlombok:lombok:1.18.30' }" }]), /^Lombok$/],
    ["annotation processor", src([{ name: "build.gradle", data: "dependencies { annotationProcessor 'com.google.auto.service:auto-service:1.1.1' }" }]), /annotation processors/],
    ["processor service file", src([{ name: "src/main/resources/META-INF/services/javax.annotation.processing.Processor", data: "x.Y" }]), /annotation processors/],
    ["unknown dependency", src([{ name: "src/main/java/a/b/D.java", data: "package a.b;\nimport com.zaxxer.hikari.HikariDataSource;\nclass D {}" }]), /unsupported dependency: com\.zaxxer\.hikari/],
    ["bstats must be shaded", src([{ name: "src/main/java/a/b/M.java", data: "package a.b;\nimport org.bstats.bukkit.Metrics;\nclass M {}" }]), /unsupported dependency: bStats/],
    ["nms", src([{ name: "src/main/java/a/b/N.java", data: "package a.b;\nimport net.minecraft.server.MinecraftServer;\nclass N {}" }]), /server internals/],
    ["paper-plugin.yml", src([{ name: "src/main/resources/paper-plugin.yml", data: "name: P\nversion: 1\nmain: a.b.P\n" }]), /^paper-plugin\.yml$/],
    ["plugin.yml libraries", src([], PY + "libraries:\n  - com.zaxxer:HikariCP:5.1.0\n"), /plugin\.yml libraries/],
    ["module-info", src([{ name: "src/main/java/module-info.java", data: "module a {}" }]), /module-info/],
    ["incomplete sources", src([{ name: "src/main/java/a/b/Q.java", data: "package a.b;\nimport a.b.util.Missing;\nclass Q {}" }]), /incomplete sources/],
    ["main class missing", zip([{ name: "src/main/resources/plugin.yml", data: PY }, { name: "src/main/java/a/b/Other.java", data: "package a.b;\nclass Other {}" }]), /incomplete sources/],
    ["jar in resources", src([{ name: "src/main/resources/lib/extra.jar", data: "PK" }]), /binary code in resources/],
    ["class in java dir", src([{ name: "src/main/java/a/b/X.class", data: "\xca\xfe" }]), /non-Java code/],
    ["spaces in the name", src([], PY.replace("name: P", "name: My Plugin")), /plugin name/],
    ["two modules with descriptors", zip([{ name: "a/src/main/resources/plugin.yml", data: PY }, { name: "a/src/main/java/a/b/P.java", data: MAIN }, { name: "b/src/main/resources/plugin.yml", data: PY }, { name: "b/src/main/java/a/b/P.java", data: MAIN }]), /multi-module/],
  ];
  for (const [name, buf, re] of cases) it(name, () => { const r = ingestUpload(buf, OPTS); assert.equal(r.ok, false); assert.ok(whats(r).some((w) => re.test(w)), JSON.stringify(whats(r))); });
  it("missing plugin.yml is a problem", () => assert.ok(codes(ingestUpload(zip([{ name: "src/main/java/a/b/P.java", data: MAIN }]), OPTS)).includes("no_descriptor")));
  it("an unused build-file dependency is only a note; test deps are ignored", () => {
    const r = ok(ingestUpload(src([{ name: "pom.xml", data: "<project><dependencies><dependency><groupId>com.zaxxer</groupId><artifactId>HikariCP</artifactId></dependency><dependency><groupId>org.junit</groupId><artifactId>junit</artifactId><scope>test</scope></dependency></dependencies></project>" }]), OPTS));
    assert.equal(r.detection.buildSystem, "maven");
