    for (let i = 0; i < 400; i++) {
      const b = Buffer.from(good);
      const flips = 1 + Math.floor(rnd() * 8);
      for (let k = 0; k < flips; k++) b[Math.floor(rnd() * b.length)] = Math.floor(rnd() * 256);
      const cut = rnd() < 0.2 ? b.subarray(0, Math.floor(rnd() * b.length)) : b;
      const r = ingestUpload(cut, OPTS);
      if (r.ok) for (const f of r.files) assert.ok(!f.path.includes("..") && !f.path.startsWith("/") && /^src\/main\/(java|resources)\//.test(f.path), f.path);
    }
  });
});

describe("import ingestion: jars, nesting and packs", () => {
  const jarBuf = readFileSync(path.join(__dirname, "fixtures/cyrus-r2/TfPairA-1.0.0.jar"));
  it("a plugin jar is analysis only, with descriptor and class major", () => {
    const r = ok(ingestUpload(jarBuf, { filename: "TfPairA-1.0.0.jar", mcVersion: "1.21.11" }));
    assert.equal(r.kind, "jar");
    assert.equal(r.detection.name, "TfPairA");
    assert.equal(r.detection.maxClassMajor, 65);
    assert.ok(r.files.some((f) => f.path.endsWith(".class")) && r.files.some((f) => f.path === "plugin.yml"));
    assert.ok(r.notes.some((n) => /cannot change it/.test(n)));
  });
  it("a zip holding one jar is unwrapped once", () => ok(ingestUpload(zip([{ name: "TfPairA-1.0.0.jar", data: jarBuf, method: 0 }]), { filename: "x.zip", mcVersion: "1.21.11" })));
  const rejar = (extra: ZEntry[], mutate?: (name: string, d: Buffer) => Buffer) => {
    const { indexZip, readEntry } = require("../lib/cyrus/inventory/zipread") as typeof import("../lib/cyrus/inventory/zipread");
    const z = indexZip(jarBuf);
    assert.ok(z.ok);
    const entries: ZEntry[] = z.zip.entries.filter((e) => !e.dir).map((e) => { const r = readEntry(z.zip, e); assert.ok(r.ok); return { name: e.name, data: mutate ? mutate(e.name, r.data) : r.data }; });
    return zip([...entries, ...extra]);
  };
  it("signature files are stripped and reported; multi-release is noticed", () => {
    const r = ok(ingestUpload(rejar([{ name: "META-INF/SIGNER.SF", data: "x" }, { name: "META-INF/SIGNER.RSA", data: "y" }, { name: "META-INF/versions/21/x/Y.class", data: Buffer.from([0xca, 0xfe, 0xba, 0xbe, 0, 0, 0, 65, 0, 0]) }]), { filename: "a.jar", mcVersion: "1.21.11" }));
    assert.deepEqual(r.detection.strippedSignatures, ["META-INF/SIGNER.SF", "META-INF/SIGNER.RSA"]);
    assert.ok(!r.files.some((f) => /\.(SF|RSA)$/.test(f.path)));
    assert.equal(r.detection.multiRelease, true);
  });
  it("classes newer than the server's Java are unsupported", () => {
    const r = ingestUpload(rejar([], (n, d) => { if (n.endsWith(".class")) { const c = Buffer.from(d); c.writeUInt16BE(69, 6); return c; } return d; }), { filename: "a.jar", mcVersion: "1.21.11" });
    assert.ok(whats(r).some((w) => /Java 25 classes/.test(w)));
    ok(ingestUpload(rejar([], (n, d) => { if (n.endsWith(".class")) { const c = Buffer.from(d); c.writeUInt16BE(69, 6); return c; } return d; }), { filename: "a.jar", mcVersion: "26.2" }));
  });
  it("a server jar is not a plugin", () => assert.ok(whats(ingestUpload(rejar([{ name: "io/papermc/paperclip/Main.class", data: "x" }]), { filename: "paper.jar", mcVersion: "1.21.11" })).includes("a server jar")));
  it("nesting deeper than the limit is refused; a nested bomb is refused", () => {
    const l3 = zip([{ name: "x.txt", data: "deep" }]);
    const l2 = zip([{ name: "c.jar", data: l3, method: 0 }]);
    const l1 = zip([{ name: "b.jar", data: l2, method: 0 }]);
    assert.ok(codes(ingestUpload(rejar([{ name: "META-INF/libs/a.jar", data: l1, method: 0 }]), { filename: "n.jar", mcVersion: "1.21.11" })).includes("nested_too_deep"));
    ok(ingestUpload(rejar([{ name: "META-INF/libs/a.jar", data: l2, method: 0 }]), { filename: "n.jar", mcVersion: "1.21.11" }));
    const bomb = zip([{ name: "z.bin", data: Buffer.alloc(20 * 1024 * 1024), method: 8 }]);
    assert.ok(codes(ingestUpload(rejar([{ name: "META-INF/libs/bomb.jar", data: bomb, method: 0 }]), { filename: "n.jar", mcVersion: "1.21.11" })).includes("zip_bomb"));
  });
  it("datapacks and resource packs are structure-checked; code inside a pack is refused", () => {
    const mc = JSON.stringify({ pack: { pack_format: 48, description: "Demo pack" } });
    const d = ok(ingestUpload(zip([{ name: "pack.mcmeta", data: mc }, { name: "data/demo/function/hi.mcfunction", data: "say hi" }]), { filename: "dp.zip", mcVersion: "1.21.11" }));
    assert.equal(d.kind, "datapack");
    assert.equal(d.detection.packFormat, 48);
    const rp = ok(ingestUpload(zip([{ name: "pack.mcmeta", data: mc }, { name: "assets/minecraft/textures/item/x.png", data: "png" }]), { filename: "rp.zip", mcVersion: "1.21.11" }));
    assert.equal(rp.kind, "resourcepack");
    assert.equal(ingestUpload(zip([{ name: "pack.mcmeta", data: mc }, { name: "data/demo/x.jar", data: "PK" }]), { filename: "dp.zip", mcVersion: "1.21.11" }).ok, false);
  });
});

