    ["lombok import", src([{ name: "src/main/java/a/b/L.java", data: "package a.b;\nimport lombok.Getter;\nclass L {}" }]), /^Lombok$/],
    ["lombok in build", src([{ name: "build.gradle", data: "dependencies { compileOnly 'org.projectlombok:lombok:1.18.30' }" }]), /^Lombok$/],
    ["annotation processor", src([{ name: "build.gradle", data: "dependencies { annotationProcessor 'com.google.auto.service:auto-service:1.1.1' }" }]), /annotation processors/],
    ["processor service file", src([{ name: "src/main/resources/META-INF/services/javax.annotation.processing.Processor", data: "x.Y" }]), /annotation processors/],
    ["unknown dependency", src([{ name: "src/main/java/a/b/D.java", data: "package a.b;\nimport com.zaxxer.hikari.HikariDataSource;\nclass D {}" }]), /unsupported dependency: com\.zaxxer\.hikari/],
    ["bstats must be shaded", src([{ name: "src/main/java/a/b/M.java", data: "package a.b;\nimport org.bstats.bukkit.Metrics;\nclass M {}" }]), /unsupported dependency: bStats/],
    ["nms", src([{ name: "src/main/java/a/b/N.java", data: "package a.b;\nimport net.minecraft.server.MinecraftServer;\nclass N {}" }]), /server internals/],
    ["paper-plugin.yml", src([{ name: "src/main/resources/paper-plugin.yml", data: "name: P\nversion: 1\nmain: a.b.P\n" }]), /^paper-plugin\.yml$/],
    ["plugin.yml libraries", src([], PY + "libraries:\n  - com.zaxxer:HikariCP:5.1.0\n"), /plugin\.yml libraries/],
    ["module-info", src([{ name: "src/main/java/module-info.java", data: "module a {}" }]), /module-info/],
    ["incomplete sources", src([{ name: "src/main/java/a/b/Q.java", data: "package a.b;\nimport a.b.util.Missing;\nclass Q {}" }]), /incomplete sources/],
    ["main class missing", zip([{ name: "src/main/resources/plugin.yml", data: PY }, { name: "src/main/java/a/b/Other.java", data: "package a.b;\nclass Other {}" }]), /incomplete sources/],
    ["jar in resources", src([{ name: "src/main/resources/lib/extra.jar", data: "PK" }]), /binary code in resources/],
    ["class in java dir", src([{ name: "src/main/java/a/b/X.class", data: "\xca\xfe" }]), /non-Java code/],
    ["spaces in the name", src([], PY.replace("name: P", "name: My Plugin")), /plugin name/],
    ["two modules with descriptors", zip([{ name: "a/src/main/resources/plugin.yml", data: PY }, { name: "a/src/main/java/a/b/P.java", data: MAIN }, { name: "b/src/main/resources/plugin.yml", data: PY }, { name: "b/src/main/java/a/b/P.java", data: MAIN }]), /multi-module/],
  ];
  for (const [name, buf, re] of cases) it(name, () => { const r = ingestUpload(buf, OPTS); assert.equal(r.ok, false); assert.ok(whats(r).some((w) => re.test(w)), JSON.stringify(whats(r))); });
  it("missing plugin.yml is a problem", () => assert.ok(codes(ingestUpload(zip([{ name: "src/main/java/a/b/P.java", data: MAIN }]), OPTS)).includes("no_descriptor")));
  it("an unused build-file dependency is only a note; test deps are ignored", () => {
    const r = ok(ingestUpload(src([{ name: "pom.xml", data: "<project><dependencies><dependency><groupId>com.zaxxer</groupId><artifactId>HikariCP</artifactId></dependency><dependency><groupId>org.junit</groupId><artifactId>junit</artifactId><scope>test</scope></dependency></dependencies></project>" }]), OPTS));
    assert.equal(r.detection.buildSystem, "maven");
    assert.ok(r.notes.some((n) => /com\.zaxxer:HikariCP/.test(n)));
  });
  it("one module of several is picked when only it has a descriptor", () => {
    const r = ok(ingestUpload(zip([{ name: "api/src/main/java/a/b/Api.java", data: "package a.b;\nclass Api {}" }, { name: "plugin/src/main/resources/plugin.yml", data: PY }, { name: "plugin/src/main/java/a/b/P.java", data: MAIN }]), OPTS));
    assert.ok(r.notes.some((n) => /Multi-module/.test(n)));
    assert.deepEqual(r.files.map((f) => f.path).sort(), ["src/main/java/a/b/P.java", "src/main/resources/plugin.yml"]);
  });
  it("build coordinates parse from Groovy/Kotlin DSL and POMs, never test scope", () => {
    assert.deepEqual(parseBuildCoordinates("build.gradle.kts", `dependencies { compileOnly("me.clip:placeholderapi:2.11.6"); implementation("a:b:1") ; testImplementation("x:y:1") }`), ["me.clip:placeholderapi:2.11.6", "a:b:1"]);
  });
});

describe("import ingestion: hostile archives are refused without inflating them", () => {
  const zeros = Buffer.alloc(60 * 1024 * 1024);
  it("zip bomb by ratio (one entry) is refused fast", () => {
    const t0 = Date.now();
    const r = ingestUpload(zip([{ name: "src/main/java/a/B.java", data: zeros, method: 8 }]), OPTS);
    assert.ok(codes(r).includes("zip_bomb") || codes(r).includes("file_too_large"), JSON.stringify(codes(r)));
    assert.ok(Date.now() - t0 < 5000);
  });
  it("archive-level bomb (many small high-ratio entries) is refused", () => {
    const e = Array.from({ length: 200 }, (_, i) => ({ name: `src/main/resources/f${i}.txt`, data: Buffer.alloc(60 * 1024), method: 8 as const }));
    assert.ok(codes(ingestUpload(zip([...e, { name: "src/main/resources/plugin.yml", data: PY }]), OPTS)).includes("zip_bomb"));
  });
  it("a declared inflated total over the budget is refused", () => {
    const e = Array.from({ length: 20 }, (_, i) => ({ name: `src/main/resources/f${i}.txt`, data: "x", usize: 6 * 1024 * 1024 }));
    assert.ok(codes(ingestUpload(zip(e), OPTS)).includes("too_large_inflated"));
  });
  it("a lying header (inflates past its declared size) never allocates past it", () => {
    const r = ingestUpload(zip([{ name: "src/main/resources/plugin.yml", data: PY }, { name: "src/main/java/a/b/P.java", data: MAIN + "/*" + "y".repeat(5000) + "*/", method: 8, usize: 100 }]), OPTS);
    assert.equal(r.ok, false);
  });
  for (const [label, name] of [["traversal", "../../etc/passwd"], ["absolute", "/etc/passwd"], ["backslash", "src\\main\\java\\A.java"], ["drive", "C:/x.java"], ["nul", "a\u0000b"], ["control", "src/a\u0007.java"], ["dot segment", "src/./x.java"], ["deep", Array(50).fill("d").join("/") + "/x"], ["long segment", "src/" + "a".repeat(300)]] as const) {
    it(`unsafe name: ${label}`, () => assert.ok(codes(ingestUpload(src([{ name, data: "x" }]), OPTS)).some((c) => c === "unsafe_path" || c === "unreadable"), label));
  }
  it("names over the byte limit are refused", () => assert.ok(codes(ingestUpload(src([{ name: "src/main/resources/" + "n/".repeat(250) + "x.txt", data: "x" }]), OPTS)).length));
  it("duplicate paths (exact and case-folded) are refused", () => {
    assert.ok(codes(ingestUpload(src([{ name: "src/main/java/a/b/P.java", data: MAIN }]), OPTS)).includes("duplicate_path"));
    assert.ok(codes(ingestUpload(src([{ name: "src/main/java/a/b/p.java", data: MAIN }]), OPTS)).includes("duplicate_path"));
  });
  it("symbolic links are refused", () => assert.ok(codes(ingestUpload(src([{ name: "src/main/resources/link.yml", data: "/etc/shadow", unixMode: 0o120777 }]), OPTS)).includes("symlink")));
  it("a regular Unix file mode is fine", () => ok(ingestUpload(src([{ name: "src/main/resources/ok.yml", data: "a: 1", unixMode: 0o100644 }]), OPTS)));
  it("encrypted entries are refused", () => assert.ok(codes(ingestUpload(src([{ name: "src/main/resources/e.yml", data: "x", flags: 1 }]), OPTS)).includes("encrypted")));
  it("too many entries are refused", () => assert.ok(codes(ingestUpload(zip(Array.from({ length: IMPORT_LIMITS.maxEntries + 1 }, (_, i) => ({ name: `f${i}`, data: "" }))), OPTS)).includes("too_many_entries")));
  it("an oversized upload is refused before parsing", () => assert.ok(codes(ingestUpload(Buffer.alloc(IMPORT_LIMITS.maxUploadBytes + 1), OPTS)).includes("upload_too_large")));
  it("truncated and garbage inputs never throw", () => {
    const good = demo();
    for (const n of [0, 1, 21, 22, 100, good.length >> 1, good.length - 1]) assert.equal(ingestUpload(good.subarray(0, n), OPTS).ok, false);
    assert.equal(ingestUpload(Buffer.from("not a zip at all, just text".repeat(10)), OPTS).ok, false);
  });
  it("fuzz: 400 random mutations of a valid archive never throw and never yield unsafe kept paths", () => {
    const good = demo();
    let seed = 1234567;
    const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
    for (let i = 0; i < 400; i++) {
      const b = Buffer.from(good);
      const flips = 1 + Math.floor(rnd() * 8);
      for (let k = 0; k < flips; k++) b[Math.floor(rnd() * b.length)] = Math.floor(rnd() * 256);
      const cut = rnd() < 0.2 ? b.subarray(0, Math.floor(rnd() * b.length)) : b;
      const r = ingestUpload(cut, OPTS);
      if (r.ok) for (const f of r.files) assert.ok(!f.path.includes("..") && !f.path.startsWith("/") && /^src\/main\/(java|resources)\//.test(f.path), f.path);
    }
  });
});

describe("import ingestion: jars, nesting and packs", () => {
  const jarBuf = readFileSync(path.join(__dirname, "fixtures/cyrus-r2/TfPairA-1.0.0.jar"));
  it("a plugin jar is analysis only, with descriptor and class major", () => {
    const r = ok(ingestUpload(jarBuf, { filename: "TfPairA-1.0.0.jar", mcVersion: "1.21.11" }));
    assert.equal(r.kind, "jar");
    assert.equal(r.detection.name, "TfPairA");
    assert.equal(r.detection.maxClassMajor, 65);
    assert.ok(r.files.some((f) => f.path.endsWith(".class")) && r.files.some((f) => f.path === "plugin.yml"));
    assert.ok(r.notes.some((n) => /cannot change it/.test(n)));
  });
  it("a zip holding one jar is unwrapped once", () => ok(ingestUpload(zip([{ name: "TfPairA-1.0.0.jar", data: jarBuf, method: 0 }]), { filename: "x.zip", mcVersion: "1.21.11" })));
  const rejar = (extra: ZEntry[], mutate?: (name: string, d: Buffer) => Buffer) => {
    const { indexZip, readEntry } = require("../lib/cyrus/inventory/zipread") as typeof import("../lib/cyrus/inventory/zipread");
    const z = indexZip(jarBuf);
    assert.ok(z.ok);
    const entries: ZEntry[] = z.zip.entries.filter((e) => !e.dir).map((e) => { const r = readEntry(z.zip, e); assert.ok(r.ok); return { name: e.name, data: mutate ? mutate(e.name, r.data) : r.data }; });
    return zip([...entries, ...extra]);
  };
  it("signature files are stripped and reported; multi-release is noticed", () => {
    const r = ok(ingestUpload(rejar([{ name: "META-INF/SIGNER.SF", data: "x" }, { name: "META-INF/SIGNER.RSA", data: "y" }, { name: "META-INF/versions/21/x/Y.class", data: Buffer.from([0xca, 0xfe, 0xba, 0xbe, 0, 0, 0, 65, 0, 0]) }]), { filename: "a.jar", mcVersion: "1.21.11" }));
    assert.deepEqual(r.detection.strippedSignatures, ["META-INF/SIGNER.SF", "META-INF/SIGNER.RSA"]);
    assert.ok(!r.files.some((f) => /\.(SF|RSA)$/.test(f.path)));
    assert.equal(r.detection.multiRelease, true);
  });
  it("classes newer than the server's Java are unsupported", () => {
    const r = ingestUpload(rejar([], (n, d) => { if (n.endsWith(".class")) { const c = Buffer.from(d); c.writeUInt16BE(69, 6); return c; } return d; }), { filename: "a.jar", mcVersion: "1.21.11" });
    assert.ok(whats(r).some((w) => /Java 25 classes/.test(w)));
    ok(ingestUpload(rejar([], (n, d) => { if (n.endsWith(".class")) { const c = Buffer.from(d); c.writeUInt16BE(69, 6); return c; } return d; }), { filename: "a.jar", mcVersion: "26.2" }));
  });
  it("a server jar is not a plugin", () => assert.ok(whats(ingestUpload(rejar([{ name: "io/papermc/paperclip/Main.class", data: "x" }]), { filename: "paper.jar", mcVersion: "1.21.11" })).includes("a server jar")));
  it("nesting deeper than the limit is refused; a nested bomb is refused", () => {
    const l3 = zip([{ name: "x.txt", data: "deep" }]);
    const l2 = zip([{ name: "c.jar", data: l3, method: 0 }]);
    const l1 = zip([{ name: "b.jar", data: l2, method: 0 }]);
    assert.ok(codes(ingestUpload(rejar([{ name: "META-INF/libs/a.jar", data: l1, method: 0 }]), { filename: "n.jar", mcVersion: "1.21.11" })).includes("nested_too_deep"));
    ok(ingestUpload(rejar([{ name: "META-INF/libs/a.jar", data: l2, method: 0 }]), { filename: "n.jar", mcVersion: "1.21.11" }));
    const bomb = zip([{ name: "z.bin", data: Buffer.alloc(20 * 1024 * 1024), method: 8 }]);
    assert.ok(codes(ingestUpload(rejar([{ name: "META-INF/libs/bomb.jar", data: bomb, method: 0 }]), { filename: "n.jar", mcVersion: "1.21.11" })).includes("zip_bomb"));
  });
  it("datapacks and resource packs are structure-checked; code inside a pack is refused", () => {
    const mc = JSON.stringify({ pack: { pack_format: 48, description: "Demo pack" } });
    const d = ok(ingestUpload(zip([{ name: "pack.mcmeta", data: mc }, { name: "data/demo/function/hi.mcfunction", data: "say hi" }]), { filename: "dp.zip", mcVersion: "1.21.11" }));
    assert.equal(d.kind, "datapack");
    assert.equal(d.detection.packFormat, 48);
    const rp = ok(ingestUpload(zip([{ name: "pack.mcmeta", data: mc }, { name: "assets/minecraft/textures/item/x.png", data: "png" }]), { filename: "rp.zip", mcVersion: "1.21.11" }));
    assert.equal(rp.kind, "resourcepack");
    assert.equal(ingestUpload(zip([{ name: "pack.mcmeta", data: mc }, { name: "data/demo/x.jar", data: "PK" }]), { filename: "dp.zip", mcVersion: "1.21.11" }).ok, false);
  });
});

