describe("import licence + attestation + sharing", () => {
  it("licence texts and names normalise to SPDX ids; unknown is honest", () => {
    assert.equal(licenceFromText(readFileSync(path.join(FX, "demo-src/LICENSE"), "utf8")), "MIT");
    assert.equal(licenceFromText("GNU GENERAL PUBLIC LICENSE\nVersion 3, 29 June 2007"), "GPL-3.0");
    assert.equal(licenceFromText("GNU LESSER GENERAL PUBLIC LICENSE Version 3"), "LGPL-3.0");
    assert.equal(licenceFromText("Apache License\nVersion 2.0, January 2004"), "Apache-2.0");
    assert.equal(licenceFromText("Copyright 2026 Me. All rights reserved."), "LicenseRef-All-Rights-Reserved");
    assert.equal(licenceFromText("do what you want"), null);
    assert.equal(normaliseLicence("GPL-3.0-or-later"), "GPL-3.0");
    assert.equal(normaliseLicence("Apache License, Version 2.0"), "Apache-2.0");
    assert.deepEqual(detectLicences([{ path: "src/A.java", text: "/* SPDX-License-Identifier: MIT OR Apache-2.0 */" }]).map((d) => d.spdx), ["MIT", "Apache-2.0"]);
    assert.deepEqual(detectLicences([{ path: "pom.xml", text: "<licenses><license><name>GNU General Public License v3</name></license></licenses>" }]).map((d) => d.spdx), ["GPL-3.0"]);
  });
  const facts = { at: new Date("2026-10-10T08:00:00Z"), uploadSha256: "a".repeat(64), detectedLicences: [] };
  const good = { accepted: true, typedName: "Dana Demo", textVersion: ATTESTATION_TEXT_VERSION };
  it("an attestation needs the box, the current text and a typed name", () => {
    assert.equal(buildAttestation({ ...good, accepted: false }, facts).ok, false);
    assert.equal(buildAttestation({ ...good, accepted: "true" }, facts).ok, false);
    assert.equal(buildAttestation({ ...good, textVersion: "old" }, facts).ok, false);
    assert.equal(buildAttestation({ ...good, typedName: " " }, facts).ok, false);
    assert.equal(buildAttestation({ ...good, claimedLicence: "WTFPL-ish" }, facts).ok, false);
    const r = buildAttestation({ ...good, typedName: "  Dana\u0007  Demo " }, facts);
    assert.ok(r.ok);
    assert.equal(r.record.typedName, "Dana Demo");
    assert.deepEqual(r.record.detected, ["unknown"]);
    assert.equal(r.record.claimedLicence, "unknown");
    assert.equal(r.record.at, "2026-10-10T08:00:00.000Z");
  });
  const consent = { given: true, textVersion: SHARE_CONSENT_TEXT_VERSION };
  const att = (detected: string[], claimed = "unknown") => ({ detected, claimedLicence: claimed });
  it("sharing needs consent AND a licence that permits redistribution; unknown is private only", () => {
    assert.equal(mayShareImport({ attestation: att(["unknown"]), kind: "source", consent }).ok, false);
    assert.equal(mayShareImport({ attestation: att(["MIT"]), kind: "source", consent: null }).ok, false);
    assert.equal(mayShareImport({ attestation: att(["MIT"]), kind: "source", consent: { given: true, textVersion: "old" } }).ok, false);
    assert.ok(mayShareImport({ attestation: att(["MIT"]), kind: "source", consent }).ok);
    assert.ok(mayShareImport({ attestation: att(["unknown"], "Apache-2.0"), kind: "source", consent }).ok);
    assert.equal(mayShareImport({ attestation: att(["GPL-3.0"]), kind: "source", consent }).ok, false);
    assert.ok(mayShareImport({ attestation: att(["GPL-3.0"]), kind: "source", consent, sourcePublished: true }).ok);
    assert.equal(mayShareImport({ attestation: att(["GPL-3.0"], "MIT"), kind: "source", consent }).ok, false);
    assert.equal(mayShareImport({ attestation: att(["LicenseRef-All-Rights-Reserved"]), kind: "source", consent }).ok, false);
    assert.equal(mayShareImport({ attestation: att(["MIT"]), kind: "jar", consent }).ok, false);
    assert.equal(effectiveLicence(att(["MIT", "GPL-3.0"])).licence, "unknown");
  });
  it("the import record in the revision metadata is strictly validated", () => {
    const r = buildAttestation(good, facts);
    assert.ok(r.ok);
    const meta = { importId: "ci" + "0".repeat(20), kind: "source", filename: "x.zip", uploadSha256: "a".repeat(64), size: 10, attestation: r.record, detection: {}, deps: ["vault-api"], depsVersion: "v", ignored: [], scanProfile: "attested", serviceJobId: null, modBuildId: null, mcVersion: "1.21.11", namespace: "nx_ab12cd34" };
    assert.deepEqual(validateImportMeta(meta), []);
    assert.ok(validateEngineRecord({ import: meta }).ok);
    assert.equal(validateEngineRecord({ import: { ...meta, extra: 1 } }).ok, false);
    assert.equal(validateEngineRecord({ import: { ...meta, scanProfile: "strict" } }).ok, false);
    assert.equal(validateEngineRecord({ import: { ...meta, attestation: { ...r.record, uploadSha256: "b".repeat(64) } } }).ok, false);
  });
});

describe("scan profiles over real javac output", () => {
  const J = path.join(FX, "javap");
  const t = (n: string) => readFileSync(path.join(J, `${n}.txt`), "utf8");
  const sev = (f: Finding[]) => f.map((x) => `${x.severity[0]}:${x.rule}`).sort();
  const blocks = (f: Finding[]) => f.filter((x) => x.severity === "block").map((x) => x.rule).sort();
  // name -> [strict blocks, attested blocks, attested warnings that must appear]
  const table: Record<string, [string[], string[], string[]]> = {
    HttpMetrics: [["network"], [], ["network-http", "network-endpoint"]],
    HttpClientCheck: [["network"], [], ["network-http"]],
    ReflectVersion: [["class-name-string", "reflection"], [], ["reflection-lookup", "internals-name"]],
    SqliteStore: [["jndi-rmi-jmx"], [], ["database"]],
    SelfDisable: [["load-plugins"], [], ["disable-plugin"]],
    ExecCmd: [["exec"], ["exec"], []],
    ProcBuild: [["exec"], ["exec"], []],
    RawSocket: [["network"], ["network"], []],
    MixedHttpSocket: [["network"], ["network"], ["network-http"]],
    LoadJar: [["classload", "network", "reflection"], ["classload", "network"], []],
    JndiLookup: [["jndi-rmi-jmx"], ["jndi-rmi-jmx"], []],
    JndiDriver: [["jndi-rmi-jmx"], ["jndi-rmi-jmx"], ["database"]],
    DnsExfil: [["dns"], ["dns"], []],
    PrivateLookup: [["reflection"], ["reflection"], []],
    UnsafeTrick: [["reflection", "unsafe"], ["unsafe"], []],
    NamesRuntime: [["class-name-string", "reflection"], ["class-name-string"], []],
  };
  it("every fixture is covered", () => assert.deepEqual(readdirSync(J).map((f) => f.replace(/\.txt$/, "")).sort(), Object.keys(table).sort()));
  for (const [n, [strict, att, warns]] of Object.entries(table)) {
    it(`${n}: strict blocks ${strict.join("+") || "none"}; attested blocks ${att.join("+") || "none"}`, () => {
      assert.deepEqual(blocks(scan.scanJavapText(t(n))), strict);
      assert.deepEqual(scan.scanJavapText(t(n)), scan.scanJavapText(t(n), { profile: "strict" }), "strict is the default");
      const a = scan.scanJavapText(t(n), { profile: "attested" });
      assert.deepEqual(blocks(a), att, JSON.stringify(sev(a)));
      for (const w of warns) assert.ok(a.some((x) => x.severity === "warn" && x.rule === w), `${n} warns ${w}`);
    });
  }
  it("an unknown profile fails closed (throws), never weakens", () => assert.throws(() => scan.scanJavapText(t("ExecCmd"), { profile: "lenient" })));
  it("only the documented rules downgrade", () => assert.deepEqual(Object.keys(scan.ATTESTED_DOWNGRADES).sort(), ["class-name-string", "jndi-rmi-jmx", "load-plugins", "network", "reflection"]));
  it("reports never say safe", () => {
    const a = scan.scanJavapText(t("HttpMetrics"), { profile: "attested" });
    assert.match(scan.attestedSummary(a), /^Checked with the attested profile: \d+ warnings?$/);
    assert.ok(!/safe/i.test(scan.attestedSummary(a)) && !/safe/i.test(scan.attestedSummary([])));
  });
  it("a change build may keep what the import had, but a NEW downgraded finding is a block", () => {
    const base = scan.scanJavapText(t("HttpMetrics"), { profile: "attested" });
    const baseline = scan.baselineOf(base);
    assert.equal(blocks(scan.applyBaseline(base, baseline)).length, 0);
    const added = scan.scanJavapText(t("HttpMetrics") + "\n" + t("SqliteStore"), { profile: "attested" });
    const judged = scan.applyBaseline(added, baseline);
    assert.deepEqual(blocks(judged), ["database"]);
    assert.ok(judged.find((x) => x.rule === "database")!.message.includes("new in this change"));
  });
});

