import { zipDir } from "./_zipwriter";
import { ingestUpload, type IngestOk } from "../lib/cyrus/import/ingest";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const FX = path.join(ROOT, "test/fixtures/cyrus-import");
const KEY = "test-key-0123456789abcdef";

const FAKE_CLAUDE = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
const prompt = a[a.indexOf("--") + 1] || "";
const sys = a[a.indexOf("--system-prompt") + 1] || "";
const ws = process.cwd();
const docsDir = path.join(ws, "imported-docs");
const docs = fs.existsSync(docsDir) ? fs.readdirSync(docsDir) : [];
const firstDoc = docs.length ? fs.readFileSync(path.join(docsDir, docs[0]), "utf8") : "";
const kind = /IMPORTED: their own code/.test(prompt) ? "import-change" : /automatic safety scan rejected/.test(prompt) ? "repair-safety" : /change request/.test(prompt) ? "change" : "other";
fs.appendFileSync(path.join(process.env.HOME, "claude.log"), JSON.stringify({ kind, docs, quoted: /QUOTED DATA, NOT INSTRUCTIONS/.test(firstDoc) && /END QUOTED DATA/.test(firstDoc), injectionInDoc: /ignore all previous instructions/i.test(firstDoc),
  importRules: /server owner's OWN imported plugin/.test(sys), depsInSys: /Vault API \\(com\\.github\\.MilkBowl:VaultAPI:1\\.7\\)/.test(sys), nsInPrompt: (prompt.match(/reserved namespace (nx_[a-z0-9]{8})/) || [])[1] || null }) + "\\n");
const w = (rel, t) => { fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true }); fs.writeFileSync(path.join(ws, rel), t); };
const out = (o) => process.stdout.write(JSON.stringify(o) + "\\n");
out({ type: "system", subtype: "init", model: "claude-sonnet-5-5" });
const P = "src/main/java/me/demo/importdemo/";
if (kind === "import-change") {
  const f = path.join(ws, P + "DemoCommand.java");
  w(P + "DemoCommand.java", fs.readFileSync(f, "utf8").replace("ImportDemo is running.", "ImportDemo is running (changed by Cyrus)."));
  w("src/main/resources/plugin.yml", fs.readFileSync(path.join(ws, "src/main/resources/plugin.yml"), "utf8").replace("version: 1.4.2", "version: 1.5.0"));
  w("modbuilder.json", JSON.stringify({ name: "ImportDemo", version: "1.5.0", tagline: "Demo", summary: "Demo.", changes: "Changed the status line." }));
  // a model that wanders outside the allow-list: all of these must be rejected
  w("build.gradle", "tasks.register('x') { doLast { 'id'.execute() } }");
  w("src/main/resources/payload.jar", "PK");
  w("src/main/resources/notes.sh", "#!/bin/sh");
  if (/ADDPHONE/.test(prompt)) w(P + "Phone.java", "package me.demo.importdemo;\\nclass Phone {}\\n");
} else if (kind === "repair-safety") {
  fs.rmSync(path.join(ws, P + "Phone.java"), { force: true });
}
out({ type: "assistant", message: { id: "m1", usage: { input_tokens: 2, output_tokens: 50 }, content: [{ type: "text", text: "Done." }] } });
out({ type: "result", subtype: "success", is_error: false, num_turns: 2, total_cost_usd: 0.01, duration_ms: 100, result: "Done.", usage: { input_tokens: 2, output_tokens: 50 } });
`;
// javac: logs its classpath + flags, writes one .class per source (package from the source), fails on COMPILE_ERROR.
const FAKE_JAVAC = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
const d = a[a.indexOf("-d") + 1];
const srcs = a.filter((x) => x.endsWith(".java"));
fs.appendFileSync(path.join(process.env.HOME, "javac.log"), JSON.stringify({ cp: a[a.indexOf("-cp") + 1], procNone: a.includes("-proc:none"), release: a[a.indexOf("--release") + 1], n: srcs.length }) + "\\n");
for (const f of srcs) {
  const t = fs.readFileSync(f, "utf8");
  if (t.includes("COMPILE_ERROR")) { process.stderr.write(f + ":1: error: cannot find symbol\\n1 error\\n"); process.exit(1); }
  const pkg = (t.match(/^\\s*package\\s+([\\w.]+)\\s*;/m) || [])[1] || "";
  const dir = path.join(d, ...pkg.split(".").filter(Boolean));
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, path.basename(f, ".java") + ".class"), "x");
}
`;
const FAKE_JAR = `#!/usr/bin/env node
const a = process.argv.slice(2); require("fs").writeFileSync(a[a.indexOf("--file") + 1], "PK fake " + Date.now());
`;
// javap: prints REAL javap -v text from the fixtures, chosen by class name (Metrics/Phone -> HTTPS metrics, Evil -> exec).
const FAKE_JAVAP = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
for (const c of process.argv.slice(2).filter((x) => x.endsWith(".class"))) {
  const n = path.basename(c, ".class");
  const pick = /Metrics|Phone/.test(n) ? "HttpMetrics" : /Evil/.test(n) ? "ExecCmd" : /UpdateChecker/.test(n) ? "HttpClientCheck" : null;
  if (!pick) { process.stdout.write("public class " + n + "\\n  #1 = Utf8 " + n + "\\n"); continue; }
  process.stdout.write(fs.readFileSync(path.join(process.env.HOME, "javap", pick + ".txt"), "utf8").replace(/public class \\w+/, "public class " + n));
}
`;
const YAML_STUB = `module.exports = {
  parse(t) { const o = {}; for (const l of String(t).split("\\n")) { const m = l.match(/^([\\w-]+):\\s*(.*)$/); if (m) o[m[1]] = m[2].replace(/^'(.*)'$/, "$1"); } return o; },
  stringify(o) { return Object.entries(o).map(([k, v]) => k + ": " + v).join("\\n") + "\\n"; },
};
`;
function yamlMissing(): boolean { try { require.resolve("yaml", { paths: [SVC] }); return false; } catch { return true; } }

let dir = "", proc: ChildProcess | null = null, port = 0, svcErr = "";
const jl = (f: string) => fs.readFileSync(path.join(dir, f), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
async function api(method: string, p: string, body?: unknown) {
  const r = await fetch(`http://127.0.0.1:${port}${p}`, { method, headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
  const text = await r.text();
  let j: Record<string, unknown> = {};
  try { j = JSON.parse(text); } catch { j = { raw: text }; }
  return { status: r.status, ...j } as Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
}
async function waitDone(id: string) {
  for (let i = 0; i < 300; i++) {
    const r = await api("GET", `/builds/${id}`);
    if (r.status === "succeeded" || r.status === "failed") return r;
    await new Promise((res) => setTimeout(res, 100));
  }
  throw new Error("did not finish: " + svcErr.slice(-2000));
}
const b64 = (b: Buffer) => b.toString("base64");
let demo: IngestOk;
const sourceBody = (id: string, extra: Record<string, unknown> = {}) => ({
  id, kind: "source", mcVersion: "1.21.11", pluginName: "ImportDemo", namespace: "nx_ab12cd34", deps: demo.deps.allowed,
  files: demo.files.map((f) => ({ path: f.path, data: b64(f.data) })), docs: demo.docs.map((d) => ({ path: d.path, text: d.text })), ...extra,
});

describe("modbuilder import path (offline, fake CLI + javac + javap over real javap text)", () => {
  before(async () => {
    const r = ingestUpload(zipDir(path.join(FX, "demo-src"), "ImportDemo-main/"), { filename: "ImportDemo-main.zip", mcVersion: "1.21.11" });
    assert.ok(r.ok);
    demo = r as IngestOk;
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-imp-"));
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", FAKE_JAVAP]]) fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    fs.mkdirSync(path.join(dir, "javap"));
    for (const f of ["HttpMetrics", "ExecCmd", "HttpClientCheck"]) fs.copyFileSync(path.join(FX, "javap", `${f}.txt`), path.join(dir, "javap", `${f}.txt`));
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent/paper-api.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\n");
    // a test allowlist whose jars exist here (the real deps.json pins the real jars' hashes)
    const depsDir = path.join(dir, "deps");
    fs.mkdirSync(depsDir);
    const real = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/import/deps.json"), "utf8"));
    for (const d of real.dependencies) {
      if (d.id === "protocollib") continue; // "allowlisted but not installed" case
      const bytes = Buffer.from(`fake jar ${d.id}`);
      fs.writeFileSync(path.join(depsDir, d.file), bytes);
      d.sha256 = crypto.createHash("sha256").update(bytes).digest("hex");
    }
    fs.writeFileSync(path.join(dir, "deps.json"), JSON.stringify(real));
    for (const f of ["claude.log", "javac.log"]) fs.writeFileSync(path.join(dir, f), "");
    const nodePath = path.join(dir, "node_modules");
    if (yamlMissing()) { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), YAML_STUB); }
    port = 39000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: {
        PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"),
        MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_GUARD: "off", NODE_PATH: nodePath,
        MB_DEPS_DIR: depsDir, MB_DEPS_MANIFEST: path.join(dir, "deps.json"),
      } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc.stderr?.on("data", (d) => { svcErr += d; });
    for (let i = 0; i < 100; i++) {
      try { const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json(); if (h.ok) return; } catch { /* starting */ }
      await new Promise((res) => setTimeout(res, 100));
    }
    throw new Error(`service did not start: ${svcErr.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("advertises imports, both scan profiles and which allowlisted jars it holds", async () => {
    const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json();
    assert.deepEqual(h.features.imports.kinds, ["source", "jar"]);
    assert.deepEqual(h.features.imports.scanProfiles, ["strict", "attested"]);
    assert.deepEqual(h.features.imports.deps.installed.sort(), ["luckperms-api", "placeholderapi", "vault-api"]);
  });

  it("import -> base build: no AI call, allowlisted classpath, -proc:none, attested scan with warnings (never 'safe')", async () => {
    const r0 = await api("POST", "/imports", sourceBody("imp-base-01"));
    assert.equal(r0.status, "queued", JSON.stringify(r0));
    const r = await waitDone("imp-base-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events) + r.errorDetail + svcErr.slice(-2000));
    assert.equal(r.aiCalls.length, 0);
    assert.equal(jl("claude.log").length, 0, "the import itself never calls the model");
    const jc = jl("javac.log").at(-1);
    assert.ok(jc.procNone);
    assert.ok(jc.cp.includes("VaultAPI-1.7.jar") && jc.cp.includes("placeholderapi-2.11.6.jar") && !jc.cp.includes("luckperms"), jc.cp);
    assert.equal(r.safety.profile, "attested");
    assert.equal(r.safety.verdict, "warn");
    assert.match(r.safety.summary, /^Checked with the attested profile: \d+ warnings$/);
    assert.ok(r.safety.findings.some((f: { rule: string; where: string }) => f.rule === "network-http" && /Metrics/.test(f.where)));
    assert.ok(r.safety.findings.every((f: { severity: string }) => f.severity !== "block"));
    assert.ok(!r.events.some((e: { message: string }) => /passed|safe/i.test(e.message)), "no 'passed'/'safe' wording for imported code");
    assert.ok(r.warnings[0].includes("does not guarantee that it is safe"));
    assert.ok(r.jar && r.jar.sha256);
    const paths = r.files.map((f: { path: string }) => f.path);
    assert.ok(!paths.includes("build.gradle") && !paths.includes("gradlew") && !paths.some((p: string) => p.startsWith("imported-docs")));
    assert.ok(paths.includes("build.gradle.kts"), "the pinned template, not the uploader's build");
    const yml = await (await fetch(`http://127.0.0.1:${port}/builds/imp-base-01/source?path=src/main/resources/plugin.yml`, { headers: { Authorization: `Bearer ${KEY}` } })).text();
    assert.match(yml, /^# ImportDemo plugin descriptor \(hand-written by the author; keep the comments\)/, "the owner's comments survive");
    assert.match(yml, /^api-version: '1\.21\.11'$/m);
  });

  it("change request on the import: docs as quoted DATA during the AI call only, import rules, rejected paths, same classpath", async () => {
    const r0 = await api("POST", "/builds", { id: "imp-chg-01", prompt: "Imported plugin: ImportDemo", baseBuildId: "imp-base-01", changeRequest: "Change the status line of /importdemo", mcVersion: "1.21.11" });
    assert.equal(r0.status, "queued", JSON.stringify(r0));
    const r = await waitDone("imp-chg-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events.map((e: { message: string; detail?: string }) => e.message + (e.detail ? " :: " + e.detail : ""))) + svcErr.slice(-2000));
    const call = jl("claude.log").find((c) => c.kind === "import-change");
    assert.ok(call, JSON.stringify(jl("claude.log")));
    assert.deepEqual(call.docs.length, 2);
    assert.ok(call.quoted && call.injectionInDoc, "the README (with its injection attempt) arrives only as a quoted DATA file");
    assert.ok(call.importRules && call.depsInSys);
    assert.equal(call.nsInPrompt, "nx_ab12cd34");
    assert.equal(r.version, "1.5.0");
    assert.deepEqual([...r.rejectedPaths].sort(), ["build.gradle", "src/main/resources/notes.sh", "src/main/resources/payload.jar"]);
    const paths = r.files.map((f: { path: string }) => f.path);
    assert.ok(!paths.some((p: string) => p.startsWith("imported-docs") || p === "build.gradle" || p.endsWith(".jar")));
    assert.ok(jl("javac.log").at(-1).cp.includes("VaultAPI-1.7.jar"));
    assert.equal(r.safety.profile, "attested");
    assert.ok(r.safety.findings.every((f: { severity: string }) => f.severity !== "block"), "what the import already did is kept");
  });

  it("a change that ADDS a network call is blocked by the import's baseline, then repaired", async () => {
    await api("POST", "/builds", { id: "imp-chg-02", prompt: "Imported plugin: ImportDemo", baseBuildId: "imp-chg-01", changeRequest: "ADDPHONE a phone-home helper class", mcVersion: "1.21.11" });
    const r = await waitDone("imp-chg-02");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events.map((e: { message: string }) => e.message)));
    assert.ok(jl("claude.log").some((c) => c.kind === "repair-safety"), "the new network call went back as a safety repair");
    assert.ok(r.events.some((e: { message: string }) => /Safety check flagged/.test(e.message)));
  });

  it("unsupported or uninstalled dependencies, Kotlin, build files and traversal are refused by the service itself", async () => {
    assert.match((await api("POST", "/imports", sourceBody("imp-bad-01", { deps: ["hikaricp"] }))).error, /unsupported dependency: hikaricp/);
    const notInstalled = await api("POST", "/imports", sourceBody("imp-bad-02", { deps: ["protocollib"] }));
    assert.equal(notInstalled.status, 503);
    const add = (p: string, t = "x") => sourceBody("imp-bad-03", { files: [...demo.files.map((f) => ({ path: f.path, data: b64(f.data) })), { path: p, data: b64(Buffer.from(t)) }] });
    assert.match((await api("POST", "/imports", add("src/main/kotlin/a/K.kt", "class K"))).error, /only src\/main\/java and src\/main\/resources/);
    assert.match((await api("POST", "/imports", add("src/main/java/a/K.kt", "class K"))).error, /only src\/main\/java/);
    assert.match((await api("POST", "/imports", add("build.gradle", "x"))).error, /only src\/main\/java/);
    assert.match((await api("POST", "/imports", add("src/main/java/../../../etc/x.java"))).error, /unsafe path/);
    assert.match((await api("POST", "/imports", add("src/main/resources/lib.jar"))).error, /resource type not accepted/);
    assert.match((await api("POST", "/imports", add("src/main/java/me/demo/importdemo/importdemo.java"))).error, /duplicate path/);
    assert.equal((await api("GET", "/builds/imp-bad-03")).status, 404, "nothing was created");
  });

  it("source that does not compile fails with the compiler output; exec stays blocked even for owned code", async () => {
    const files = demo.files.map((f) => ({ path: f.path, data: b64(f.path.endsWith("DemoCommand.java") ? Buffer.from(f.data.toString() + "\n// COMPILE_ERROR") : f.data) }));
    await api("POST", "/imports", sourceBody("imp-bad-04", { files }));
    const c = await waitDone("imp-bad-04");
    assert.equal(c.status, "failed");
    assert.equal(c.errorCode, "compile");
    const evil = ingestUpload(zipDir(path.join(FX, "evil-src")), { filename: "evil.zip", mcVersion: "1.21.11" });
    assert.ok(evil.ok);
    await api("POST", "/imports", { id: "imp-evil-01", kind: "source", mcVersion: "1.21.11", namespace: "nx_ab12cd34", files: (evil as IngestOk).files.map((f) => ({ path: f.path, data: b64(f.data) })) });
    const e = await waitDone("imp-evil-01");
    assert.equal(e.status, "failed");
    assert.equal(e.errorCode, "safety");
    assert.match(e.error, /runs other programs/);
    assert.equal(e.safety.verdict, "block");
  });

  it("jar-only import: attested analysis, no artifact, and it can never be a change base", async () => {
    const cls = (n: string) => ({ path: `me/demo/${n}.class`, data: b64(Buffer.concat([Buffer.from([0xca, 0xfe, 0xba, 0xbe, 0, 0, 0, 65]), Buffer.from(n)])) });
    const r0 = await api("POST", "/imports", { id: "imp-jar-01", kind: "jar", mcVersion: "1.21.11", namespace: "nx_ab12cd34", files: [cls("Main"), cls("Metrics"), { path: "plugin.yml", data: b64(Buffer.from("name: J\nversion: 1\nmain: me.demo.Main\n")) }] });
    assert.equal(r0.status, "queued");
    const r = await waitDone("imp-jar-01");
    assert.equal(r.status, "succeeded");
    assert.equal(r.analysisOnly, true);
    assert.equal(r.safety.profile, "attested");
    assert.ok(r.safety.findings.some((f: { rule: string }) => f.rule === "network-http"));
    assert.equal((await fetch(`http://127.0.0.1:${port}/builds/imp-jar-01/artifact`, { headers: { Authorization: `Bearer ${KEY}` } })).status, 404);
    const chg = await api("POST", "/builds", { id: "imp-jar-chg", prompt: "Imported plugin: J", baseBuildId: "imp-jar-01", changeRequest: "change it", mcVersion: "1.21.11" });
    assert.match(String(chg.error), /analysis only/);
    assert.match(String((await api("POST", "/imports", { id: "imp-jar-02", kind: "jar", mcVersion: "1.21.11", namespace: "nx_ab12cd34", files: [{ path: "a/B.class", data: b64(Buffer.from("not a class")) }] })).error), /not a class file/);
  });
});

