// Cyrus import: the API routes (lib/cyrus/import/api.ts, what app/api/cyrus/import/** call) and the importer, with
// in-memory fakes for every host dependency (DB rows, build service, quarantine, server view). No DB, no network.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { zip, zipDir } from "./_zipwriter";
import { handleConflicts, handleDelete, handleGet, handleList, handleUpload, type ImportApiDeps } from "../lib/cyrus/import/api";
import { ATTESTATION_TEXT_VERSION, type ImportMeta } from "../lib/cyrus/import/attestation";
import type { ImporterDeps, ImportRow, SvcView } from "../lib/cyrus/import/importer";
import { MemoryQuarantine } from "../lib/cyrus/import/store";
import { validateEngineRecord, validateManifest } from "../lib/cyrus/engine-core/revisions";
import type { ReadOnlyServerFs } from "../lib/cyrus/inventory/types";

const FX = path.join(__dirname, "fixtures");
const DEMO = zipDir(path.join(FX, "cyrus-import/demo-src"), "ImportDemo-main/");

function world() {
  let n = 0;
  const projects = new Map<string, { id: string; userId: string; namespace: string; title: string | null; rootBuildId: string | null }>();
  const revs: { id: string; projectId: string; seq: number; status: string; engine: Record<string, unknown>; manifest: unknown[]; modBuildId: string | null; createdAt: Date }[] = [];
  const modBuilds = new Map<string, { id: string; userId: string; status: string; prompt: string }>();
  const svcBodies: Record<string, unknown>[] = [];
  const svcState = new Map<string, SvcView>();
  const quarantine = new MemoryQuarantine();
  const serverFiles = new Map<string, Buffer>();
  const rowOf = (pid: string): ImportRow | null => {
    const p = projects.get(pid);
    const r = revs.find((x) => x.projectId === pid && x.seq === 1);
    return p && r ? { projectId: p.id, namespace: p.namespace, title: p.title, revisionId: r.id, revisionStatus: r.status, meta: r.engine.import as ImportMeta, manifestCount: r.manifest.length, createdAt: r.createdAt } : null;
  };
  const importer: ImporterDeps = {
    now: () => new Date("2026-10-10T09:00:00Z"),
    newId: (p) => p + (++n).toString(16).padStart(20, "0"),
    quarantine,
    findByUploadHash: async (u, h) => [...projects.values()].filter((p) => p.userId === u).map((p) => rowOf(p.id)).find((r) => r?.meta.uploadSha256 === h) ?? null,
    getImportRow: async (u, pid) => (projects.get(pid)?.userId === u ? rowOf(pid) : null),
    listImportRows: async (u) => [...projects.values()].filter((p) => p.userId === u).map((p) => rowOf(p.id)!).filter(Boolean),
    createProject: async (i) => { const id = "cp" + (++n).toString(16).padStart(20, "0"); const p = { id, userId: i.userId, namespace: "nx_" + id.slice(-8), title: i.title, rootBuildId: i.rootBuildId }; projects.set(id, p); return p; },
    addImportedRevision: async (pid, i) => {
      const e = validateEngineRecord(i.engine);
      assert.ok(e.ok, JSON.stringify(!e.ok && e.errors));
      assert.ok(validateManifest(i.manifest).ok);
      const r = { id: "rev" + ++n, projectId: pid, seq: revs.filter((x) => x.projectId === pid).length + 1, status: i.status, engine: i.engine, manifest: i.manifest, modBuildId: i.modBuildId, createdAt: new Date() };
      revs.push(r);
      return r;
    },
    setRevisionStatus: async (id, st) => { const r = revs.find((x) => x.id === id)!; assert.equal(r.status, "pending"); r.status = st; },
    createModBuildRow: async (row) => { modBuilds.set(row.id, { id: row.id, userId: row.userId, status: "queued", prompt: row.prompt }); },
    failModBuildRow: async (id) => { modBuilds.get(id)!.status = "failed"; },
    syncModBuild: async (id) => svcState.get(id) ?? { id, status: "queued", error: null, warnings: [], safety: null },
    service: {
      importBuild: async (b) => { svcBodies.push(b); return { id: String(b.id), status: "queued", error: null, warnings: [], safety: null }; },
      get: async (id) => svcState.get(id) ?? null,
    },
    openServerReadOnly: async (u, sid) => (u === "u1" && sid === "srv1" ? { fs: memFs(serverFiles), base: "/opt/mc" } : null),
    fetchArtifact: async () => null,
    validateSpec: (s) => s,
  };
  let flag: boolean | Error = true;
  let user: { id: string; emailVerified: boolean } | null = { id: "u1", emailVerified: true };
  let limited = false;
  const api: ImportApiDeps = {
    importEnabled: async () => { if (flag instanceof Error) throw flag; return flag; },
    currentUser: async () => user,
    rateLimit: () => ({ ok: !limited, retryAfterSec: 30 }),
    inflight: async () => 0,
    versions: ["1.21.11", "1.21.8"],
    importer,
  };
  return { api, importer, projects, revs, modBuilds, svcBodies, svcState, quarantine, serverFiles, setFlag: (f: boolean | Error) => { flag = f; }, setUser: (u: typeof user) => { user = u; }, setLimited: (l: boolean) => { limited = l; } };
}

function memFs(files: Map<string, Buffer>): ReadOnlyServerFs {
  return {
    stat: async (p) => (files.has(p) ? { type: "file", size: files.get(p)!.length } : [...files.keys()].some((k) => k.startsWith(p.replace(/\/$/, "") + "/")) ? { type: "dir", size: 0 } : null),
    readFile: async (p) => files.get(p) ?? null,
    list: async (d) => [...new Set([...files.keys()].filter((k) => k.startsWith(d.replace(/\/$/, "") + "/")).map((k) => k.slice(d.replace(/\/$/, "").length + 1).split("/")[0]))],
  };
}

const ATT = { accepted: "true", typedName: "Dana Demo", textVersion: ATTESTATION_TEXT_VERSION };
function upload(buf: Buffer, name: string, fields: Record<string, string> = ATT, mcVersion = "1.21.11") {
  const fd = new FormData();
  fd.set("file", new Blob([buf]), name);
  fd.set("mcVersion", mcVersion);
  for (const [k, v] of Object.entries(fields)) fd.set(k, v);
  return new Request("http://x/api/cyrus/import", { method: "POST", body: fd });
}
const body = async (r: Response) => ({ status: r.status, ...(await r.json()) });

describe("import API: gates fail closed", () => {
  it("flag off, unreadable flag, no user -> 404 on every route; unverified email -> 403", async () => {
    const w = world();
    for (const f of [false, new Error("db down")] as const) {
      w.setFlag(f);
      assert.equal((await handleList(w.api)).status, 404);
      assert.equal((await handleUpload(upload(DEMO, "d.zip"), w.api)).status, 404);
      assert.equal((await handleGet("cp" + "0".repeat(20), w.api)).status, 404);
      assert.equal((await handleDelete("cp" + "0".repeat(20), w.api)).status, 404);
    }
    w.setFlag(true);
    w.setUser(null);
    assert.equal((await handleUpload(upload(DEMO, "d.zip"), w.api)).status, 404);
    w.setUser({ id: "u1", emailVerified: false });
    assert.equal((await handleUpload(upload(DEMO, "d.zip"), w.api)).status, 403);
    assert.equal(w.quarantine.m.size, 0);
  });
  it("rate limits, size caps, missing file, bad type, bad version, missing attestation", async () => {
    const w = world();
    w.setLimited(true);
    assert.equal((await handleUpload(upload(DEMO, "d.zip"), w.api)).status, 429);
    w.setLimited(false);
    const big = new Request("http://x", { method: "POST", headers: { "content-length": String(30 * 1024 * 1024) }, body: "x" });
    assert.equal((await handleUpload(big, w.api)).status, 413);
    assert.equal((await body(await handleUpload(new Request("http://x", { method: "POST", body: new FormData() }), w.api))).code, "no_file");
    assert.equal((await body(await handleUpload(upload(DEMO, "d.exe"), w.api))).code, "bad_type");
    assert.equal((await body(await handleUpload(upload(DEMO, "d.zip", ATT, "1.7.10"), w.api))).code, "bad_version");
    const noAtt = await body(await handleUpload(upload(DEMO, "d.zip", { typedName: "Dana" }), w.api));
    assert.equal(noAtt.status, 400);
    assert.equal(noAtt.code, "attestation_required");
    assert.equal(w.quarantine.m.size, 0, "nothing stored without an attestation");
  });
});

describe("import API: the source flow", () => {
  const w = world();
  let pid = "";
  it("upload -> quarantine, project + root revision (imported, attestation in metadata), ModBuild row, service base build", async () => {
    const r = await body(await handleUpload(upload(DEMO, "ImportDemo-main.zip", { ...ATT, claimedLicence: "MIT" }), w.api));
    assert.equal(r.status, 201, JSON.stringify(r));
    const v = r.import;
    pid = v.projectId;
    assert.equal(v.kind, "source");
    assert.equal(v.status, "building");
    assert.equal(v.quarantined, true);
    assert.deepEqual(v.licence.detected, ["MIT"]);
    assert.equal(v.licence.effective, "MIT");
    assert.equal(v.sharing.allowed, false, "never shared without explicit consent");
    assert.deepEqual(v.deps.map((d: { id: string }) => d.id), ["placeholderapi", "vault-api"]);
    const rev = w.revs[0];
    assert.equal(rev.seq, 1);
    const meta = rev.engine.import as ImportMeta;
    assert.equal(meta.attestation.typedName, "Dana Demo");
    assert.equal(meta.attestation.textVersion, ATTESTATION_TEXT_VERSION);
    assert.equal(meta.scanProfile, "attested");
    assert.equal(meta.namespace, w.projects.get(pid)!.namespace);
    assert.equal(w.projects.get(pid)!.rootBuildId, meta.modBuildId, "the project is the ModBuild chain's project (assets + changes find it)");
    assert.ok(w.modBuilds.has(meta.modBuildId!));
    const sb = w.svcBodies[0] as { kind: string; files: { path: string }[]; deps: string[]; docs: { path: string }[]; namespace: string };
    assert.equal(sb.kind, "source");
    assert.ok(sb.files.every((f) => /^src\/main\/(java|resources)\//.test(f.path)));
    assert.deepEqual(sb.deps, ["placeholderapi", "vault-api"]);
    assert.equal(sb.namespace, meta.namespace);
    assert.equal(sb.docs.length, 2);
  });
  it("the same bytes again reuse the import (idempotent by upload hash)", async () => {
    const r = await body(await handleUpload(upload(DEMO, "again.zip"), w.api));
    assert.equal(r.status, 200);
    assert.equal(r.reused, true);
    assert.equal(r.import.projectId, pid);
    assert.equal(w.projects.size, 1);
    assert.equal(w.svcBodies.length, 1);
  });
  it("GET syncs the service: ready + revision passed; never 'safe' wording", async () => {
    const mb = (w.revs[0].engine.import as ImportMeta).modBuildId!;
    w.svcState.set(mb, { id: mb, status: "succeeded", error: null, warnings: [], safety: { verdict: "warn", profile: "attested", summary: "Checked with the attested profile: 4 warnings", findings: [{ severity: "warn", rule: "network-http", where: "Metrics", message: "makes HTTP(S) requests" }] } });
    const r = await body(await handleGet(pid, w.api));
    assert.equal(r.import.status, "ready");
    assert.equal(r.import.revisionStatus, "passed");
    assert.equal(r.import.scan.summary, "Checked with the attested profile: 4 warnings");
    assert.equal(w.revs[0].status, "passed");
  });
  it("list shows it; another account cannot see it; DELETE removes the quarantined bytes only", async () => {
    const l = await body(await handleList(w.api));
    assert.equal(l.imports.length, 1);
    assert.equal(l.attestation.textVersion, ATTESTATION_TEXT_VERSION);
    w.setUser({ id: "u2", emailVerified: true });
    assert.equal((await handleGet(pid, w.api)).status, 404);
    assert.equal((await handleDelete(pid, w.api)).status, 404);
    w.setUser({ id: "u1", emailVerified: true });
    assert.equal((await handleDelete(pid, w.api)).status, 200);
    assert.equal(w.quarantine.m.size, 0);
    assert.equal((await body(await handleGet(pid, w.api))).import.quarantined, false);
    const again = await body(await handleUpload(upload(DEMO, "again.zip"), w.api));
    assert.equal(again.reused, true);
    assert.equal(again.import.quarantined, true, "re-uploading the same bytes re-quarantines them");
  });
});

describe("import API: refusals, jars, packs, conflicts", () => {
  it("unsupported input is refused with what + why, and its quarantined bytes are removed", async () => {
    const w = world();
    const kt = zip([{ name: "src/main/resources/plugin.yml", data: "name: K\nversion: 1\nmain: a.K\n" }, { name: "src/main/kotlin/a/K.kt", data: "class K" }, { name: "src/main/java/a/K.java", data: "package a;\npublic class K extends org.bukkit.plugin.java.JavaPlugin {}" }]);
    const r = await body(await handleUpload(upload(kt, "k.zip"), w.api));
    assert.equal(r.status, 422);
    assert.equal(r.code, "unsupported");
    assert.match(r.error, /unsupported: Kotlin/);
    assert.equal(w.quarantine.m.size, 0);
    assert.equal(w.projects.size, 0);
    const bomb = zip([{ name: "src/main/java/a/B.java", data: Buffer.alloc(30 * 1024 * 1024), method: 8 }]);
    assert.equal((await handleUpload(upload(bomb, "b.zip"), w.api)).status, 422);
  });
  it("a jar is analysed by the service (no ModBuild row); GET -> analysed", async () => {
    const w = world();
    const jar = readFileSync(path.join(FX, "cyrus-r2/TfClashB-1.0.0.jar"));
    const r = await body(await handleUpload(upload(jar, "TfClashB-1.0.0.jar"), w.api));
    assert.equal(r.status, 201, JSON.stringify(r));
    assert.equal(r.import.kind, "jar");
    assert.equal(w.modBuilds.size, 0);
    const sb = w.svcBodies[0] as { kind: string; id: string; files: { path: string }[] };
    assert.equal(sb.kind, "jar");
    assert.ok(sb.files.every((f) => f.path.endsWith(".class") || f.path === "plugin.yml"));
    assert.equal(r.import.sharing.allowed, false);
    w.svcState.set(sb.id, { id: sb.id, status: "succeeded", error: null, warnings: [], safety: { verdict: "warn", profile: "attested", summary: "Checked with the attested profile: 0 warnings", findings: [] } });
    assert.equal((await body(await handleGet(r.import.projectId, w.api))).import.status, "analysed");
    // conflicts against a server that already runs TfClashA (same command + permission)
    w.serverFiles.set("/opt/mc/plugins/TfClashA-1.0.0.jar", readFileSync(path.join(FX, "cyrus-r2/TfClashA-1.0.0.jar")));
    w.serverFiles.set("/opt/mc/server.properties", Buffer.from("level-name=world\n"));
    const c = await body(await handleConflicts(r.import.projectId, new Request("http://x", { method: "POST", body: JSON.stringify({ serverId: "srv1" }) }), w.api));
    assert.equal(c.status, 200, JSON.stringify(c));
    assert.ok(c.report.findings.some((f: { class: string }) => /command/.test(f.class)), JSON.stringify(c.report.findings.map((f: { class: string }) => f.class)));
    assert.equal((await handleConflicts(r.import.projectId, new Request("http://x", { method: "POST", body: JSON.stringify({ serverId: "other" }) }), w.api)).status, 404);
  });
  it("datapacks are done at upload (no service call)", async () => {
    const w = world();
    const dp = zip([{ name: "pack.mcmeta", data: JSON.stringify({ pack: { pack_format: 48, description: "Demo" } }) }, { name: "data/demo/function/hi.mcfunction", data: "say hi" }]);
    const r = await body(await handleUpload(upload(dp, "dp.zip"), w.api));
    assert.equal(r.status, 201);
    assert.equal(r.import.status, "ready");
    assert.equal(w.svcBodies.length, 0);
    assert.equal(w.revs[0].status, "passed");
  });
  it("a service that refuses the hand-off fails the ModBuild row and the revision", async () => {
    const w = world();
    w.importer.service.importBuild = async () => { throw new Error("offline"); };
    const r = await body(await handleUpload(upload(DEMO, "d.zip"), w.api));
    assert.equal(r.status, 201);
    assert.equal(r.import.status, "failed");
    assert.equal([...w.modBuilds.values()][0].status, "failed");
  });
});

