import path from "node:path";

/**
 * DB-backed checks of the Cyrus engine store (lib/cyrus/engine-core/store.ts) against a THROWAWAY Postgres:
 * append-only revisions, parent chain, last passing revision, diffs, revert-by-new-revision, the immutability
 * trigger from the manual migration, namespace uniqueness under concurrency and the identifier registry.
 *
 * Opt-in and fail-closed: runs only when CYRUS_ENGINE_DB_TEST=1 and DATABASE_URL is a node-2 agent database
 * (127.0.0.1:5433/wt_*). Schema first: `devhost db push`.
 *   devhost run --lock -- env CYRUS_ENGINE_DB_TEST=1 npx tsx --test test/cyrus-engine-store-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_ENGINE_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_ENGINE_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let S: typeof import("../lib/cyrus/engine-core/store.ts");
let I: typeof import("../lib/cyrus/engine-core/identifiers.ts");
const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const userId = `cyeng-${uniq}`;
const h = (c: string) => c.repeat(64);
const file = (p: string, c: string, role = "source") => ({ path: p, sha256: h(c), role });
const spec = (namespace: string, extra: Record<string, unknown> = {}) => ({
  schemaVersion: 1, game: "minecraft", target: { version: "1.21.11" }, namespace, summary: "A coin shop with a chest menu",
  routes: ["plugin"], requirements: [{ id: "REQ-1", text: "Players can buy items for coins" }],
  tests: [{ id: "T-1", kind: "compile", description: "compiles", covers: ["REQ-1"] }], install: { side: "server", restartRequired: true }, ...extra,
});
const msg = async (p: Promise<unknown>) => { try { await p; return "ok"; } catch (e) { return String((e as Error).message); } };
const code = async (p: Promise<unknown>) => { try { await p; return "ok"; } catch (e) { return (e as { code?: string }).code ?? (e as Error).message; } };

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  S = await import("../lib/cyrus/engine-core/store.ts");
  I = await import("../lib/cyrus/engine-core/identifiers.ts");
  // The trigger section of the manual migration (db push does not create triggers).

