type RevRow = { id: string; projectId: string; status: string; engine: unknown; manifest: unknown; createdAt: Date };
type ProjRow = { id: string; namespace: string; title: string | null };
const toRow = (p: ProjRow, r: RevRow): ImportRow => ({
  projectId: p.id, namespace: p.namespace, title: p.title, revisionId: r.id, revisionStatus: r.status,
  meta: (r.engine as { import: ImportMeta }).import, manifestCount: Array.isArray(r.manifest) ? r.manifest.length : 0, createdAt: r.createdAt,
});

async function firstImported(projectIds: string[], extra: Record<string, unknown> = {}): Promise<RevRow[]> {
  if (!projectIds.length) return [];
  return db.cyrusRevision.findMany({ where: { projectId: { in: projectIds }, kind: "imported", seq: 1, ...extra }, orderBy: { createdAt: "desc" } }) as unknown as RevRow[];
}

function svcViewOfRow(row: { id: string; status: string; error: string | null; result: unknown; jarName: string | null; jarSize: number | null; jarSha256: string | null }): SvcView {
  const res = (row.result ?? {}) as { warnings?: string[]; safety?: SvcView["safety"]; errorDetail?: string | null };
  return { id: row.id, status: row.status, error: row.error, errorDetail: res.errorDetail ?? null, warnings: res.warnings ?? [], safety: res.safety ?? null, jar: row.jarName ? { name: row.jarName, size: row.jarSize ?? 0, sha256: row.jarSha256 ?? "" } : null };
}

export function dbImporterDeps(o: { service: ImporterDeps["service"]; quarantine: QuarantineStore; syncModBuild: ImporterDeps["syncModBuild"] }): ImporterDeps {
  return {
  now: () => new Date(),
  newId: (prefix) => prefix + randomBytes(10).toString("hex"),
  quarantine: o.quarantine,
  async findByUploadHash(userId, sha256) {
    const projects = await db.cyrusProject.findMany({ where: { userId }, select: { id: true, namespace: true, title: true } });
    const revs = await firstImported(projects.map((p) => p.id), { engine: { path: ["import", "uploadSha256"], equals: sha256 } });
    const r = revs[0];
    return r ? toRow(projects.find((p) => p.id === r.projectId)!, r) : null;
  },
  async getImportRow(userId, projectId) {
    const p = await db.cyrusProject.findFirst({ where: { id: projectId, userId }, select: { id: true, namespace: true, title: true } });
    if (!p) return null;
    const [r] = await firstImported([p.id]);
    return r ? toRow(p, r) : null;
  },
  async listImportRows(userId) {
    const projects = await db.cyrusProject.findMany({ where: { userId }, select: { id: true, namespace: true, title: true }, orderBy: { createdAt: "desc" }, take: 500 });
    const revs = await firstImported(projects.map((p) => p.id));
    return revs.map((r) => toRow(projects.find((p) => p.id === r.projectId)!, r));
  },
  createProject: (i) => createProject(i),
  async addImportedRevision(projectId, i) {
    const r = await addRevision(projectId, { kind: "imported", manifest: i.manifest, spec: i.spec ?? undefined, modBuildId: i.modBuildId, engine: i.engine as never, status: i.status, message: i.message, expectedHeadId: null });
    return { id: r.id, seq: r.seq, status: r.status };
  },
  async setRevisionStatus(id, status) { await setRevisionStatus(id, status); },
  async createModBuildRow(row) {
    await db.modBuild.create({ data: { id: row.id, userId: row.userId, prompt: row.prompt, mcVersion: row.mcVersion, pluginName: row.pluginName, rootBuildId: row.id, ...(row.title ? { cyrus: { title: row.title } } : {}) } });
  },
  async failModBuildRow(id, message) {
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: message, finishedAt: new Date() } });
  },
  syncModBuild: o.syncModBuild,
  service: o.service,
  validateSpec(spec) {
    const v = validateModSpec(spec, { adapterFor: getAdapter });
    return v.ok ? v.spec : null;
  },
  };
}

