// REAL Cyrus import runs ON node-2 (not part of the unit suite: real javac, real build service, real Paper boots).
//   scripts/devhost run --lock -- npx tsx test/cyrus-import-real.ts [--out results.json]
// No real client and no AI model are used: the import path has no model call, and nothing connects to the servers.
// Steps: verify the allowlist jars (sha256/sha1/size) -> start the REAL services/modbuilder/server.js with JDK 21 (and the
// Test Flight JDK 25 for a 26.2 build) against the resolved Paper classpaths -> portal ingestion of the realistic fixture
// project (test/fixtures/cyrus-import/demo-src) -> POST /imports -> base build -> check the attested scan (warnings, no
// blocks) and the jar -> Test Flight boots on 1.21.11 and 26.2 (one at a time, busy backoff) -> the exec fixture stays blocked.
import { createHash } from "node:crypto";
import { execFileSync, spawn } from "node:child_process";
import { copyFileSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { zipDir } from "./_zipwriter";
import { ingestUpload, type IngestOk } from "../lib/cyrus/import/ingest";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const RUN = `${T}/cyrus-import-real/run-${Date.now().toString(36)}`;
const JDK21 = `${T}/testflight/jdk/21`;
const JDK25 = `${T}/testflight/jdk/25`;
const DEPS = `${T}/cyrus-import-deps`;
const KEY = "real-run-key-" + createHash("sha256").update(String(Math.random())).digest("hex").slice(0, 24);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {});
    child.stdin.end(opts.input ?? undefined);
  }),
};

async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

async function main() {
  const oi = process.argv.indexOf("--out");
  const out: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, aiModel: "none (the import path makes no model call)" };
  // 1. allowlist jars: verified against deps.json (sha256 + sha1 + size); nothing is downloaded when they are present.
  out.depsVerify = execFileSync(process.execPath, [path.join(ROOT, "services/modbuilder/tools/fetch-import-deps.js"), path.join(ROOT, "lib/cyrus/import/deps.json"), DEPS], { encoding: "utf8" }).trim().split("\n");
  // 2. the real service
  mkdirSync(`${RUN}/cp`, { recursive: true });
  copyFileSync(`${T}/testflight/classpath/1.21.11.txt`, `${RUN}/cp/1.21.11.txt`);
  copyFileSync(`${T}/r0-26x/classpath/26.2.txt`, `${RUN}/cp/26.2.txt`);
  // Test-only registry override: 26.2 is "preview" (not buildable) in the shipped registry; this run builds it with JDK 25.
  const reg = JSON.parse(readFileSync(path.join(ROOT, "lib/cyrus/versions/registry.json"), "utf8"));
  for (const v of reg.versions) if (v.id === "26.2") v.buildable = true;
  writeFileSync(`${RUN}/registry.json`, JSON.stringify(reg));
